      ctx.vars.content += `├──────────────────────────────────────────────────┤\n`;
      ctx.vars.content += `│  Security (risk, permissions, vault, pairing)    │\n`;
      ctx.vars.content += `├──────────────────────────────────────────────────┤\n`;
      ctx.vars.content += `│  Tools (system, file, browser, auth, download,   │\n`;
