// ─── Pipeline: deploy-package ───────────────────────────────────────────────

function deployPackagePipeline() {
  return new Pipeline('deploy-package')
    .step('create-pkg-dir', (ctx) => {
      ctx.vars.target = path.join(PROJECT_ROOT, 'dist');
      ctx = ops.mkdir(ctx);
      return ctx;
    })
    .step('copy-backend', (ctx) => {
      ctx.vars.command = process.platform === 'win32'
        ? `xcopy "${BACKEND}" "${path.join(PROJECT_ROOT, 'dist', 'backend')}" /E /I /Q`
        : `cp -r "${BACKEND}" "${path.join(PROJECT_ROOT, 'dist', 'backend')}"`;
      ctx = ops.exec(ctx);
      return ctx;
    })
    .step('copy-frontend', (ctx) => {
      ctx.vars.command = process.platform === 'win32'
        ? `xcopy "${FRONTEND}" "${path.join(PROJECT_ROOT, 'dist', 'frontend')}" /E /I /Q`
        : `cp -r "${FRONTEND}" "${path.join(PROJECT_ROOT, 'dist', 'frontend')}"`;
      ctx = ops.exec(ctx);
      return ctx;
    })
    .step('copy-root-files', (ctx) => {
      const rootFiles = ['README.md', 'start.bat', 'start.sh'];
      for (const f of rootFiles) {
        const src = path.join(PROJECT_ROOT, f);
        if (require('fs').existsSync(src)) {
          ctx.vars.source = src;
          ctx.vars.target = path.join(PROJECT_ROOT, 'dist', f);
          ctx = ops.copyFile(ctx);
        }
      }
      return ctx;
    })
    .step('copy-datasets', (ctx) => {
      ctx.vars.command = process.platform === 'win32'
        ? `xcopy "${path.join(DATA, 'datasets')}" "${path.join(PROJECT_ROOT, 'dist', 'data', 'datasets')}" /E /I /Q`
        : `cp -r "${path.join(DATA, 'datasets')}" "${path.join(PROJECT_ROOT, 'dist', 'data', 'datasets')}"`;
      ctx = ops.exec(ctx);
      return ctx;
    })
    .onComplete((ctx) => {
      console.log(`\n✅ Package deployed to dist/ (${ctx.results.length} operations)`);
    });
}

// ─── Pipeline: batch-convert ────────────────────────────────────────────────

function batchConvertPipeline(sourceDir, targetDir, extension) {
  return new Pipeline('batch-convert')
    .step('scan', (ctx) => {
      ctx.vars.pattern = `**/*${extension}`;
      ctx.vars.searchPath = sourceDir;
      ctx = ops.glob(ctx);
      ctx.vars.filesToConvert = (ctx.vars.matches || []).slice();
      return ctx;
    })
    .step('ensure-target', (ctx) => {
      ctx.vars.target = targetDir;
      ctx = ops.mkdir(ctx);
      return ctx;
    })
    .step('convert', (ctx) => {
      for (const file of (ctx.vars.filesToConvert || [])) {
        const basename = path.basename(file);
        ctx.vars.source = file;
        ctx.vars.target = path.join(targetDir, basename);
        ctx = ops.copyFile(ctx);
      }
      return ctx;
    })
    .onComplete((ctx) => {
      console.log(`\n✅ Batch convert: ${ctx.results.length} files converted`);
    });
}

