// BROWSER DOMAIN PIPELINES (Phase 2 — Session)
// ════════════════════════════════════════════════════════════════════════════
//
// Browser session pipelines — control the lifecycle of a browser instance.
// All pipelines use the planning-engine execution graph schema with
// verification, recovery, risk, and confidence metadata.
//
// Pipelines:
//   browser-launch          — Open a fresh browser instance
//   browser-close           — Close the active browser instance
//   browser-restart         — Close then re-launch the browser
//   browser-detect          — Detect whether a browser is currently running
//   browser-attach          — Attach to an existing browser session
//

/**
 * Graph pipeline: browser-launch
 * Launches a fresh browser instance and verifies it is ready.
 */
function browserLaunchGraph(browserName = 'chrome') {
  return {
    name: 'browser-launch-graph',
    nodes: [
      buildNode({
        id: 'observe_existing',
        type: NODE_TYPES.OBSERVE,
        objective: 'Check if a browser is already running',
        preferred_skill: 'process.detect',
        parameters: { name: browserName },
        expected_result: 'Process state for browser',
        verification: { method: 'returns_object', success: 'result has running field' },
        recovery: ['Assume no browser running'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 1,
        confidence: 0.95,
      }),
      buildNode({
        id: 'decide_launch',
        type: NODE_TYPES.DECIDE,
        objective: 'Decide whether to launch fresh or reuse existing',
        dependencies: ['observe_existing'],
        parameters: { strategy: 'launch_fresh' },
        expected_result: 'Launch decision',
        verification: { method: 'returns_string', success: 'result is launch or reuse' },
        recovery: ['Default to launch'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 1,
        confidence: 0.95,
      }),
      buildNode({
        id: 'launch_browser',
        type: NODE_TYPES.ACT,
        objective: `Launch ${browserName} browser`,
        dependencies: ['decide_launch'],
        preferred_skill: 'browser.open',
        parameters: { url: 'about:blank', browser: browserName },
        expected_result: 'Browser window opened',
        verification: { method: 'process_running', success: 'browser process is active' },
        recovery: ['Retry launch', 'Use system default browser'],
        risk: RISK_LEVELS.SAFE_LOCAL,
        estimated_duration: 3,
        confidence: 0.9,
      }),
      buildNode({
        id: 'verify_browser_ready',
        type: NODE_TYPES.VERIFY,
        objective: 'Verify browser is responsive',
        dependencies: ['launch_browser'],
        verification: { method: 'dom_loaded', success: 'about:blank page loaded' },
        recovery: ['Wait and retry', 'Re-launch browser'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 2,
        confidence: 0.9,
      }),
      buildNode({
        id: 'finish',
        type: NODE_TYPES.FINISH,
        objective: 'Browser launch complete',
        dependencies: ['verify_browser_ready'],
        verification: { method: 'always', success: 'true' },
        recovery: ['No-op'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 0,
        confidence: 1.0,
      }),
    ],
  };
}

