// ════════════════════════════════════════════════════════════════════════════
// BROWSER DOMAIN PIPELINES (Phase 2 — Search)
// ════════════════════════════════════════════════════════════════════════════
//
// Browser search pipelines — perform searches on various search engines.
// All pipelines use the planning-engine execution graph schema with
// verification, recovery, risk, and confidence metadata.
//
// Pipelines:
//   browser-search-google       — Search Google
//   browser-search-bing         — Search Bing
//   browser-search-duckduckgo   — Search DuckDuckGo
//   browser-search-youtube      — Search YouTube
//   browser-search-github       — Search GitHub
//

/**
 * Generic search pipeline factory.
 * Builds a graph for searching a specific engine.
 */
function _browserSearchGraph(engineName, searchUrl, query) {
  return {
    name: `browser-search-${engineName}-graph`,
    nodes: [
      buildNode({
        id: 'observe_browser',
        type: NODE_TYPES.OBSERVE,
        objective: 'Verify browser session is active',
        preferred_skill: 'browser.status',
        parameters: {},
        expected_result: 'Browser session state',
        verification: { method: 'returns_object', success: 'result has active field' },
        recovery: ['Launch browser first'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 1,
        confidence: 0.95,
      }),
      buildNode({
        id: 'build_search_url',
        type: NODE_TYPES.DECIDE,
        objective: `Build ${engineName} search URL`,
        dependencies: ['observe_browser'],
        parameters: { base: searchUrl, query },
        expected_result: 'Full search URL',
        verification: { method: 'returns_string', success: 'result is valid URL with query' },
        recovery: ['Use URL as-is'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 1,
        confidence: 0.95,
      }),
      buildNode({
        id: 'navigate_search',
        type: NODE_TYPES.ACT,
        objective: `Navigate to ${engineName} search results`,
        dependencies: ['build_search_url'],
        preferred_skill: 'browser.open',
        parameters: { url: searchUrl + encodeURIComponent(query) },
        expected_result: 'Search results page loaded',
        verification: { method: 'dom_loaded', success: 'document.readyState === complete' },
        recovery: ['Retry navigation', 'Use system browser fallback'],
        risk: RISK_LEVELS.EXTERNAL,
        estimated_duration: 5,
        confidence: 0.9,
      }),
      buildNode({
        id: 'verify_results',
        type: NODE_TYPES.VERIFY,
        objective: `Verify ${engineName} search results are visible`,
        dependencies: ['navigate_search'],
        verification: { method: 'results_visible', success: 'search result elements present' },
        recovery: ['Wait and retry', 'Log warning'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 2,
        confidence: 0.85,
      }),
      buildNode({
        id: 'finish',
        type: NODE_TYPES.FINISH,
        objective: `${engineName} search complete`,
        dependencies: ['verify_results'],
        verification: { method: 'always', success: 'true' },
        recovery: ['No-op'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 0,
        confidence: 1.0,
      }),
    ],
  };
}

/**
 * Graph pipeline: browser-search-google
 * Performs a Google search.
 */
function browserSearchGoogleGraph(query) {
  return _browserSearchGraph('google', 'https://www.google.com/search?q=', query);
}

/**
 * Graph pipeline: browser-search-bing
 * Performs a Bing search.
 */
function browserSearchBingGraph(query) {
  return _browserSearchGraph('bing', 'https://www.bing.com/search?q=', query);
}

/**
 * Graph pipeline: browser-search-duckduckgo
 * Performs a DuckDuckGo search.
 */
function browserSearchDuckduckgoGraph(query) {
  return _browserSearchGraph('duckduckgo', 'https://duckduckgo.com/?q=', query);
}

/**
 * Graph pipeline: browser-search-youtube
 * Performs a YouTube search.
 */
function browserSearchYoutubeGraph(query) {
  return _browserSearchGraph('youtube', 'https://www.youtube.com/results?search_query=', query);
}

/**
 * Graph pipeline: browser-search-github
 * Performs a GitHub search.
 */
function browserSearchGithubGraph(query) {
  return _browserSearchGraph('github', 'https://github.com/search?q=', query);
}

