// BROWSER DOMAIN PIPELINES (Phase 2 — Downloads)
// ════════════════════════════════════════════════════════════════════════════
//
// Browser download pipelines — manage file downloads from the browser.
// All pipelines use the planning-engine execution graph schema with
// verification, recovery, risk, and confidence metadata.
//
// Pipelines:
//   browser-download-file    — Download a file from a URL
//   browser-verify-download  — Verify a downloaded file (size, hash, type)
//   browser-cancel-download  — Cancel an in-progress download
//

/**
 * Graph pipeline: browser-download-file
 * Downloads a file from a URL to the local downloads directory.
 */
function browserDownloadFileGraph(url, filename = null) {
  return {
    name: 'browser-download-file-graph',
    nodes: [
      buildNode({
        id: 'observe_browser',
        type: NODE_TYPES.OBSERVE,
        objective: 'Verify browser session is active',
        preferred_skill: 'browser.status',
        parameters: {},
        expected_result: 'Browser session state',
        verification: { method: 'returns_object', success: 'result has active field' },
        recovery: ['Launch browser first'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 1,
        confidence: 0.95,
      }),
      buildNode({
        id: 'check_url_safety',
        type: NODE_TYPES.DECIDE,
        objective: 'Check URL safety (domain, extension)',
        dependencies: ['observe_browser'],
        parameters: { url },
        expected_result: 'Safety verdict',
        verification: { method: 'returns_string', success: 'result is safe or unsafe' },
        recovery: ['Mark as unsafe if check fails'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 1,
        confidence: 0.9,
      }),
      buildNode({
        id: 'approval_request',
        type: NODE_TYPES.APPROVAL,
        objective: 'Request approval for download (if executable)',
        dependencies: ['check_url_safety'],
        parameters: { action: 'download', target: url },
        expected_result: 'Approval decision',
        verification: { method: 'returns_string', success: 'result is approved or denied' },
        recovery: ['Default to deny for unsafe files'],
        risk: RISK_LEVELS.EXTERNAL,
        estimated_duration: 5,
        confidence: 0.9,
      }),
      buildNode({
        id: 'prepare_download_dir',
        type: NODE_TYPES.ACT,
        objective: 'Ensure downloads directory exists',
        dependencies: ['approval_request'],
        preferred_skill: 'fs.mkdir',
        parameters: { path: path.join(DATA, 'downloads') },
        expected_result: 'Downloads directory ready',
        verification: { method: 'dir_exists', success: 'downloads directory exists' },
        recovery: ['Create directory'],
        risk: RISK_LEVELS.SAFE_LOCAL,
        estimated_duration: 1,
        confidence: 0.95,
      }),
      buildNode({
        id: 'download_file',
        type: NODE_TYPES.ACT,
        objective: `Download file from ${url}`,
        dependencies: ['prepare_download_dir'],
        preferred_skill: 'browser.download',
        parameters: { url, filename },
        expected_result: 'File downloaded',
        verification: { method: 'file_exists', success: 'downloaded file exists in downloads dir' },
        recovery: ['Retry download', 'Use curl fallback'],
        risk: RISK_LEVELS.EXTERNAL,
        estimated_duration: 30,
        confidence: 0.85,
      }),
      buildNode({
        id: 'verify_download',
        type: NODE_TYPES.VERIFY,
        objective: 'Verify download completed (file exists, size > 0)',
        dependencies: ['download_file'],
        verification: { method: 'file_exists', success: 'file exists and size > 0' },
        recovery: ['Retry download', 'Log warning'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 2,
        confidence: 0.9,
      }),
      buildNode({
        id: 'finish',
        type: NODE_TYPES.FINISH,
        objective: 'Download complete',
        dependencies: ['verify_download'],
        verification: { method: 'always', success: 'true' },
        recovery: ['No-op'],
        risk: RISK_LEVELS.READ_ONLY,
        estimated_duration: 0,
        confidence: 1.0,
      }),
    ],
  };
}

