/**
 * Graph pipeline: research-collect (planning-engine version)
 * Demonstrates parallel branches for multi-site research.
 */
function researchCollectGraph(query, maxSites = 5) {
  const searchNode = buildNode({
    id: 'search_web',
    type: NODE_TYPES.ACT,
    objective: `Search the web for: ${query}`,
    preferred_skill: 'browser.search',
    parameters: { query },
    expected_result: 'Search results page loaded',
    verification: { method: 'results_visible', success: 'search result elements present' },
    recovery: ['Retry with different search engine', 'Open URL directly'],
    risk: RISK_LEVELS.EXTERNAL,
    estimated_duration: 5,
    confidence: 0.9,
  });

  const visitNodes = [];
  for (let i = 0; i < maxSites; i++) {
    visitNodes.push(buildNode({
      id: `visit_site_${i + 1}`,
      type: NODE_TYPES.ACT,
      objective: `Visit result site ${i + 1}`,
      dependencies: ['search_web'],
      preferred_skill: 'browser.open',
      parameters: { url: '', index: i },
      expected_result: 'Site loaded',
      verification: { method: 'dom_loaded', success: 'document.readyState === complete' },
      recovery: ['Skip this site', 'Try next result'],
      risk: RISK_LEVELS.EXTERNAL,
      estimated_duration: 5,
      confidence: 0.85,
    }));
  }

  const extractNode = buildNode({
    id: 'extract_text',
    type: NODE_TYPES.ACT,
    objective: 'Extract text from visited sites',
    dependencies: visitNodes.map(n => n.id),
    preferred_skill: 'browser.extract_text',
    parameters: {},
    expected_result: 'Combined text corpus',
    verification: { method: 'returns_string', success: 'result length > 100' },
    recovery: ['Use partial extraction', 'Retry with OCR fallback'],
    risk: RISK_LEVELS.READ_ONLY,
    estimated_duration: 10,
    confidence: 0.85,
  });

  const saveNode = buildNode({
    id: 'save_report',
    type: NODE_TYPES.ACT,
    objective: 'Save research report to file',
    dependencies: ['extract_text'],
    preferred_skill: 'file.write',
    parameters: { path: path.join(DATA, 'research', `${Date.now()}_${query.replace(/\s+/g, '_')}.txt`) },
    expected_result: 'Report file written',
    verification: { method: 'file_exists', success: 'file exists and size > 0' },
    recovery: ['Retry once', 'Save to alternate path'],
    risk: RISK_LEVELS.LOCAL_DESTRUCTIVE,
    estimated_duration: 2,
    confidence: 0.95,
  });

  return {
    name: 'research-collect-graph',
    nodes: [searchNode, ...visitNodes, extractNode, saveNode, buildNode({
      id: 'finish',
      type: NODE_TYPES.FINISH,
      objective: 'Research complete',
      dependencies: ['save_report'],
      verification: { method: 'always', success: 'true' },
      recovery: ['No-op'],
      risk: RISK_LEVELS.READ_ONLY,
      estimated_duration: 0,
      confidence: 1.0,
    })],
  };
}

