// ============================================================================
// PHASE 5 — INTENT ENGINE
// ============================================================================
// 10 utility classes for converting user requests into executable intents:
//   1. IntentClassifier       - Intent classification
//   2. EntityExtractor        - Entity extraction
//   3. ParameterExtractor     - Parameter extraction
//   4. SlotFiller             - Slot filling
//   5. ConfidenceScorer       - Confidence scoring
//   6. ContextEnricher        - Context enrichment
//   7. PipelineSelector       - Pipeline selection
//   8. IntentNormalizer       - Intent normalization
//   9. MultiIntentSplitter    - Multi-intent splitting
//  10. IntentHistory          - Intent history
// ============================================================================

// 1. IntentClassifier — Intent classification
class IntentClassifier {
  constructor(options = {}) {
    this.options = {
      minConfidence: options.minConfidence || 0.5,
      ...options,
    };
    this.intents = new Map();
    this.patterns = [];
  }

  registerIntent(name, definition) {
    this.intents.set(name, {
      name,
      patterns: definition.patterns || [],
      keywords: definition.keywords || [],
      examples: definition.examples || [],
      domain: definition.domain || 'general',
      ...definition,
    });
    for (const pattern of definition.patterns || []) {
      this.patterns.push({ intent: name, pattern, regex: new RegExp(pattern, 'i') });
    }
    return this;
  }

  classify(text) {
    const scores = [];
    for (const [name, intent] of this.intents.entries()) {
      let score = 0;
      let matches = 0;
      for (const { regex, intent: intentName } of this.patterns) {
        if (intentName === name && regex.test(text)) {
          score += 0.5;
          matches++;
        }
      }
      for (const keyword of intent.keywords || []) {
        if (text.toLowerCase().includes(keyword.toLowerCase())) {
          score += 0.2;
          matches++;
        }
      }
      if (matches > 0) {
        scores.push({ intent: name, score: Math.min(score, 1.0), matches, domain: intent.domain });
      }
    }
    scores.sort((a, b) => b.score - a.score);
    const top = scores[0];
    if (!top || top.score < this.options.minConfidence) {
      return { intent: null, confidence: 0, alternatives: scores };
    }
    return {
      intent: top.intent,
      confidence: top.score,
      domain: top.domain,
      alternatives: scores.slice(1, 4),
    };
  }

  listIntents() {
    return Array.from(this.intents.keys());
  }

  getIntent(name) {
    return this.intents.get(name) || null;
  }
}

// 2. EntityExtractor — Entity extraction
class EntityExtractor {
  constructor(options = {}) {
    this.options = options;
    this.entityTypes = new Map();
  }

  registerType(type, definition) {
    this.entityTypes.set(type, {
      type,
      pattern: definition.pattern ? new RegExp(definition.pattern, 'gi') : null,
      extractor: definition.extractor || null,
      validator: definition.validator || null,
      ...definition,
    });
    return this;
  }

  extract(text, types = null) {
    const targetTypes = types || Array.from(this.entityTypes.keys());
    const entities = [];
    for (const type of targetTypes) {
      const def = this.entityTypes.get(type);
      if (!def) continue;
      if (def.pattern) {
        const matches = text.matchAll(def.pattern);
        for (const match of matches) {
          entities.push({
            type,
            value: match[0],
            groups: match.groups || {},
            index: match.index,
            valid: def.validator ? def.validator(match[0]) : true,
          });
        }
      } else if (def.extractor) {
        const extracted = def.extractor(text);
        if (extracted) {
          entities.push({
            type,
            value: extracted,
            valid: def.validator ? def.validator(extracted) : true,
          });
        }
      }
    }
    return entities;
  }

  extractByType(text, type) {
    return this.extract(text, [type]);
  }

  listTypes() {
    return Array.from(this.entityTypes.keys());
  }
}

// 3. ParameterExtractor — Parameter extraction
class ParameterExtractor {
  constructor(options = {}) {
    this.options = options;
    this.schemas = new Map();
  }

  registerSchema(intent, schema) {
    this.schemas.set(intent, schema);
    return this;
  }

  extract(intent, text, entities = []) {
    const schema = this.schemas.get(intent);
    if (!schema) return {};
    const params = {};
    for (const [name, def] of Object.entries(schema)) {
      if (def.fromEntity) {
        const entity = entities.find(e => e.type === def.fromEntity);
        if (entity) params[name] = entity.value;
      } else if (def.pattern) {
        const regex = new RegExp(def.pattern, 'i');
        const match = text.match(regex);
        if (match && match[1] !== undefined) {
          params[name] = def.transform ? def.transform(match[1]) : match[1];
        } else if (def.default !== undefined) {
          params[name] = def.default;
        }
      } else if (def.default !== undefined) {
        params[name] = def.default;
      }
    }
    return params;
  }

  validate(intent, params) {
    const schema = this.schemas.get(intent);
    if (!schema) return { valid: true, errors: [] };
    const errors = [];
    for (const [name, def] of Object.entries(schema)) {
      if (def.required && (params[name] === undefined || params[name] === null)) {
        errors.push(`Missing required parameter: ${name}`);
      }
      if (def.validate && params[name] !== undefined) {
        if (!def.validate(params[name])) {
          errors.push(`Invalid value for parameter: ${name}`);
        }
      }
    }
    return { valid: errors.length === 0, errors };
  }

  getSchema(intent) {
    return this.schemas.get(intent) || null;
  }

  listSchemas() {
    return Array.from(this.schemas.keys());
  }
}

// 4. SlotFiller — Slot filling
class SlotFiller {
  constructor(options = {}) {
    this.options = {
      maxQuestions: options.maxQuestions || 5,
      ...options,
    };
    this.slots = new Map();
    this.dialogs = new Map();
  }

  defineSlots(intent, slotDefs) {
    this.slots.set(intent, slotDefs);
    return this;
  }

  fill(intent, providedValues = {}) {
    const slotDefs = this.slots.get(intent);
    if (!slotDefs) return { filled: {}, missing: [], complete: true };
    const filled = {};
    const missing = [];
    for (const [name, def] of Object.entries(slotDefs)) {
      if (providedValues[name] !== undefined) {
        filled[name] = providedValues[name];
      } else if (def.default !== undefined) {
        filled[name] = def.default;
      } else if (def.required) {
        missing.push({ name, prompt: def.prompt || `Please provide ${name}`, type: def.type });
      }
    }
    return {
      filled,
      missing,
      complete: missing.length === 0,
    };
  }

  startDialog(intent, providedValues = {}) {
    const dialogId = `dlg_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
    const result = this.fill(intent, providedValues);
    this.dialogs.set(dialogId, {
      id: dialogId,
      intent,
      filled: result.filled,
      missing: result.missing,
      questionIndex: 0,
      complete: result.complete,
    });
    return this.dialogs.get(dialogId);
  }

  answerQuestion(dialogId, value) {
    const dialog = this.dialogs.get(dialogId);
    if (!dialog) return null;
    if (dialog.questionIndex >= dialog.missing.length) return dialog;
    const slot = dialog.missing[dialog.questionIndex];
    dialog.filled[slot.name] = value;
    dialog.questionIndex++;
    if (dialog.questionIndex >= dialog.missing.length) {
      dialog.complete = true;
    }
    return dialog;
  }

  getCurrentQuestion(dialogId) {
    const dialog = this.dialogs.get(dialogId);
    if (!dialog || dialog.complete) return null;
    return dialog.missing[dialog.questionIndex] || null;
  }

  endDialog(dialogId) {
    return this.dialogs.delete(dialogId);
  }

  getDialog(dialogId) {
    return this.dialogs.get(dialogId) || null;
  }
}

// 5. ConfidenceScorer — Confidence scoring
class ConfidenceScorer {
  constructor(options = {}) {
    this.options = {
      threshold: options.threshold || 0.7,
      weights: options.weights || {
        classification: 0.4,
        entities: 0.3,
        parameters: 0.3,
      },
      ...options,
    };
  }

  score({ classification = 0, entities = [], parameters = {} } = {}) {
    const entityScore = entities.length > 0
      ? entities.reduce((sum, e) => sum + (e.valid ? 1 : 0), 0) / entities.length
      : 0;
    const paramCount = Object.keys(parameters).length;
    const paramScore = paramCount > 0 ? Math.min(paramCount / 3, 1) : 0;
    const w = this.options.weights;
    const total = (classification * w.classification) + (entityScore * w.entities) + (paramScore * w.parameters);
    return {
      total: Math.min(total, 1.0),
      breakdown: {
        classification,
        entities: entityScore,
        parameters: paramScore,
      },
      aboveThreshold: total >= this.options.threshold,
    };
  }

  isConfident(score) {
    return score >= this.options.threshold;
  }

  setThreshold(threshold) {
    this.options.threshold = threshold;
    return this;
  }
}

// 6. ContextEnricher — Context enrichment
class ContextEnricher {
  constructor(options = {}) {
    this.options = options;
    this.enrichers = new Map();
  }

  register(name, enricherFn) {
    this.enrichers.set(name, enricherFn);
    return this;
  }

  enrich(intent, params, context = {}) {
    const enriched = { ...params };
    const sources = [];
    for (const [name, fn] of this.enrichers.entries()) {
      try {
        const result = fn(intent, params, context);
        if (result && typeof result === 'object') {
          Object.assign(enriched, result);
          sources.push(name);
        }
      } catch (_) { /* ignore */ }
    }
    return { enriched, sources };
  }

  enrichFromContext(intent, params, contextProviders = {}) {
    const enriched = { ...params };
    for (const [key, provider] of Object.entries(contextProviders)) {
      if (enriched[key] === undefined && provider && provider.get) {
        const value = provider.get();
        if (value !== undefined && value !== null) {
          enriched[key] = value;
        }
      }
    }
    return enriched;
  }

  listEnrichers() {
    return Array.from(this.enrichers.keys());
  }
}

// 7. PipelineSelector — Pipeline selection
class PipelineSelector {
  constructor(options = {}) {
    this.options = options;
    this.pipelines = new Map();
    this.selections = [];
  }

  register(intent, pipelineName, metadata = {}) {
    if (!this.pipelines.has(intent)) this.pipelines.set(intent, []);
    this.pipelines.get(intent).push({
      pipeline: pipelineName,
      priority: metadata.priority || 0,
      conditions: metadata.conditions || [],
      ...metadata,
    });
    return this;
  }

  select(intent, context = {}) {
    const candidates = this.pipelines.get(intent) || [];
    if (candidates.length === 0) return null;
    const scored = candidates.map(c => {
      let score = c.priority;
      for (const cond of c.conditions) {
        if (cond.check && cond.check(context)) {
          score += cond.weight || 1;
        }
      }
      return { ...c, score };
    });
    scored.sort((a, b) => b.score - a.score);
    const selected = scored[0];
    this.selections.push({
      intent,
      pipeline: selected.pipeline,
      timestamp: Date.now(),
      context: { ...context },
    });
    return selected;
  }

  listForIntent(intent) {
    return this.pipelines.get(intent) || [];
  }

  listAll() {
    const result = {};
    for (const [intent, list] of this.pipelines.entries()) {
      result[intent] = list.map(p => p.pipeline);
    }
    return result;
  }

  getHistory(limit = 10) {
    return this.selections.slice(-limit);
  }
}

// 8. IntentNormalizer — Intent normalization
class IntentNormalizer {
  constructor(options = {}) {
    this.options = options;
    this.aliases = new Map();
    this.canonicalNames = new Set();
  }

  registerAlias(alias, canonical) {
    this.aliases.set(alias.toLowerCase(), canonical);
    this.canonicalNames.add(canonical);
    return this;
  }

  normalize(intent) {
    if (!intent) return null;
    const lower = intent.toLowerCase().trim();
    return this.aliases.get(lower) || intent;
  }

  normalizeText(text) {
    let normalized = text.toLowerCase().trim();
    normalized = normalized.replace(/\s+/g, ' ');
    normalized = normalized.replace(/[?!.,;]+$/g, '');
    return normalized;
  }

  areEquivalent(intent1, intent2) {
    return this.normalize(intent1) === this.normalize(intent2);
  }

  listAliases() {
    return Array.from(this.aliases.entries()).map(([alias, canonical]) => ({ alias, canonical }));
  }

  listCanonical() {
    return Array.from(this.canonicalNames);
  }
}

// 9. MultiIntentSplitter — Multi-intent splitting
class MultiIntentSplitter {
  constructor(options = {}) {
    this.options = {
      separators: options.separators || [' and ', ' then ', ',', ';', ' also '],
      ...options,
    };
  }

  split(text) {
    const parts = [text];
    for (const sep of this.options.separators) {
      const newParts = [];
      for (const part of parts) {
        const split = part.split(sep);
        newParts.push(...split);
      }
      parts.length = 0;
      parts.push(...newParts);
    }
    return parts.map(p => p.trim()).filter(p => p.length > 0);
  }

  isMultiIntent(text) {
    return this.split(text).length > 1;
  }

  countIntents(text) {
    return this.split(text).length;
  }

  addSeparator(separator) {
    if (!this.options.separators.includes(separator)) {
      this.options.separators.push(separator);
    }
    return this;
  }
}

// 10. IntentHistory — Intent history
class IntentHistory {
  constructor(options = {}) {
    this.options = {
      maxSize: options.maxSize || 1000,
      ...options,
    };
    this.history = [];
    this.subscribers = [];
  }

  record(intent, params = {}, result = null) {
    const entry = {
      id: `ih_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      intent,
      params,
      result,
      timestamp: Date.now(),
    };
    this.history.push(entry);
    if (this.history.length > this.options.maxSize) {
      this.history = this.history.slice(-this.options.maxSize);
    }
    this._notify(entry);
    return entry;
  }

  getRecent(limit = 10) {
    return this.history.slice(-limit).reverse();
  }

  getByIntent(intent, limit = 10) {
    return this.history.filter(e => e.intent === intent).slice(-limit).reverse();
  }

  findById(id) {
    return this.history.find(e => e.id === id) || null;
  }

  search(query, limit = 10) {
    const lower = query.toLowerCase();
    return this.history.filter(e =>
      e.intent.toLowerCase().includes(lower) ||
      JSON.stringify(e.params).toLowerCase().includes(lower)
    ).slice(-limit).reverse();
  }

  clear() {
    this.history = [];
    this._notify({ cleared: true });
    return this;
  }

  size() {
    return this.history.length;
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(entry) {
    for (const cb of this.subscribers) {
      try { cb(entry); } catch (_) { /* ignore */ }
    }
  }
}

// Global instances for Phase 5
const globalIntentClassifier = new IntentClassifier();
const globalEntityExtractor = new EntityExtractor();
const globalParameterExtractor = new ParameterExtractor();
const globalSlotFiller = new SlotFiller();
const globalConfidenceScorer = new ConfidenceScorer();
const globalContextEnricher = new ContextEnricher();
const globalPipelineSelector = new PipelineSelector();
const globalIntentNormalizer = new IntentNormalizer();
const globalMultiIntentSplitter = new MultiIntentSplitter();
const globalIntentHistory = new IntentHistory();

// ============================================================================
// PHASE 6 — PLANNER
// ============================================================================
// 10 utility classes for turning intents into execution graphs:
//   1. GoalDecomposer         - Goal decomposition
//   2. DependencyGraphBuilder - Dependency graph
//   3. ParallelPlanner        - Parallel planning
//   4. CostEstimator          - Cost estimation
//   5. RiskAnalyzer           - Risk analysis
//   6. ResourceAllocator      - Resource allocation
//   7. PipelineOrderer        - Pipeline ordering
//   8. ConstraintSolver       - Constraint solving
//   9. DynamicReplanner       - Dynamic replanning
//  10. ExecutionGraphBuilder  - Execution graph generation
// ============================================================================

// 1. GoalDecomposer — Goal decomposition
class GoalDecomposer {
  constructor(options = {}) {
    this.options = {
      maxDepth: options.maxDepth || 5,
      ...options,
    };
    this.decompositions = new Map();
  }

  register(goal, subGoals) {
    this.decompositions.set(goal, subGoals);
    return this;
  }

  decompose(goal, context = {}) {
    const subGoals = this.decompositions.get(goal);
    if (!subGoals) return [{ goal, depth: 0, parent: null }];
    const result = [];
    const decomposeRecursive = (g, depth, parent) => {
      if (depth > this.options.maxDepth) return;
      const subs = this.decompositions.get(g);
      if (!subs) {
        result.push({ goal: g, depth, parent });
        return;
      }
      for (const sub of subs) {
        result.push({ goal: sub, depth: depth + 1, parent: g });
        decomposeRecursive(sub, depth + 1, g);
      }
    };
    decomposeRecursive(goal, 0, null);
    return result;
  }

  getDepth(goal) {
    const decomposed = this.decompose(goal);
    return Math.max(...decomposed.map(d => d.depth), 0);
  }

  listGoals() {
    return Array.from(this.decompositions.keys());
  }
}

// 2. DependencyGraphBuilder — Dependency graph
class DependencyGraphBuilder {
  constructor(options = {}) {
    this.options = options;
    this.nodes = new Map();
    this.edges = [];
  }

  addNode(id, data = {}) {
    this.nodes.set(id, { id, dependencies: [], dependents: [], ...data });
    return this;
  }

  addEdge(from, to) {
    if (!this.nodes.has(from) || !this.nodes.has(to)) {
      throw new Error(`Unknown node: ${from} or ${to}`);
    }
    this.edges.push({ from, to });
    this.nodes.get(from).dependents.push(to);
    this.nodes.get(to).dependencies.push(from);
    return this;
  }

  build() {
    return {
      nodes: Array.from(this.nodes.values()),
      edges: this.edges.slice(),
    };
  }

  getRoots() {
    return Array.from(this.nodes.values()).filter(n => n.dependencies.length === 0);
  }

  getLeaves() {
    return Array.from(this.nodes.values()).filter(n => n.dependents.length === 0);
  }

  hasCycle() {
    const visited = new Set();
    const stack = new Set();
    const dfs = (id) => {
      if (stack.has(id)) return true;
      if (visited.has(id)) return false;
      visited.add(id);
      stack.add(id);
      for (const dep of this.nodes.get(id).dependencies) {
        if (dfs(dep)) return true;
      }
      stack.delete(id);
      return false;
    };
    for (const id of this.nodes.keys()) {
      if (dfs(id)) return true;
    }
    return false;
  }

  clear() {
    this.nodes.clear();
    this.edges = [];
    return this;
  }
}

// 3. ParallelPlanner — Parallel planning
class ParallelPlanner {
  constructor(options = {}) {
    this.options = {
      maxParallel: options.maxParallel || 4,
      ...options,
    };
  }

  plan(tasks) {
    const waves = [];
    const completed = new Set();
    const remaining = new Set(tasks.map(t => t.id));
    const taskMap = new Map(tasks.map(t => [t.id, t]));

    while (remaining.size > 0) {
      const wave = [];
      for (const id of remaining) {
        const task = taskMap.get(id);
        const deps = task.dependencies || [];
        if (deps.every(d => completed.has(d))) {
          wave.push(task);
        }
      }
      if (wave.length === 0) throw new Error('Circular dependency in tasks');
      waves.push(wave);
      for (const task of wave) {
        remaining.delete(task.id);
        completed.add(task.id);
      }
    }
    return waves;
  }

  canParallelize(tasks) {
    const waves = this.plan(tasks);
    return waves.length < tasks.length;
  }

  estimateParallelSpeedup(tasks) {
    const waves = this.plan(tasks);
    const totalDuration = waves.reduce((sum, wave) => {
      const waveDuration = Math.max(...wave.map(t => t.duration || 1));
      return sum + waveDuration;
    }, 0);
    const sequentialDuration = tasks.reduce((sum, t) => sum + (t.duration || 1), 0);
    return sequentialDuration > 0 ? sequentialDuration / totalDuration : 1;
  }
}

// 4. CostEstimator — Cost estimation
class CostEstimator {
  constructor(options = {}) {
    this.options = {
      currency: options.currency || 'units',
      ...options,
    };
    this.costModels = new Map();
  }

  registerCostModel(operation, model) {
    this.costModels.set(operation, model);
    return this;
  }

  estimate(operation, params = {}) {
    const model = this.costModels.get(operation);
    if (!model) return { operation, cost: 1, currency: this.options.currency, estimated: true };
    const cost = model(params);
    return { operation, cost, currency: this.options.currency, estimated: true };
  }

  estimateGraph(graph) {
    const nodes = Array.isArray(graph) ? graph : (graph.nodes || []);
    let totalCost = 0;
    const breakdown = [];
    for (const node of nodes) {
      const op = node.tool || node.type || 'unknown';
      const estimate = this.estimate(op, node.parameters || {});
      totalCost += estimate.cost;
      breakdown.push({ nodeId: node.id, ...estimate });
    }
    return { totalCost, currency: this.options.currency, breakdown };
  }

  comparePlans(plans) {
    return plans.map(plan => ({
      plan,
      cost: this.estimateGraph(plan).totalCost,
    })).sort((a, b) => a.cost - b.cost);
  }
}

// 5. RiskAnalyzer — Risk analysis
class RiskAnalyzer {
  constructor(options = {}) {
    this.options = {
      riskLevels: options.riskLevels || {
        READ_ONLY: 0,
        SAFE_LOCAL: 1,
        LOCAL_DESTRUCTIVE: 2,
        EXTERNAL: 3,
        CRITICAL: 4,
      },
      approvalThreshold: options.approvalThreshold || 3,
      ...options,
    };
  }

  analyzeNode(node) {
    const risk = node.risk !== undefined ? node.risk : 1;
    const factors = [];
    if (node.dependencies && node.dependencies.length > 3) factors.push('high_fan_in');
    if (node.dependents && node.dependents.length > 3) factors.push('high_fan_out');
    if (node.type === 'act' && risk >= 3) factors.push('external_action');
    if (node.type === 'act' && risk >= 4) factors.push('critical_action');
    return {
      nodeId: node.id,
      risk,
      level: this._riskLevelName(risk),
      requiresApproval: risk >= this.options.approvalThreshold,
      factors,
    };
  }

  analyzeGraph(graph) {
    const nodes = Array.isArray(graph) ? graph : (graph.nodes || []);
    const analyses = nodes.map(n => this.analyzeNode(n));
    const maxRisk = Math.max(...analyses.map(a => a.risk), 0);
    const approvalCount = analyses.filter(a => a.requiresApproval).length;
    return {
      maxRisk,
      maxRiskLevel: this._riskLevelName(maxRisk),
      totalNodes: nodes.length,
      approvalRequired: approvalCount,
      analyses,
    };
  }

  _riskLevelName(risk) {
    for (const [name, level] of Object.entries(this.options.riskLevels)) {
      if (level === risk) return name;
    }
    return 'UNKNOWN';
  }

  requiresApproval(risk) {
    return risk >= this.options.approvalThreshold;
  }
}

// 6. ResourceAllocator — Resource allocation
class ResourceAllocator {
  constructor(options = {}) {
    this.options = {
      maxCpu: options.maxCpu || 100,
      maxMemory: options.maxMemory || 4096,
      maxNetwork: options.maxNetwork || 100,
      ...options,
    };
    this.allocations = new Map();
  }

  allocate(resourceId, requirements) {
    const current = this._getCurrentUsage();
    const newUsage = {
      cpu: current.cpu + (requirements.cpu || 0),
      memory: current.memory + (requirements.memory || 0),
      network: current.network + (requirements.network || 0),
    };
    if (newUsage.cpu > this.options.maxCpu) {
      throw new Error(`CPU limit exceeded: ${newUsage.cpu}/${this.options.maxCpu}`);
    }
    if (newUsage.memory > this.options.maxMemory) {
      throw new Error(`Memory limit exceeded: ${newUsage.memory}/${this.options.maxMemory}`);
    }
    if (newUsage.network > this.options.maxNetwork) {
      throw new Error(`Network limit exceeded: ${newUsage.network}/${this.options.maxNetwork}`);
    }
    this.allocations.set(resourceId, { ...requirements, allocatedAt: Date.now() });
    return this;
  }

  release(resourceId) {
    return this.allocations.delete(resourceId);
  }

  get(resourceId) {
    return this.allocations.get(resourceId) || null;
  }

  _getCurrentUsage() {
    let cpu = 0, memory = 0, network = 0;
    for (const alloc of this.allocations.values()) {
      cpu += alloc.cpu || 0;
      memory += alloc.memory || 0;
      network += alloc.network || 0;
    }
    return { cpu, memory, network };
  }

  getUsage() {
    return this._getCurrentUsage();
  }

  getAvailable() {
    const used = this._getCurrentUsage();
    return {
      cpu: this.options.maxCpu - used.cpu,
      memory: this.options.maxMemory - used.memory,
      network: this.options.maxNetwork - used.network,
    };
  }

  listAllocations() {
    return Array.from(this.allocations.entries()).map(([id, alloc]) => ({ resourceId: id, ...alloc }));
  }
}

// 7. PipelineOrderer — Pipeline ordering
class PipelineOrderer {
  constructor(options = {}) {
    this.options = {
      strategies: ['topological', 'priority', 'risk_first', 'duration_first'],
      ...options,
    };
  }

  order(pipelines, strategy = 'topological') {
    switch (strategy) {
      case 'topological':
        return this._topologicalOrder(pipelines);
      case 'priority':
        return [...pipelines].sort((a, b) => (b.priority || 0) - (a.priority || 0));
      case 'risk_first':
        return [...pipelines].sort((a, b) => (b.risk || 0) - (a.risk || 0));
      case 'duration_first':
        return [...pipelines].sort((a, b) => (a.duration || 0) - (b.duration || 0));
      default:
        return pipelines;
    }
  }

  _topologicalOrder(pipelines) {
    const sorted = [];
    const visited = new Set();
    const visiting = new Set();
    const pipelineMap = new Map(pipelines.map(p => [p.id, p]));

    const visit = (id) => {
      if (visited.has(id)) return;
      if (visiting.has(id)) throw new Error(`Circular dependency: ${id}`);
      visiting.add(id);
      const pipeline = pipelineMap.get(id);
      if (pipeline && pipeline.dependencies) {
        for (const dep of pipeline.dependencies) {
          if (pipelineMap.has(dep)) visit(dep);
        }
      }
      visiting.delete(id);
      visited.add(id);
      sorted.push(pipeline);
    };

    for (const p of pipelines) visit(p.id);
    return sorted;
  }

  listStrategies() {
    return this.options.strategies;
  }
}

// 8. ConstraintSolver — Constraint solving
class ConstraintSolver {
  constructor(options = {}) {
    this.options = options;
    this.constraints = [];
  }

  addConstraint(constraint) {
    this.constraints.push(constraint);
    return this;
  }

  solve(variables) {
    const violations = [];
    for (const constraint of this.constraints) {
      try {
        const result = constraint.check(variables);
        if (result !== true) {
          violations.push({
            constraint: constraint.name || 'unnamed',
            message: typeof result === 'string' ? result : 'Constraint violated',
          });
        }
      } catch (err) {
        violations.push({
          constraint: constraint.name || 'unnamed',
          message: err.message,
        });
      }
    }
    return {
      satisfied: violations.length === 0,
      violations,
    };
  }

  solveAll(solutions) {
    return solutions.map(solution => ({
      solution,
      result: this.solve(solution),
    }));
  }

  findValid(solutions) {
    return solutions.filter(s => this.solve(s).satisfied);
  }

  clear() {
    this.constraints = [];
    return this;
  }

  listConstraints() {
    return this.constraints.length;
  }
}

// 9. DynamicReplanner — Dynamic replanning
class DynamicReplanner {
  constructor(options = {}) {
    this.options = {
      maxReplans: options.maxReplans || 3,
      ...options,
    };
    this.replans = [];
    this.strategies = new Map();
  }

  registerStrategy(name, strategyFn) {
    this.strategies.set(name, strategyFn);
    return this;
  }

  replan(originalPlan, failure, context = {}) {
    if (this.replans.length >= this.options.maxReplans) {
      return { replanned: false, reason: 'max_replans_exceeded' };
    }
    const replanEntry = {
      id: `replan_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      originalPlan,
      failure,
      context,
      timestamp: Date.now(),
      strategy: null,
      newPlan: null,
    };
    for (const [name, strategyFn] of this.strategies.entries()) {
      try {
        const newPlan = strategyFn(originalPlan, failure, context);
        if (newPlan) {
          replanEntry.strategy = name;
          replanEntry.newPlan = newPlan;
          break;
        }
      } catch (_) { /* try next strategy */ }
    }
    this.replans.push(replanEntry);
    return {
      replanned: !!replanEntry.newPlan,
      replanId: replanEntry.id,
      strategy: replanEntry.strategy,
      newPlan: replanEntry.newPlan,
    };
  }

  getHistory(limit = 10) {
    return this.replans.slice(-limit);
  }

  getStats() {
    const total = this.replans.length;
    const successful = this.replans.filter(r => r.newPlan).length;
    return {
      total,
      successful,
      failed: total - successful,
      successRate: total > 0 ? successful / total : 0,
    };
  }

  clear() {
    this.replans = [];
    return this;
  }
}

// 10. ExecutionGraphBuilder — Execution graph generation
class ExecutionGraphBuilder {
  constructor(options = {}) {
    this.options = options;
    this.graphs = [];
  }

  build(name, nodes, edges = []) {
    const graph = {
      name,
      nodes: nodes.map(n => ({ ...n })),
      edges: edges.map(e => ({ ...e })),
      metadata: {
        createdAt: Date.now(),
        nodeCount: nodes.length,
        edgeCount: edges.length,
      },
    };
    this.graphs.push(graph);
    return graph;
  }

  buildFromPlan(plan) {
    const nodes = [];
    const edges = [];
    let nodeIndex = 0;
    const nodeIdMap = new Map();

    for (const step of plan.steps || []) {
      const nodeId = step.id || `node_${nodeIndex++}`;
      nodeIdMap.set(step, nodeId);
      nodes.push({
        id: nodeId,
        type: step.type || 'act',
        objective: step.objective || step.name,
        parameters: step.parameters || {},
        risk: step.risk || 1,
        dependencies: [],
      });
    }

    for (const step of plan.steps || []) {
      const nodeId = nodeIdMap.get(step);
      const node = nodes.find(n => n.id === nodeId);
      if (step.dependencies) {
        for (const dep of step.dependencies) {
          const depId = nodeIdMap.get(dep);
          if (depId) {
            node.dependencies.push(depId);
            edges.push({ from: depId, to: nodeId });
          }
        }
      }
    }

    return this.build(plan.name || 'plan_graph', nodes, edges);
  }

  validate(graph) {
    const errors = [];
    if (!graph.nodes || graph.nodes.length === 0) {
      errors.push('Graph has no nodes');
    }
    const nodeIds = new Set(graph.nodes.map(n => n.id));
    for (const edge of graph.edges || []) {
      if (!nodeIds.has(edge.from)) errors.push(`Edge references unknown node: ${edge.from}`);
      if (!nodeIds.has(edge.to)) errors.push(`Edge references unknown node: ${edge.to}`);
    }
    for (const node of graph.nodes) {
      for (const dep of node.dependencies || []) {
        if (!nodeIds.has(dep)) errors.push(`Node ${node.id} has unknown dependency: ${dep}`);
      }
    }
    return { valid: errors.length === 0, errors };
  }

  listGraphs() {
    return this.graphs.slice();
  }

  getGraph(name) {
    return this.graphs.find(g => g.name === name) || null;
  }
}

