// ============================================================================
// PHASE 7 — OBSERVATION ENGINE
// ============================================================================
// 10 utility classes for understanding the current desktop:
//   1. WindowObserver         - Window observer
//   2. ProcessObserver        - Process observer
//   3. BrowserObserver        - Browser observer
//   4. FilesystemObserver     - Filesystem observer
//   5. ClipboardObserver      - Clipboard observer
//   6. OCRObserver            - OCR observer
//   7. VisionObserver         - Vision observer
//   8. AccessibilityObserver  - Accessibility observer
//   9. NetworkObserver        - Network observer
//  10. SystemObserver         - System observer
// ============================================================================

// 1. WindowObserver — Window observer
class WindowObserver {
  constructor(options = {}) {
    this.options = {
      pollInterval: options.pollInterval || 1000,
      ...options,
    };
    this.windows = new Map();
    this.subscribers = [];
    this.observing = false;
  }

  observe() {
    this.observing = true;
    return this;
  }

  stop() {
    this.observing = false;
    return this;
  }

  update(windowId, info) {
    const existing = this.windows.get(windowId);
    this.windows.set(windowId, {
      ...info,
      windowId,
      firstSeen: existing ? existing.firstSeen : Date.now(),
      lastSeen: Date.now(),
    });
    this._notify({ type: 'update', windowId, info });
    return this;
  }

  remove(windowId) {
    const existed = this.windows.delete(windowId);
    if (existed) this._notify({ type: 'remove', windowId });
    return existed;
  }

  get(windowId) {
    return this.windows.get(windowId) || null;
  }

  list() {
    return Array.from(this.windows.values());
  }

  findByTitle(titlePattern) {
    const regex = new RegExp(titlePattern, 'i');
    return this.list().filter(w => regex.test(w.title || ''));
  }

  findByApp(appName) {
    return this.list().filter(w => w.app === appName);
  }

  getActive() {
    const list = this.list();
    return list.find(w => w.active) || list[0] || null;
  }

  count() {
    return this.windows.size;
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// 2. ProcessObserver — Process observer
class ProcessObserver {
  constructor(options = {}) {
    this.options = {
      pollInterval: options.pollInterval || 2000,
      ...options,
    };
    this.processes = new Map();
    this.subscribers = [];
  }

  update(pid, info) {
    const existing = this.processes.get(pid);
    this.processes.set(pid, {
      pid,
      ...info,
      firstSeen: existing ? existing.firstSeen : Date.now(),
      lastSeen: Date.now(),
    });
    this._notify({ type: 'update', pid, info });
    return this;
  }

  remove(pid) {
    const existed = this.processes.delete(pid);
    if (existed) this._notify({ type: 'remove', pid });
    return existed;
  }

  get(pid) {
    return this.processes.get(pid) || null;
  }

  list() {
    return Array.from(this.processes.values());
  }

  findByName(name) {
    return this.list().filter(p => p.name === name);
  }

  getHighCpu(threshold = 50) {
    return this.list().filter(p => (p.cpu || 0) > threshold);
  }

  getHighMemory(threshold = 500) {
    return this.list().filter(p => (p.memory || 0) > threshold);
  }

  count() {
    return this.processes.size;
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// 3. BrowserObserver — Browser observer
class BrowserObserver {
  constructor(options = {}) {
    this.options = options;
    this.browsers = new Map();
    this.tabs = new Map();
  }

  registerBrowser(browserId, info) {
    this.browsers.set(browserId, {
      browserId,
      ...info,
      registeredAt: Date.now(),
    });
    return this;
  }

  updateTab(browserId, tabId, info) {
    const key = `${browserId}:${tabId}`;
    const existing = this.tabs.get(key);
    this.tabs.set(key, {
      browserId,
      tabId,
      ...info,
      firstSeen: existing ? existing.firstSeen : Date.now(),
      lastSeen: Date.now(),
    });
    return this;
  }

  closeTab(browserId, tabId) {
    return this.tabs.delete(`${browserId}:${tabId}`);
  }

  getBrowser(browserId) {
    return this.browsers.get(browserId) || null;
  }

  listBrowsers() {
    return Array.from(this.browsers.values());
  }

  getTabs(browserId) {
    return Array.from(this.tabs.values()).filter(t => t.browserId === browserId);
  }

  getActiveTab(browserId) {
    const tabs = this.getTabs(browserId);
    return tabs.find(t => t.active) || tabs[0] || null;
  }

  listAllTabs() {
    return Array.from(this.tabs.values());
  }

  findTabsByUrl(urlPattern) {
    const regex = new RegExp(urlPattern, 'i');
    return this.listAllTabs().filter(t => regex.test(t.url || ''));
  }

  count() {
    return this.browsers.size;
  }

  tabCount() {
    return this.tabs.size;
  }
}

// 4. FilesystemObserver — Filesystem observer
class FilesystemObserver {
  constructor(options = {}) {
    this.options = {
      watchPaths: options.watchPaths || [],
      ...options,
    };
    this.watchedPaths = new Map();
    this.events = [];
    this.maxEvents = options.maxEvents || 1000;
  }

  watch(path) {
    this.watchedPaths.set(path, {
      path,
      watchedAt: Date.now(),
      events: [],
    });
    return this;
  }

  unwatch(path) {
    return this.watchedPaths.delete(path);
  }

  recordEvent(path, eventType, info = {}) {
    const event = {
      id: `fs_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      path,
      eventType,
      ...info,
      timestamp: Date.now(),
    };
    this.events.push(event);
    if (this.events.length > this.maxEvents) {
      this.events = this.events.slice(-this.maxEvents);
    }
    const watched = this.watchedPaths.get(path);
    if (watched) {
      watched.events.push(event);
    }
    return event;
  }

  getEvents(path = null, limit = 50) {
    const filtered = path
      ? this.events.filter(e => e.path === path)
      : this.events;
    return filtered.slice(-limit);
  }

  getEventsByType(eventType, limit = 50) {
    return this.events.filter(e => e.eventType === eventType).slice(-limit);
  }

  listWatchedPaths() {
    return Array.from(this.watchedPaths.keys());
  }

  isWatching(path) {
    return this.watchedPaths.has(path);
  }

  clearEvents() {
    this.events = [];
    return this;
  }
}

// 5. ClipboardObserver — Clipboard observer
class ClipboardObserver {
  constructor(options = {}) {
    this.options = {
      pollInterval: options.pollInterval || 500,
      ...options,
    };
    this.current = null;
    this.history = [];
    this.maxHistory = options.maxHistory || 100;
    this.subscribers = [];
  }

  update(content, formats = ['text']) {
    const entry = {
      content,
      formats,
      timestamp: Date.now(),
    };
    if (this.current && this.current.content !== content) {
      this.history.unshift({ ...this.current });
      if (this.history.length > this.maxHistory) {
        this.history = this.history.slice(0, this.maxHistory);
      }
    }
    this.current = entry;
    this._notify(entry);
    return this;
  }

  getCurrent() {
    return this.current ? { ...this.current } : null;
  }

  getHistory(limit = 10) {
    return this.history.slice(0, limit);
  }

  hasChanged(newContent) {
    return !this.current || this.current.content !== newContent;
  }

  clear() {
    this.current = null;
    this.history = [];
    this._notify({ cleared: true });
    return this;
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// 6. OCRObserver — OCR observer
class OCRObserver {
  constructor(options = {}) {
    this.options = {
      languages: options.languages || ['en'],
      minConfidence: options.minConfidence || 0.6,
      ...options,
    };
    this.results = [];
    this.maxResults = options.maxResults || 500;
  }

  record(screenshotId, text, regions = [], metadata = {}) {
    const result = {
      id: `ocr_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      screenshotId,
      text,
      regions,
      metadata,
      timestamp: Date.now(),
    };
    this.results.push(result);
    if (this.results.length > this.maxResults) {
      this.results = this.results.slice(-this.maxResults);
    }
    return result;
  }

  getRecent(limit = 10) {
    return this.results.slice(-limit).reverse();
  }

  getByScreenshot(screenshotId) {
    return this.results.filter(r => r.screenshotId === screenshotId);
  }

  search(query, limit = 10) {
    const lower = query.toLowerCase();
    return this.results.filter(r => r.text.toLowerCase().includes(lower)).slice(-limit).reverse();
  }

  getHighConfidence(minConf = this.options.minConfidence, limit = 10) {
    return this.results.filter(r => (r.metadata.confidence || 0) >= minConf).slice(-limit).reverse();
  }

  clear() {
    this.results = [];
    return this;
  }

  count() {
    return this.results.length;
  }
}

// 7. VisionObserver — Vision observer
class VisionObserver {
  constructor(options = {}) {
    this.options = {
      detectObjects: options.detectObjects !== false,
      detectText: options.detectText !== false,
      ...options,
    };
    this.detections = [];
    this.maxDetections = options.maxDetections || 500;
  }

  record(screenshotId, detections, metadata = {}) {
    const entry = {
      id: `vis_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      screenshotId,
      detections,
      metadata,
      timestamp: Date.now(),
    };
    this.detections.push(entry);
    if (this.detections.length > this.maxDetections) {
      this.detections = this.detections.slice(-this.maxDetections);
    }
    return entry;
  }

  getRecent(limit = 10) {
    return this.detections.slice(-limit).reverse();
  }

  getByScreenshot(screenshotId) {
    return this.detections.filter(d => d.screenshotId === screenshotId);
  }

  findByClass(className, limit = 10) {
    const results = [];
    for (const entry of this.detections.slice().reverse()) {
      for (const det of entry.detections || []) {
        if (det.class === className) {
          results.push({ ...det, screenshotId: entry.screenshotId });
          if (results.length >= limit) return results;
        }
      }
    }
    return results;
  }

  findByConfidence(minConf, limit = 10) {
    const results = [];
    for (const entry of this.detections.slice().reverse()) {
      for (const det of entry.detections || []) {
        if ((det.confidence || 0) >= minConf) {
          results.push({ ...det, screenshotId: entry.screenshotId });
          if (results.length >= limit) return results;
        }
      }
    }
    return results;
  }

  clear() {
    this.detections = [];
    return this;
  }

  count() {
    return this.detections.length;
  }
}

// 8. AccessibilityObserver — Accessibility observer
class AccessibilityObserver {
  constructor(options = {}) {
    this.options = options;
    this.elements = new Map();
    this.focusedElement = null;
  }

  update(elementId, info) {
    this.elements.set(elementId, {
      elementId,
      ...info,
      lastSeen: Date.now(),
    });
    if (info.focused) {
      this.focusedElement = { elementId, ...info };
    }
    return this;
  }

  remove(elementId) {
    return this.elements.delete(elementId);
  }

  get(elementId) {
    return this.elements.get(elementId) || null;
  }

  list() {
    return Array.from(this.elements.values());
  }

  findByRole(role) {
    return this.list().filter(e => e.role === role);
  }

  findByLabel(labelPattern) {
    const regex = new RegExp(labelPattern, 'i');
    return this.list().filter(e => regex.test(e.label || '') || regex.test(e.name || ''));
  }

  findClickable() {
    return this.list().filter(e => e.clickable || e.role === 'button' || e.role === 'link');
  }

  findByText(textPattern) {
    const regex = new RegExp(textPattern, 'i');
    return this.list().filter(e => regex.test(e.text || '') || regex.test(e.value || ''));
  }

  getFocused() {
    return this.focusedElement ? { ...this.focusedElement } : null;
  }

  count() {
    return this.elements.size;
  }
}

// 9. NetworkObserver — Network observer
class NetworkObserver {
  constructor(options = {}) {
    this.options = options;
    this.connections = new Map();
    this.requests = [];
    this.maxRequests = options.maxRequests || 1000;
  }

  recordRequest(request) {
    const entry = {
      id: `net_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      ...request,
      timestamp: Date.now(),
    };
    this.requests.push(entry);
    if (this.requests.length > this.maxRequests) {
      this.requests = this.requests.slice(-this.maxRequests);
    }
    return entry;
  }

  recordConnection(connectionId, info) {
    this.connections.set(connectionId, {
      connectionId,
      ...info,
      establishedAt: Date.now(),
    });
    return this;
  }

  closeConnection(connectionId) {
    return this.connections.delete(connectionId);
  }

  getConnection(connectionId) {
    return this.connections.get(connectionId) || null;
  }

  listConnections() {
    return Array.from(this.connections.values());
  }

  getRecentRequests(limit = 50) {
    return this.requests.slice(-limit).reverse();
  }

  getRequestsByHost(host, limit = 50) {
    return this.requests.filter(r => r.host === host).slice(-limit).reverse();
  }

  getFailedRequests(limit = 50) {
    return this.requests.filter(r => r.status >= 400).slice(-limit).reverse();
  }

  getSlowRequests(thresholdMs = 1000, limit = 50) {
    return this.requests.filter(r => (r.duration || 0) > thresholdMs).slice(-limit).reverse();
  }

  isOnline() {
    return this.connections.size > 0;
  }

  clearRequests() {
    this.requests = [];
    return this;
  }
}

// 10. SystemObserver — System observer
class SystemObserver {
  constructor(options = {}) {
    this.options = {
      pollInterval: options.pollInterval || 5000,
      ...options,
    };
    this.metrics = {
      cpu: { current: 0, history: [] },
      memory: { used: 0, total: 0, history: [] },
      disk: { used: 0, total: 0, history: [] },
      network: { rx: 0, tx: 0, history: [] },
      battery: null,
      temperature: null,
      uptime: 0,
      lastUpdated: null,
    };
    this.alerts = [];
  }

  updateCpu(percent) {
    this.metrics.cpu.current = percent;
    this.metrics.cpu.history.push({ value: percent, timestamp: Date.now() });
    if (this.metrics.cpu.history.length > 100) {
      this.metrics.cpu.history = this.metrics.cpu.history.slice(-100);
    }
    this.metrics.lastUpdated = Date.now();
    return this;
  }

  updateMemory(used, total) {
    this.metrics.memory.used = used;
    this.metrics.memory.total = total;
    this.metrics.memory.history.push({ used, total, timestamp: Date.now() });
    if (this.metrics.memory.history.length > 100) {
      this.metrics.memory.history = this.metrics.memory.history.slice(-100);
    }
    this.metrics.lastUpdated = Date.now();
    return this;
  }

  updateDisk(used, total) {
    this.metrics.disk.used = used;
    this.metrics.disk.total = total;
    this.metrics.disk.history.push({ used, total, timestamp: Date.now() });
    if (this.metrics.disk.history.length > 100) {
      this.metrics.disk.history = this.metrics.disk.history.slice(-100);
    }
    this.metrics.lastUpdated = Date.now();
    return this;
  }

  updateNetwork(rx, tx) {
    this.metrics.network.rx = rx;
    this.metrics.network.tx = tx;
    this.metrics.network.history.push({ rx, tx, timestamp: Date.now() });
    if (this.metrics.network.history.length > 100) {
      this.metrics.network.history = this.metrics.network.history.slice(-100);
    }
    this.metrics.lastUpdated = Date.now();
    return this;
  }

  updateBattery(info) {
    this.metrics.battery = { ...info, timestamp: Date.now() };
    this.metrics.lastUpdated = Date.now();
    return this;
  }

  updateUptime(seconds) {
    this.metrics.uptime = seconds;
    return this;
  }

  addAlert(alert) {
    const entry = {
      id: `alert_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      ...alert,
      timestamp: Date.now(),
    };
    this.alerts.push(entry);
    return entry;
  }

  getMetrics() {
    return { ...this.metrics };
  }

  getAlerts(limit = 10) {
    return this.alerts.slice(-limit).reverse();
  }

  clearAlerts() {
    this.alerts = [];
    return this;
  }
}

