// ============================================================================
// PHASE 8 — VERIFICATION ENGINE
// ============================================================================
// 10 utility classes for verifying that actions actually succeeded:
//   1. StateVerifier         - State verification
//   2. UIVerifier            - UI verification
//   3. DOMVerifier           - DOM verification
//   4. OCRVerifier           - OCR verification
//   5. FilesystemVerifier    - Filesystem verification
//   6. APIVerifier           - API verification
//   7. ProcessVerifier       - Process verification
//   8. WindowVerifier        - Window verification
//   9. ImageVerifier         - Image verification
//  10. CustomVerifier        - Custom verifiers (JS + native C++ bridge)
// ============================================================================

// 1. StateVerifier — State verification
class StateVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      pollInterval: options.pollInterval || 100,
      ...options,
    };
    this.checks = [];
    this.results = [];
  }

  define(name, predicate, options = {}) {
    this.checks.push({
      name,
      predicate,
      timeout: options.timeout || this.options.timeout,
      pollInterval: options.pollInterval || this.options.pollInterval,
      description: options.description || '',
    });
    return this;
  }

  async verify(name, context = {}) {
    const check = this.checks.find(c => c.name === name);
    if (!check) {
      const result = { name, passed: false, error: 'check not found', timestamp: Date.now() };
      this.results.push(result);
      return result;
    }
    const start = Date.now();
    let lastError = null;
    while (Date.now() - start < check.timeout) {
      try {
        const passed = await check.predicate(context);
        if (passed) {
          const result = { name, passed: true, duration: Date.now() - start, timestamp: Date.now() };
          this.results.push(result);
          return result;
        }
      } catch (e) {
        lastError = e.message;
      }
      await new Promise(r => setTimeout(r, check.pollInterval));
    }
    const result = {
      name,
      passed: false,
      duration: Date.now() - start,
      error: lastError || 'predicate returned false',
      timestamp: Date.now(),
    };
    this.results.push(result);
    return result;
  }

  async verifyAll(context = {}) {
    const results = [];
    for (const check of this.checks) {
      results.push(await this.verify(check.name, context));
    }
    return results;
  }

  getResults(name = null) {
    return name ? this.results.filter(r => r.name === name) : [...this.results];
  }

  clearResults() {
    this.results = [];
    return this;
  }

  listChecks() {
    return this.checks.map(c => ({ name: c.name, description: c.description }));
  }
}

// 2. UIVerifier — UI verification
class UIVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      ...options,
    };
    this.expectedStates = [];
  }

  expectElement(text, options = {}) {
    this.expectedStates.push({
      type: 'element',
      text,
      minConfidence: options.minConfidence || 0.7,
      timeout: options.timeout || this.options.timeout,
    });
    return this;
  }

  expectText(text, options = {}) {
    this.expectedStates.push({
      type: 'text',
      text,
      exact: options.exact || false,
      timeout: options.timeout || this.options.timeout,
    });
    return this;
  }

  expectAbsent(text, options = {}) {
    this.expectedStates.push({
      type: 'absent',
      text,
      timeout: options.timeout || this.options.timeout,
    });
    return this;
  }

  async verify(observer, expectations = null) {
    const checks = expectations || this.expectedStates;
    const results = [];
    for (const exp of checks) {
      const start = Date.now();
      let passed = false;
      while (Date.now() - start < exp.timeout) {
        const elements = observer.list ? observer.list() : [];
        if (exp.type === 'element') {
          passed = elements.some(e => {
            const text = (e.text || e.label || e.name || '').toLowerCase();
            return text.includes(exp.text.toLowerCase());
          });
        } else if (exp.type === 'text') {
          passed = elements.some(e => {
            const text = (e.text || e.label || e.name || '').toLowerCase();
            return exp.exact ? text === exp.text.toLowerCase() : text.includes(exp.text.toLowerCase());
          });
        } else if (exp.type === 'absent') {
          passed = !elements.some(e => {
            const text = (e.text || e.label || e.name || '').toLowerCase();
            return text.includes(exp.text.toLowerCase());
          });
        }
        if (passed) break;
        await new Promise(r => setTimeout(r, 100));
      }
      results.push({ type: exp.type, target: exp.text, passed, duration: Date.now() - start });
    }
    return results;
  }

  clear() {
    this.expectedStates = [];
    return this;
  }
}

// 3. DOMVerifier — DOM verification
class DOMVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      ...options,
    };
  }

  async verifySelector(page, selector, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      await page.waitForSelector(selector, { timeout, state: options.state || 'visible' });
      return { selector, passed: true, duration: Date.now() - start };
    } catch (e) {
      return { selector, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyText(page, expectedText, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      await page.waitForFunction(
        (text) => document.body && document.body.innerText.includes(text),
        expectedText,
        { timeout }
      );
      return { expectedText, passed: true, duration: Date.now() - start };
    } catch (e) {
      return { expectedText, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyURL(page, urlPattern, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    const regex = urlPattern instanceof RegExp ? urlPattern : new RegExp(urlPattern);
    try {
      await page.waitForFunction(
        (pattern) => {
          const re = new RegExp(pattern);
          return re.test(window.location.href);
        },
        regex.source,
        { timeout }
      );
      return { urlPattern: regex.source, passed: true, duration: Date.now() - start };
    } catch (e) {
      return { urlPattern: regex.source, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyAttribute(page, selector, attribute, expected, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      await page.waitForFunction(
        ({ sel, attr, exp }) => {
          const el = document.querySelector(sel);
          return el && el.getAttribute(attr) === exp;
        },
        { sel: selector, attr: attribute, exp: expected },
        { timeout }
      );
      return { selector, attribute, expected, passed: true, duration: Date.now() - start };
    } catch (e) {
      return { selector, attribute, expected, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyAll(page, checks) {
    const results = [];
    for (const check of checks) {
      if (check.type === 'selector') {
        results.push(await this.verifySelector(page, check.selector, check.options));
      } else if (check.type === 'text') {
        results.push(await this.verifyText(page, check.text, check.options));
      } else if (check.type === 'url') {
        results.push(await this.verifyURL(page, check.url, check.options));
      } else if (check.type === 'attribute') {
        results.push(await this.verifyAttribute(page, check.selector, check.attribute, check.expected, check.options));
      }
    }
    return results;
  }
}

// 4. OCRVerifier — OCR verification
class OCRVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      minConfidence: options.minConfidence || 0.6,
      ...options,
    };
  }

  async verifyText(ocrObserver, expectedText, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    const exact = options.exact || false;
    while (Date.now() - start < timeout) {
      const results = ocrObserver.search(expectedText, 5);
      if (results.length > 0) {
        const match = exact
          ? results.some(r => r.text.trim() === expectedText.trim())
          : results.length > 0;
        if (match) {
          return { expectedText, passed: true, duration: Date.now() - start };
        }
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { expectedText, passed: false, duration: Date.now() - start };
  }

  async verifyAbsent(ocrObserver, text, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const results = ocrObserver.search(text, 5);
      if (results.length === 0) {
        return { text, passed: true, duration: Date.now() - start };
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { text, passed: false, duration: Date.now() - start };
  }

  async verifyConfidence(ocrObserver, minConfidence, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const results = ocrObserver.getHighConfidence(minConfidence, 5);
      if (results.length > 0) {
        return { minConfidence, passed: true, count: results.length, duration: Date.now() - start };
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { minConfidence, passed: false, duration: Date.now() - start };
  }
}

// 5. FilesystemVerifier — Filesystem verification
class FilesystemVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      ...options,
    };
  }

  async verifyExists(path, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (fs.existsSync(path)) {
          const stat = fs.statSync(path);
          return { path, passed: true, exists: true, isFile: stat.isFile(), isDirectory: stat.isDirectory(), duration: Date.now() - start };
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }

  async verifyAbsent(path, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (!fs.existsSync(path)) {
          return { path, passed: true, duration: Date.now() - start };
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }

  async verifyContent(path, expectedContent, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (fs.existsSync(path)) {
          const content = fs.readFileSync(path, 'utf8');
          const matches = options.exact
            ? content === expectedContent
            : content.includes(expectedContent);
          if (matches) {
            return { path, passed: true, duration: Date.now() - start };
          }
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }

  async verifySize(path, expectedSize, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    const tolerance = options.tolerance || 0;
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (fs.existsSync(path)) {
          const stat = fs.statSync(path);
          if (Math.abs(stat.size - expectedSize) <= tolerance) {
            return { path, passed: true, size: stat.size, duration: Date.now() - start };
          }
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }

  async verifyModified(path, afterTimestamp, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (fs.existsSync(path)) {
          const stat = fs.statSync(path);
          if (stat.mtimeMs >= afterTimestamp) {
            return { path, passed: true, mtime: stat.mtimeMs, duration: Date.now() - start };
          }
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }
}

// 6. APIVerifier — API verification
class APIVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 10000,
      ...options,
    };
  }

  async verifyStatus(url, expectedStatus, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeout);
      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(timer);
      const passed = Array.isArray(expectedStatus)
        ? expectedStatus.includes(response.status)
        : response.status === expectedStatus;
      return { url, expectedStatus, actualStatus: response.status, passed, duration: Date.now() - start };
    } catch (e) {
      return { url, expectedStatus, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyJSON(url, jsonPath, expectedValue, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeout);
      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(timer);
      const data = await response.json();
      const pathParts = jsonPath.split('.');
      let current = data;
      for (const part of pathParts) {
        if (current == null) break;
        current = current[part];
      }
      const passed = current === expectedValue;
      return { url, jsonPath, expectedValue, actualValue: current, passed, duration: Date.now() - start };
    } catch (e) {
      return { url, jsonPath, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyHeader(url, headerName, expectedValue, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeout);
      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(timer);
      const actual = response.headers.get(headerName);
      const passed = actual === expectedValue;
      return { url, headerName, expectedValue, actualValue: actual, passed, duration: Date.now() - start };
    } catch (e) {
      return { url, headerName, passed: false, error: e.message, duration: Date.now() - start };
    }
  }

  async verifyResponseTime(url, maxMs, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeout);
      const response = await fetch(url, { ...options, signal: controller.signal });
      clearTimeout(timer);
      await response.text();
      const duration = Date.now() - start;
      return { url, maxMs, actualMs: duration, passed: duration <= maxMs };
    } catch (e) {
      return { url, maxMs, passed: false, error: e.message, duration: Date.now() - start };
    }
  }
}

// 7. ProcessVerifier — Process verification
class ProcessVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      ...options,
    };
  }

  async verifyRunning(processName, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const { execSync } = require('child_process');
        const cmd = process.platform === 'win32'
          ? `tasklist /FI "IMAGENAME eq ${processName}.exe"`
          : `pgrep -f ${processName}`;
        const output = execSync(cmd, { encoding: 'utf8' });
        const running = process.platform === 'win32'
          ? output.toLowerCase().includes(processName.toLowerCase())
          : output.trim().length > 0;
        if (running) {
          return { processName, passed: true, running: true, duration: Date.now() - start };
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 200));
    }
    return { processName, passed: false, duration: Date.now() - start };
  }

  async verifyStopped(processName, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const { execSync } = require('child_process');
        const cmd = process.platform === 'win32'
          ? `tasklist /FI "IMAGENAME eq ${processName}.exe"`
          : `pgrep -f ${processName}`;
        const output = execSync(cmd, { encoding: 'utf8' });
        const running = process.platform === 'win32'
          ? output.toLowerCase().includes(processName.toLowerCase())
          : output.trim().length > 0;
        if (!running) {
          return { processName, passed: true, running: false, duration: Date.now() - start };
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 200));
    }
    return { processName, passed: false, duration: Date.now() - start };
  }

  async verifyCount(processName, expectedCount, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const { execSync } = require('child_process');
        const cmd = process.platform === 'win32'
          ? `tasklist /FI "IMAGENAME eq ${processName}.exe" /FO CSV`
          : `pgrep -f ${processName} | wc -l`;
        const output = execSync(cmd, { encoding: 'utf8' });
        const count = process.platform === 'win32'
          ? (output.match(new RegExp(processName, 'gi')) || []).length
          : parseInt(output.trim(), 10) || 0;
        if (count === expectedCount) {
          return { processName, expectedCount, actualCount: count, passed: true, duration: Date.now() - start };
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 200));
    }
    return { processName, expectedCount, passed: false, duration: Date.now() - start };
  }
}

// 8. WindowVerifier — Window verification
class WindowVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      ...options,
    };
  }

  async verifyWindowExists(windowObserver, titlePattern, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const matches = windowObserver.findByTitle(titlePattern);
      if (matches.length > 0) {
        return { titlePattern, passed: true, count: matches.length, duration: Date.now() - start };
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { titlePattern, passed: false, duration: Date.now() - start };
  }

  async verifyWindowClosed(windowObserver, titlePattern, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const matches = windowObserver.findByTitle(titlePattern);
      if (matches.length === 0) {
        return { titlePattern, passed: true, duration: Date.now() - start };
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { titlePattern, passed: false, duration: Date.now() - start };
  }

  async verifyActiveWindow(windowObserver, titlePattern, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const active = windowObserver.getActive();
      if (active && new RegExp(titlePattern, 'i').test(active.title || '')) {
        return { titlePattern, passed: true, activeTitle: active.title, duration: Date.now() - start };
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { titlePattern, passed: false, duration: Date.now() - start };
  }

  async verifyWindowCount(windowObserver, expectedCount, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      const count = windowObserver.count();
      if (count === expectedCount) {
        return { expectedCount, actualCount: count, passed: true, duration: Date.now() - start };
      }
      await new Promise(r => setTimeout(r, 200));
    }
    return { expectedCount, passed: false, duration: Date.now() - start };
  }
}

// 9. ImageVerifier — Image verification
class ImageVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      pixelTolerance: options.pixelTolerance || 0.1,
      ...options,
    };
  }

  async verifyImageExists(path, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (fs.existsSync(path)) {
          const stat = fs.statSync(path);
          if (stat.size > 0) {
            return { path, passed: true, size: stat.size, duration: Date.now() - start };
          }
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }

  async verifyImageSize(path, options = {}) {
    const timeout = options.timeout || this.options.timeout;
    const start = Date.now();
    const { width, height, tolerance = 0 } = options;
    while (Date.now() - start < timeout) {
      try {
        const fs = require('fs');
        if (fs.existsSync(path)) {
          const buf = fs.readFileSync(path);
          // PNG: width @ byte 16-19, height @ byte 20-23 (big-endian)
          // JPEG: parse SOF marker
          let w = 0, h = 0;
          if (buf[0] === 0x89 && buf[1] === 0x50) {
            w = buf.readUInt32BE(16);
            h = buf.readUInt32BE(20);
          } else if (buf[0] === 0xFF && buf[1] === 0xD8) {
            let i = 2;
            while (i < buf.length) {
              if (buf[i] === 0xFF && (buf[i + 1] >= 0xC0 && buf[i + 1] <= 0xC3)) {
                h = buf.readUInt16BE(i + 5);
                w = buf.readUInt16BE(i + 7);
                break;
              }
              i += 2 + buf.readUInt16BE(i + 2);
            }
          }
          const widthOk = !width || Math.abs(w - width) <= tolerance;
          const heightOk = !height || Math.abs(h - height) <= tolerance;
          if (widthOk && heightOk && w > 0 && h > 0) {
            return { path, passed: true, width: w, height: h, duration: Date.now() - start };
          }
        }
      } catch (_) { /* ignore */ }
      await new Promise(r => setTimeout(r, 100));
    }
    return { path, passed: false, duration: Date.now() - start };
  }

  async verifyImagesEqual(path1, path2, options = {}) {
    const tolerance = options.tolerance || this.options.pixelTolerance;
    try {
      const fs = require('fs');
      if (!fs.existsSync(path1) || !fs.existsSync(path2)) {
        return { path1, path2, passed: false, error: 'one or both files missing' };
      }
      const buf1 = fs.readFileSync(path1);
      const buf2 = fs.readFileSync(path2);
      if (buf1.length !== buf2.length) {
        return { path1, path2, passed: false, reason: 'size mismatch', size1: buf1.length, size2: buf2.length };
      }
      let diffPixels = 0;
      const totalPixels = buf1.length;
      for (let i = 0; i < buf1.length; i++) {
        if (buf1[i] !== buf2[i]) diffPixels++;
      }
      const diffRatio = diffPixels / totalPixels;
      const passed = diffRatio <= tolerance;
      return { path1, path2, passed, diffRatio, tolerance, duration: 0 };
    } catch (e) {
      return { path1, path2, passed: false, error: e.message };
    }
  }

  async verifyImageChanged(path, baselinePath, options = {}) {
    const tolerance = options.tolerance || this.options.pixelTolerance;
    const result = await this.verifyImagesEqual(path, baselinePath, { tolerance });
    return { ...result, passed: !result.passed };
  }
}

// 10. CustomVerifier — Custom verifiers (JS + native C++ bridge)
class CustomVerifier {
  constructor(options = {}) {
    this.options = {
      timeout: options.timeout || 5000,
      nativeLibPath: options.nativeLibPath || null,
      ...options,
    };
    this.verifiers = new Map();
    this.nativeAvailable = false;
    this._initNative();
  }

  _initNative() {
    // Try to load native verifier bridge if available
    // Native C++ source lives at: hackathon_ui_operator_distill/native/verifier_bridge.cpp
    // Compiled binary expected at: ai_pc_operator/data/native/verifier_bridge.node
    try {
      const path = require('path');
      const candidates = [
        this.options.nativeLibPath,
        path.join(process.cwd(), 'ai_pc_operator', 'data', 'native', 'verifier_bridge.node'),
        path.join(process.cwd(), '..', 'ai_pc_operator', 'data', 'native', 'verifier_bridge.node'),
        path.join(__dirname, '..', 'data', 'native', 'verifier_bridge.node'),
      ].filter(Boolean);
      for (const candidate of candidates) {
        try {
          const native = require(candidate);
          if (native && typeof native.verify === 'function') {
            this.native = native;
            this.nativeAvailable = true;
            return;
          }
        } catch (_) { /* try next */ }
      }
    } catch (_) { /* native not available */ }
  }

  register(name, verifierFn, options = {}) {
    this.verifiers.set(name, {
      fn: verifierFn,
      timeout: options.timeout || this.options.timeout,
      description: options.description || '',
    });
    return this;
  }

  async verify(name, context = {}) {
    const verifier = this.verifiers.get(name);
    if (!verifier) {
      return { name, passed: false, error: 'verifier not registered', timestamp: Date.now() };
    }
    const start = Date.now();
    try {
      const result = await Promise.race([
        Promise.resolve(verifier.fn(context)),
        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), verifier.timeout)),
      ]);
      const passed = result === true || (result && result.passed === true);
      return { name, passed, duration: Date.now() - start, timestamp: Date.now() };
    } catch (e) {
      return { name, passed: false, error: e.message, duration: Date.now() - start, timestamp: Date.now() };
    }
  }

  async verifyNative(checkType, target, options = {}) {
    if (!this.nativeAvailable) {
      return { checkType, target, passed: false, error: 'native verifier not available', fallback: 'js' };
    }
    try {
      const result = this.native.verify(checkType, target, options);
      return { checkType, target, passed: result.passed, details: result.details || null };
    } catch (e) {
      return { checkType, target, passed: false, error: e.message };
    }
  }

  list() {
    return Array.from(this.verifiers.entries()).map(([name, v]) => ({
      name,
      description: v.description,
      timeout: v.timeout,
    }));
  }

  unregister(name) {
    return this.verifiers.delete(name);
  }

  isNativeAvailable() {
    return this.nativeAvailable;
  }
}

// Global instances for Phase 8
const globalStateVerifier = new StateVerifier();
const globalUIVerifier = new UIVerifier();
const globalDOMVerifier = new DOMVerifier();
const globalOCRVerifier = new OCRVerifier();
const globalFilesystemVerifier = new FilesystemVerifier();
const globalAPIVerifier = new APIVerifier();
const globalProcessVerifier = new ProcessVerifier();
const globalWindowVerifier = new WindowVerifier();
const globalImageVerifier = new ImageVerifier();
const globalCustomVerifier = new CustomVerifier();

// ============================================================================
// NATIVE BRIDGE — Unified C++ accelerator for all phases
// ============================================================================
// Loads hackathon_ui_operator_distill/native/screenai_core.cpp compiled as
// ai_pc_operator/data/native/screenai_core.node. Falls back to pure-JS when
// the native addon is not present (non-fatal).
//
// Op codes (see screenai_core.h):
//   0  = monotonic_ms
//   1  = sleep_ms
//   10 = enumerate_processes
//   11 = enumerate_windows
//   12 = get_focused_window_title
//   20 = string_similarity
//   21 = normalize_intent
//   30 = compute_plan_cost
//   31 = compute_risk_score
//   32 = topological_sort
//   40 = get_cpu_percent
//   41 = get_memory_usage
//   42 = get_disk_usage
//   43 = get_network_stats
//   44 = get_uptime_seconds
//   50 = verify (Phase 8)
// ============================================================================

class NativeBridge {
  constructor(options = {}) {
    this.options = options;
    this.native = null;
    this.available = false;
    this._init();
  }

  _init() {
    try {
      const path = require('path');
      const candidates = [
        this.options.libPath,
        path.join(process.cwd(), 'ai_pc_operator', 'data', 'native', 'screenai_core.node'),
        path.join(process.cwd(), '..', 'ai_pc_operator', 'data', 'native', 'screenai_core.node'),
        path.join(__dirname, '..', 'data', 'native', 'screenai_core.node'),
        path.join(__dirname, '..', '..', 'ai_pc_operator', 'data', 'native', 'screenai_core.node'),
      ].filter(Boolean);
      for (const candidate of candidates) {
        try {
          const mod = require(candidate);
          if (mod && typeof mod.call === 'function') {
            this.native = mod;
            this.available = true;
            return;
          }
        } catch (_) { /* try next */ }
      }
    } catch (_) { /* native not available */ }
  }

  call(op, input = '') {
    if (!this.available) return null;
    try {
      return this.native.call(op, input);
    } catch (e) {
      return null;
    }
  }

  // Convenience wrappers
  monotonicMs() {
    const r = this.call(0);
    return r !== null ? parseInt(r, 10) : Date.now();
  }

  sleepMs(ms) {
    if (this.available) this.call(1, String(ms));
    else {
      const start = Date.now();
      while (Date.now() - start < ms) { /* busy wait fallback */ }
    }
  }

  enumerateProcesses(maxCount = 256) {
    const r = this.call(10, String(maxCount));
    if (!r) return [];
    try { return JSON.parse(r); } catch (_) { return []; }
  }

  enumerateWindows(maxCount = 128) {
    const r = this.call(11, String(maxCount));
    if (!r) return [];
    try { return JSON.parse(r); } catch (_) { return []; }
  }

  getFocusedWindowTitle() {
    const r = this.call(12);
    if (!r) return '';
    try {
      const parsed = JSON.parse(r);
      return typeof parsed === 'string' ? parsed : '';
    } catch (_) { return ''; }
  }

  stringSimilarity(a, b) {
    const r = this.call(20, a + '|' + b);
    if (r !== null) return parseFloat(r);
    // JS fallback: Jaccard similarity on word tokens
    if (!a || !b) return 0;
    const tokA = new Set(a.toLowerCase().split(/\W+/).filter(Boolean));
    const tokB = new Set(b.toLowerCase().split(/\W+/).filter(Boolean));
    if (tokA.size === 0 && tokB.size === 0) return 1;
    let inter = 0;
    for (const t of tokA) if (tokB.has(t)) inter++;
    const union = tokA.size + tokB.size - inter;
    return union > 0 ? Math.round((inter / union) * 100) / 100 : 0;
  }

  normalizeIntent(s) {
    const r = this.call(21, s);
    if (r === null) return s.toLowerCase().trim();
    try {
      const parsed = JSON.parse(r);
      return typeof parsed === 'string' ? parsed : s;
    } catch (_) { return s; }
  }

  computePlanCost(costs) {
    const r = this.call(30, costs.join(','));
    return r !== null ? parseFloat(r) : costs.reduce((a, b) => a + b, 0);
  }

  computeRiskScore(risks) {
    const r = this.call(31, risks.join(','));
    if (r !== null) return parseFloat(r);
    // JS fallback: weighted max + average
    if (!Array.isArray(risks) || risks.length === 0) return 0;
    const max = Math.max(...risks);
    const avg = risks.reduce((a, b) => a + b, 0) / risks.length;
    return Math.round((max * 0.7 + avg * 0.3) * 100) / 100;
  }

  topologicalSort(n, adj) {
    const adjStr = adj.map(row => row.join(',')).join(';');
    const r = this.call(32, n + '|' + adjStr);
    if (r) {
      try {
        const parsed = JSON.parse(r);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      } catch (_) { /* fall through */ }
    }
    // JS fallback: Kahn's algorithm
    if (!n || !Array.isArray(adj)) return null;
    const inDeg = new Array(n).fill(0);
    for (const row of adj) {
      if (!Array.isArray(row)) continue;
      for (const v of row) {
        if (v >= 0 && v < n) inDeg[v]++;
      }
    }
    const queue = [];
    for (let i = 0; i < n; i++) if (inDeg[i] === 0) queue.push(i);
    const result = [];
    while (queue.length > 0) {
      const u = queue.shift();
      result.push(u);
      if (Array.isArray(adj[u])) {
        for (const v of adj[u]) {
          if (v >= 0 && v < n) {
            inDeg[v]--;
            if (inDeg[v] === 0) queue.push(v);
          }
        }
      }
    }
    return result.length === n ? result : null;
  }

  getCpuPercent() {
    const r = this.call(40);
    if (r !== null) return parseFloat(r);
    // JS fallback: estimate from process.cpuUsage
    try {
      const cpus = require('os').cpus();
      let total = 0, idle = 0;
      for (const cpu of cpus) {
        const t = cpu.times;
        total += t.user + t.nice + t.sys + t.idle + t.irq;
        idle += t.idle;
      }
      return total > 0 ? Math.round((1 - idle / total) * 100 * 100) / 100 : 0;
    } catch (_) { return 0; }
  }

  getMemoryUsage() {
    const r = this.call(41);
    if (r) {
      try { return JSON.parse(r); } catch (_) { /* fall through */ }
    }
    // JS fallback: process.memoryUsage + os.totalmem
    try {
      const os = require('os');
      const mu = process.memoryUsage();
      const total = os.totalmem();
      const used = mu.rss + (total - os.freemem());
      return { used, total };
    } catch (_) { return { used: 0, total: 0 }; }
  }

  getDiskUsage(path) {
    const r = this.call(42, path);
    if (r) {
      try { return JSON.parse(r); } catch (_) { /* fall through */ }
    }
    // JS fallback: statfs if available, else 0
    try {
      const fs = require('fs');
      const target = path || '.';
      const stat = fs.statfsSync(target);
      const total = stat.blocks * stat.bsize;
      const free = stat.bavail * stat.bsize;
      return { used: total - free, total };
    } catch (_) { return { used: 0, total: 0 }; }
  }

  getNetworkStats() {
    const r = this.call(43);
    if (r) {
      try { return JSON.parse(r); } catch (_) { /* fall through */ }
    }
    // JS fallback: no per-process network stats available
    return { rx: 0, tx: 0 };
  }

  getUptimeSeconds() {
    const r = this.call(44);
    return r !== null ? parseInt(r, 10) : Math.floor(process.uptime());
  }

  verify(checkType, target, options = '') {
    const r = this.call(50, checkType + '|' + target + '|' + options);
    if (!r) return null;
    try { return JSON.parse(r); } catch (_) { return null; }
  }

  // ===== PHASE 9 — RECOVERY ENGINE: Op codes 60-69 =====

  // Op 60: classify failure (returns category string)
  classifyFailure(errorMsg) {
    const r = this.call(60, errorMsg || '');
    if (r) {
      try { return JSON.parse(r); } catch (_) { return null; }
    }
    // JS fallback: simple keyword classifier
    if (!errorMsg) return 'unknown';
    const msg = String(errorMsg).toLowerCase();
    if (msg.includes('timeout') || msg.includes('timed out')) return 'timeout';
    if (msg.includes('permission') || msg.includes('denied') || msg.includes('forbidden')) return 'permission';
    if (msg.includes('network') || msg.includes('econnrefused') || msg.includes('enotfound')) return 'network';
    if (msg.includes('not found') || msg.includes('enoent')) return 'not_found';
    if (msg.includes('crash') || msg.includes('segfault') || msg.includes('panic')) return 'crash';
    if (msg.includes('memory') || msg.includes('oom')) return 'memory';
    if (msg.includes('validation') || msg.includes('invalid')) return 'validation';
    if (msg.includes('rate') || msg.includes('limit') || msg.includes('429')) return 'rate_limit';
    return 'unknown';
  }

  // Op 61: compute backoff delay (ms) given attempt number and base
  computeBackoff(attempt, baseMs) {
    const r = this.call(61, attempt + '|' + baseMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: exponential backoff with jitter
    const base = Math.max(0, parseInt(baseMs, 10) || 100);
    const exp = Math.min(attempt, 10);
    const delay = base * Math.pow(2, exp);
    const jitter = Math.random() * delay * 0.1;
    return Math.floor(delay + jitter);
  }

  // Op 62: hash error signature for deduplication
  hashErrorSignature(errorMsg) {
    const r = this.call(62, errorMsg || '');
    if (r) return r;
    // JS fallback: simple djb2 hash
    const s = String(errorMsg || '');
    let hash = 5381;
    for (let i = 0; i < s.length; i++) {
      hash = ((hash << 5) + hash) + s.charCodeAt(i);
      hash = hash & 0xffffffff;
    }
    return 'sig_' + (hash >>> 0).toString(16);
  }

  // Op 63: compute retry budget remaining
  computeRetryBudget(used, max) {
    const r = this.call(63, used + '|' + max);
    if (r !== null) return parseInt(r, 10);
    return Math.max(0, (parseInt(max, 10) || 0) - (parseInt(used, 10) || 0));
  }

  // ===== PHASE 10 — EVENT SYSTEM: Op codes 70-74 =====

  // Op 70: get monotonic timestamp for event ordering
  eventTimestamp() {
    const r = this.call(70);
    if (r !== null) return parseInt(r, 10);
    return Date.now();
  }

  // Op 71: generate a unique event id
  generateEventId(prefix) {
    const r = this.call(71, prefix || 'evt');
    if (r) return r;
    return (prefix || 'evt') + '_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
  }

  // Op 72: hash event payload for dedup
  hashEventPayload(payload) {
    const r = this.call(72, payload || '');
    if (r) return r;
    // JS fallback: djb2 hash
    const s = String(payload || '');
    let hash = 5381;
    for (let i = 0; i < s.length; i++) {
      hash = ((hash << 5) + hash) + s.charCodeAt(i);
      hash = hash & 0xffffffff;
    }
    return 'evt_' + (hash >>> 0).toString(16);
  }

  // Op 73: compute event priority score
  computeEventPriority(eventType, ageMs) {
    const r = this.call(73, eventType + '|' + ageMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: priority by event type
    const basePriority = {
      'PipelineFailed': 100,
      'UserInterrupted': 95,
      'ApprovalGranted': 90,
      'ApprovalRejected': 90,
      'PipelineStarted': 50,
      'PipelineCompleted': 40,
      'WindowOpened': 30,
      'BrowserLoaded': 30,
      'DownloadFinished': 30,
      'FileChanged': 20,
      'OCRCompleted': 20,
      'VisionDetected': 20,
      'ContextUpdated': 10
    };
    const base = basePriority[eventType] || 25;
    // Older events get lower priority
    const age = Math.max(0, parseInt(ageMs, 10) || 0);
    return Math.max(0, base - Math.floor(age / 1000));
  }

  // ===== PHASE 11 — MEMORY SYSTEM: Op codes 80-83 =====

  // Op 80: compute memory relevance score
  computeMemoryRelevance(query, key, ageMs) {
    const r = this.call(80, query + '|' + key + '|' + ageMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: token overlap + recency
    const qTokens = String(query || '').toLowerCase().split(/\s+/).filter(Boolean);
    const kTokens = String(key || '').toLowerCase().split(/\s+/).filter(Boolean);
    let overlap = 0;
    for (const t of qTokens) {
      if (kTokens.includes(t)) overlap++;
    }
    const tokenScore = qTokens.length > 0 ? Math.round((overlap / qTokens.length) * 70) : 0;
    const age = Math.max(0, parseInt(ageMs, 10) || 0);
    const recencyScore = Math.max(0, 30 - Math.floor(age / 86400000)); // decay over days
    return Math.min(100, tokenScore + recencyScore);
  }

  // Op 81: hash memory key for indexing
  hashMemoryKey(key) {
    const r = this.call(81, key || '');
    if (r) return r;
    // JS fallback: djb2 hash
    const s = String(key || '');
    let hash = 5381;
    for (let i = 0; i < s.length; i++) {
      hash = ((hash << 5) + hash) + s.charCodeAt(i);
      hash = hash & 0xffffffff;
    }
    return 'mem_' + (hash >>> 0).toString(16);
  }

  // Op 82: compute memory TTL in ms
  computeMemoryTTL(importance, ageMs) {
    const r = this.call(82, importance + '|' + ageMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: importance-based TTL
    const imp = Math.max(0, Math.min(100, parseInt(importance, 10) || 50));
    const baseTTL = 86400000; // 1 day
    return Math.round(baseTTL * (imp / 50));
  }

  // Op 83: compute memory cleanup priority
  computeCleanupPriority(ageMs, accessCount, importance) {
    const r = this.call(83, ageMs + '|' + accessCount + '|' + importance);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: high age + low access + low importance = high cleanup priority
    const age = Math.max(0, parseInt(ageMs, 10) || 0);
    const access = Math.max(0, parseInt(accessCount, 10) || 0);
    const imp = Math.max(0, Math.min(100, parseInt(importance, 10) || 50));
    const ageScore = Math.min(50, Math.floor(age / 86400000));
    const accessScore = Math.max(0, 30 - access * 3);
    const impScore = Math.max(0, 20 - Math.floor(imp / 5));
    return ageScore + accessScore + impScore;
  }

  // ===== PHASE 13 — SKILL ORCHESTRATOR: Op codes 90-93 =====

  // Op 90: compute skill match score
  computeSkillMatch(query, skillName, tags) {
    const r = this.call(90, query + '|' + skillName + '|' + (tags || ''));
    if (r !== null) return parseInt(r, 10);
    // JS fallback: token overlap + tag match
    const qTokens = String(query || '').toLowerCase().split(/\s+/).filter(Boolean);
    const sTokens = String(skillName || '').toLowerCase().split(/[_\s]+/).filter(Boolean);
    const tagList = String(tags || '').toLowerCase().split(',').map(t => t.trim()).filter(Boolean);
    let overlap = 0;
    for (const t of qTokens) {
      if (sTokens.includes(t)) overlap++;
    }
    const tokenScore = qTokens.length > 0 ? Math.round((overlap / qTokens.length) * 60) : 0;
    let tagScore = 0;
    for (const t of qTokens) {
      if (tagList.includes(t)) tagScore += 10;
    }
    return Math.min(100, tokenScore + tagScore);
  }

  // Op 91: compute skill health score
  computeSkillHealth(successCount, failCount, avgDurationMs) {
    const r = this.call(91, successCount + '|' + failCount + '|' + avgDurationMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: success rate weighted by recency
    const s = Math.max(0, parseInt(successCount, 10) || 0);
    const f = Math.max(0, parseInt(failCount, 10) || 0);
    const total = s + f;
    if (total === 0) return 50; // unknown
    const successRate = s / total;
    const duration = Math.max(0, parseInt(avgDurationMs, 10) || 0);
    const speedScore = duration > 0 ? Math.max(0, 20 - Math.floor(duration / 1000)) : 20;
    return Math.round(successRate * 80 + speedScore);
  }

  // Op 92: compute skill chain cost
  computeSkillChainCost(skills) {
    const r = this.call(92, Array.isArray(skills) ? skills.join(',') : String(skills || ''));
    if (r !== null) return parseInt(r, 10);
    // JS fallback: sum of skill costs
    const list = Array.isArray(skills) ? skills : String(skills || '').split(',');
    return list.length * 10;
  }

  // Op 93: compute skill retry budget
  computeSkillRetryBudget(used, max) {
    const r = this.call(93, used + '|' + max);
    if (r !== null) return parseInt(r, 10);
    return Math.max(0, (parseInt(max, 10) || 0) - (parseInt(used, 10) || 0));
  }

  // ===== PHASE 14 — STATE MANAGER: Op codes 100-103 =====

  // Op 100: compute state hash for change detection
  computeStateHash(stateJson) {
    const r = this.call(100, String(stateJson || ''));
    if (r !== null) return r;
    // JS fallback: djb2 hash
    const s = String(stateJson || '');
    let hash = 5381;
    for (let i = 0; i < s.length; i++) {
      hash = ((hash << 5) + hash) + s.charCodeAt(i);
      hash = hash & 0xffffffff;
    }
    return 'st_' + (hash >>> 0).toString(16);
  }

  // Op 101: compute state diff score (0-100, higher = more different)
  computeStateDiff(hashA, hashB) {
    const r = this.call(101, hashA + '|' + hashB);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: simple char-by-char comparison
    const a = String(hashA || '');
    const b = String(hashB || '');
    if (a === b) return 0;
    const maxLen = Math.max(a.length, b.length);
    let diff = 0;
    for (let i = 0; i < maxLen; i++) {
      if (a[i] !== b[i]) diff++;
    }
    return Math.min(100, Math.round((diff / maxLen) * 100));
  }

  // Op 102: compute state freshness score (0-100, higher = fresher)
  computeStateFreshness(ageMs, maxAgeMs) {
    const r = this.call(102, ageMs + '|' + maxAgeMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: linear decay
    const age = Math.max(0, parseInt(ageMs, 10) || 0);
    const max = Math.max(1, parseInt(maxAgeMs, 10) || 1);
    if (age >= max) return 0;
    return Math.round((1 - age / max) * 100);
  }

  // Op 103: compute state priority for eviction (0-100, higher = evict first)
  computeStateEvictionPriority(ageMs, accessCount, sizeBytes) {
    const r = this.call(103, ageMs + '|' + accessCount + '|' + sizeBytes);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: high age + low access + large size = high eviction priority
    const age = Math.max(0, parseInt(ageMs, 10) || 0);
    const access = Math.max(0, parseInt(accessCount, 10) || 0);
    const size = Math.max(0, parseInt(sizeBytes, 10) || 0);
    const ageScore = Math.min(40, Math.floor(age / 60000));
    const accessScore = Math.max(0, 30 - access * 3);
    const sizeScore = Math.min(30, Math.floor(size / 1024));
    return ageScore + accessScore + sizeScore;
  }

  // Op 110: compute workflow complexity score (0-100)
  computeWorkflowComplexity(nodeCount, maxDepth) {
    const r = this.call(110, nodeCount + '|' + maxDepth);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: node count + depth weighted
    const nodes = Math.max(0, parseInt(nodeCount, 10) || 0);
    const depth = Math.max(0, parseInt(maxDepth, 10) || 0);
    const nodeScore = Math.min(60, nodes * 5);
    const depthScore = Math.min(40, depth * 10);
    return Math.min(100, nodeScore + depthScore);
  }

  // Op 111: compute workflow parallelism score (0-100)
  computeWorkflowParallelism(branchCount, maxWidth) {
    const r = this.call(111, branchCount + '|' + maxWidth);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: branch count + width weighted
    const branches = Math.max(0, parseInt(branchCount, 10) || 0);
    const width = Math.max(0, parseInt(maxWidth, 10) || 0);
    const branchScore = Math.min(60, branches * 15);
    const widthScore = Math.min(40, width * 10);
    return Math.min(100, branchScore + widthScore);
  }

  // Op 112: compute workflow schedule priority (0-100)
  computeWorkflowPriority(priority, dueInMs) {
    const r = this.call(112, priority + '|' + dueInMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: priority + due time weighted
    const p = Math.max(0, parseInt(priority, 10) || 0);
    const due = parseInt(dueInMs, 10) || 0;
    const priorityScore = Math.min(60, p * 10);
    let dueScore = 0;
    if (due <= 0) dueScore = 40;
    else if (due < 60000) dueScore = 35;
    else if (due < 300000) dueScore = 25;
    else if (due < 3600000) dueScore = 15;
    else dueScore = 5;
    return Math.min(100, priorityScore + dueScore);
  }

  // Op 113: compute workflow retry budget remaining
  computeWorkflowRetryBudget(used, max) {
    const r = this.call(113, used + '|' + max);
    if (r !== null) return parseInt(r, 10);
    // JS fallback: max - used, clamped to >= 0
    const u = Math.max(0, parseInt(used, 10) || 0);
    const m = Math.max(0, parseInt(max, 10) || 0);
    return Math.max(0, m - u);
  }

  // Op 120: compute provider selection score (health 50% + cost 20% + latency 30%)
  computeProviderScore(health, cost, latencyMs) {
    const r = this.call(120, health + '|' + cost + '|' + latencyMs);
    if (r !== null) return parseInt(r, 10);
    // JS fallback
    const h = Math.max(0, Math.min(100, parseInt(health, 10) || 0));
    const c = Math.max(0, Math.min(100, parseInt(cost, 10) || 0));
    const l = parseInt(latencyMs, 10) || 0;
    const costScore = 100 - c;
    let latencyScore = 0;
    if (l <= 0) latencyScore = 100;
    else if (l < 100) latencyScore = 95;
    else if (l < 500) latencyScore = 80;
    else if (l < 2000) latencyScore = 60;
    else if (l < 10000) latencyScore = 30;
    else latencyScore = 10;
    return Math.min(100, Math.floor((h * 50 + costScore * 20 + latencyScore * 30) / 100));
  }

  // Op 121: compute fallback chain depth score
  computeFallbackDepth(chainLength, reliability) {
    const r = this.call(121, chainLength + '|' + reliability);
    if (r !== null) return parseInt(r, 10);
    // JS fallback
    const cl = Math.max(0, parseInt(chainLength, 10) || 0);
    const rel = Math.max(0, Math.min(100, parseInt(reliability, 10) || 0));
    const lengthScore = Math.min(60, cl * 15);
    const reliabilityScore = Math.min(40, Math.floor(rel / 2));
    return Math.min(100, lengthScore + reliabilityScore);
  }

  // Op 122: compute load balancing weight (free capacity %)
  computeLoadWeight(capacity, currentLoad) {
    const r = this.call(122, capacity + '|' + currentLoad);
    if (r !== null) return parseInt(r, 10);
    // JS fallback
    const cap = parseInt(capacity, 10) || 0;
    if (cap <= 0) return 0;
    const load = Math.min(cap, Math.max(0, parseInt(currentLoad, 10) || 0));
    return Math.min(100, Math.floor(((cap - load) * 100) / cap));
  }

  // Op 123: compute circuit breaker state (0=closed, 1=half-open, 2=open)
  computeCircuitState(failureCount, threshold) {
    const r = this.call(123, failureCount + '|' + threshold);
    if (r !== null) return parseInt(r, 10);
    // JS fallback
    const f = Math.max(0, parseInt(failureCount, 10) || 0);
    const t = parseInt(threshold, 10) || 0;
    if (t <= 0) return 0;
    if (f >= t) return 2;
    if (f >= Math.floor(t / 2)) return 1;
    return 0;
  }

  // Op 130: compute stage priority (0-100) from stage name and age
  computeStagePriority(stage, ageMs) {
    const r = this.call(130, stage + '|' + (ageMs || 0));
    if (r !== null) return parseInt(r, 10);
    // JS fallback
    const basePriorities = {
      intent: 90, context: 80, plan: 85, graph: 75,
      registry: 60, runtime: 95, skills: 70, observe: 65,
      verify: 85, recover: 90, memory: 50, complete: 40,
    };
    const base = basePriorities[stage] || 50;
    const decay = Math.floor((ageMs || 0) / 1000);
    return Math.max(0, Math.min(100, base - decay));
  }

  // Op 131: hash runtime request for dedup
  hashRuntimeRequest(requestJson) {
    const r = this.call(131, requestJson || '');
    if (r !== null) return r;
    // JS fallback: djb2 hash
    let hash = 5381;
    const s = requestJson || '';
    for (let i = 0; i < s.length; i++) {
      hash = ((hash << 5) + hash) + s.charCodeAt(i);
      hash = hash & hash;
    }
    return 'rt_' + (hash >>> 0).toString(16);
  }

  // Op 132: compute runtime relevance (0-100) from text and query
  computeRuntimeRelevance(text, query) {
    const r = this.call(132, (text || '') + '|' + (query || ''));
    if (r !== null) return parseInt(r, 10);
    // JS fallback: token overlap
    if (!text || !query) return 0;
    const textWords = text.toLowerCase().split(/\s+/);
    const queryWords = query.toLowerCase().split(/\s+/);
    if (queryWords.length === 0) return 0;
    let matches = 0;
    for (const qw of queryWords) {
      if (textWords.includes(qw)) matches++;
    }
    return Math.min(100, Math.floor((matches * 100) / queryWords.length));
  }

  // Op 133: compute stage transition cost (0-100)
  computeStageTransitionCost(source, target) {
    const r = this.call(133, (source || '') + '|' + (target || ''));
    if (r !== null) return parseInt(r, 10);
    // JS fallback
    if (source === target) return 90;
    const naturalFlow = [
      ['intent', 'context'], ['context', 'plan'], ['plan', 'graph'],
      ['graph', 'registry'], ['registry', 'runtime'], ['runtime', 'skills'],
      ['skills', 'observe'], ['observe', 'verify'], ['verify', 'recover'],
      ['recover', 'memory'], ['memory', 'complete'],
    ];
    for (const [s, t] of naturalFlow) {
      if (s === source && t === target) return 10;
    }
    return 50;
  }

  isAvailable() {
    return this.available;
  }
}

const globalNativeBridge = new NativeBridge();

// ============================================================================
// PHASE 9 — RECOVERY ENGINE: 10 utilities for automatic failure recovery
// ============================================================================
//
// Recovery Engine handles:
//   - Retry strategies (exponential, linear, custom)
//   - Alternative pipelines (fallback when primary fails)
//   - Rollback (undo previous actions)
//   - Re-observation (re-scan state after failure)
//   - Replanning (generate new sub-plan)
//   - Safe abort (graceful shutdown)
//   - User approval (request intervention)
//   - Failure classification (categorize errors)
//   - Error recovery policies (rules per category)
//   - Recovery history (learn from past failures)
//

// ----- 1. RetryStrategy: configurable retry with backoff -----
class RetryStrategy {
  constructor(options = {}) {
    this.options = {
      maxAttempts: options.maxAttempts || 3,
      baseDelayMs: options.baseDelayMs || 100,
      maxDelayMs: options.maxDelayMs || 30000,
      backoff: options.backoff || 'exponential', // 'exponential' | 'linear' | 'fixed'
      jitter: options.jitter !== false,
      retryOn: options.retryOn || null, // function(error) => bool
      ...options
    };
    this.attempts = 0;
    this.history = [];
  }

  shouldRetry(error) {
    if (this.attempts >= this.options.maxAttempts) return false;
    if (typeof this.options.retryOn === 'function') {
      return this.options.retryOn(error);
    }
    // Default: retry on transient errors
    const category = globalNativeBridge.classifyFailure(error?.message || String(error));
    return ['timeout', 'network', 'rate_limit', 'memory'].includes(category);
  }

  nextDelay() {
    const attempt = this.attempts;
    const base = this.options.baseDelayMs;
    let delay;
    if (this.options.backoff === 'linear') {
      delay = base * (attempt + 1);
    } else if (this.options.backoff === 'fixed') {
      delay = base;
    } else {
      // exponential
      delay = globalNativeBridge.computeBackoff(attempt, base);
    }
    return Math.min(delay, this.options.maxDelayMs);
  }

  async execute(fn) {
    let lastError;
    while (this.attempts < this.options.maxAttempts) {
      try {
        const result = await fn(this.attempts);
        this.history.push({ attempt: this.attempts, success: true });
        return result;
      } catch (err) {
        lastError = err;
        this.attempts++;
        this.history.push({ attempt: this.attempts - 1, success: false, error: err.message });
        if (!this.shouldRetry(err)) break;
        const delay = this.nextDelay();
        await new Promise(r => setTimeout(r, delay));
      }
    }
    throw lastError;
  }

  reset() {
    this.attempts = 0;
    this.history = [];
  }
}

// ----- 2. AlternativePipeline: fallback pipeline registry -----
class AlternativePipeline {
  constructor(options = {}) {
    this.options = options;
    this.alternatives = new Map(); // primary -> [fallback1, fallback2, ...]
    this.usageStats = new Map();   // pipeline -> { attempts, successes, failures }
  }

  register(primary, fallbacks) {
    if (!Array.isArray(fallbacks)) fallbacks = [fallbacks];
    this.alternatives.set(primary, fallbacks);
    if (!this.usageStats.has(primary)) {
      this.usageStats.set(primary, { attempts: 0, successes: 0, failures: 0 });
    }
    for (const fb of fallbacks) {
      if (!this.usageStats.has(fb)) {
        this.usageStats.set(fb, { attempts: 0, successes: 0, failures: 0 });
      }
    }
  }

  getAlternatives(primary) {
    return this.alternatives.get(primary) || [];
  }

  async tryWithFallback(primary, executor) {
    const stats = this.usageStats.get(primary) || { attempts: 0, successes: 0, failures: 0 };
    stats.attempts++;
    try {
      const result = await executor(primary);
      stats.successes++;
      return { pipeline: primary, result, fallback: false };
    } catch (err) {
      stats.failures++;
      const fallbacks = this.getAlternatives(primary);
      for (const fb of fallbacks) {
        const fbStats = this.usageStats.get(fb) || { attempts: 0, successes: 0, failures: 0 };
        fbStats.attempts++;
        try {
          const result = await executor(fb);
          fbStats.successes++;
          return { pipeline: fb, result, fallback: true, originalError: err.message };
        } catch (fbErr) {
          fbStats.failures++;
        }
      }
      throw err;
    }
  }

  getStats(pipeline) {
    return this.usageStats.get(pipeline) || null;
  }
}

// ----- 3. RollbackManager: undo previous actions -----
class RollbackManager {
  constructor(options = {}) {
    this.options = options;
    this.checkpoints = []; // stack of { id, action, undo, timestamp }
    this.undoLog = [];
  }

  checkpoint(id, action, undoFn) {
    const cp = { id, action, undo: undoFn, timestamp: Date.now() };
    this.checkpoints.push(cp);
    return cp;
  }

  async rollback(checkpointId) {
    const idx = this.checkpoints.findIndex(c => c.id === checkpointId);
    if (idx === -1) return { success: false, reason: 'not_found' };
    const cp = this.checkpoints[idx];
    try {
      await cp.undo();
      this.undoLog.push({ id: cp.id, action: cp.action, timestamp: Date.now(), success: true });
      // Remove this and all later checkpoints
      this.checkpoints = this.checkpoints.slice(0, idx);
      return { success: true, undone: cp.action };
    } catch (err) {
      this.undoLog.push({ id: cp.id, action: cp.action, timestamp: Date.now(), success: false, error: err.message });
      return { success: false, reason: 'undo_failed', error: err.message };
    }
  }

  async rollbackAll() {
    const results = [];
    while (this.checkpoints.length > 0) {
      const cp = this.checkpoints[this.checkpoints.length - 1];
      const r = await this.rollback(cp.id);
      results.push(r);
    }
    return results;
  }

  list() {
    return this.checkpoints.map(c => ({ id: c.id, action: c.action, timestamp: c.timestamp }));
  }
}

// ----- 4. ReObserver: re-scan state after failure -----
class ReObserver {
  constructor(options = {}) {
    this.options = { sources: options.sources || ['window', 'process', 'filesystem'], ...options };
    this.observations = [];
    this.subscribers = [];
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }

  async reobserve(context = {}) {
    const observation = {
      timestamp: Date.now(),
      sources: {},
      context
    };
    for (const source of this.options.sources) {
      try {
        observation.sources[source] = await this._observeSource(source, context);
      } catch (err) {
        observation.sources[source] = { error: err.message };
      }
    }
    this.observations.push(observation);
    this._notify({ type: 'reobserved', observation });
    return observation;
  }

  async _observeSource(source, context) {
    // Delegate to existing observers if available
    if (source === 'window' && typeof globalWindowObserver !== 'undefined') {
      return globalWindowObserver.list ? globalWindowObserver.list() : { ok: true };
    }
    if (source === 'process' && typeof globalProcessObserver !== 'undefined') {
      return globalProcessObserver.list ? globalProcessObserver.list() : { ok: true };
    }
    if (source === 'filesystem' && typeof globalFilesystemObserver !== 'undefined') {
      return globalFilesystemObserver.list ? globalFilesystemObserver.list() : { ok: true };
    }
    return { ok: true, source, timestamp: Date.now() };
  }

  getHistory() {
    return this.observations;
  }
}

// ----- 5. Replanner: generate new sub-plan after failure -----
class Replanner {
  constructor(options = {}) {
    this.options = options;
    this.originalPlan = null;
    this.replans = [];
  }

  setOriginalPlan(plan) {
    this.originalPlan = plan;
  }

  async replan(failureContext) {
    const replan = {
      timestamp: Date.now(),
      failureContext,
      newPlan: null,
      strategy: 'retry_with_modifications'
    };
    if (this.originalPlan && Array.isArray(this.originalPlan.nodes)) {
      // Strategy: skip failed node, continue with remaining
      const failedNodeId = failureContext?.failedNodeId;
      const remaining = this.originalPlan.nodes.filter(n => n.id !== failedNodeId);
      replan.newPlan = {
        ...this.originalPlan,
        nodes: remaining,
        replanned: true,
        skipped: failedNodeId ? [failedNodeId] : []
      };
    } else {
      replan.newPlan = { nodes: [], replanned: true, empty: true };
    }
    this.replans.push(replan);
    return replan;
  }

  getHistory() {
    return this.replans;
  }
}

// ----- 6. SafeAbort: graceful shutdown with cleanup -----
class SafeAbort {
  constructor(options = {}) {
    this.options = { timeoutMs: options.timeoutMs || 5000, ...options };
    this.aborted = false;
    this.cleanupFns = [];
    this.abortListeners = [];
  }

  registerCleanup(fn) {
    this.cleanupFns.push(fn);
  }

  onAbort(callback) {
    this.abortListeners.push(callback);
  }

  async abort(reason = 'user_requested') {
    if (this.aborted) return { alreadyAborted: true };
    this.aborted = true;
    const results = [];
    // Run cleanup in reverse order
    for (let i = this.cleanupFns.length - 1; i >= 0; i--) {
      try {
        await Promise.race([
          this.cleanupFns[i](),
          new Promise((_, rej) => setTimeout(() => rej(new Error('cleanup_timeout')), this.options.timeoutMs))
        ]);
        results.push({ success: true });
      } catch (err) {
        results.push({ success: false, error: err.message });
      }
    }
    // Notify listeners
    for (const cb of this.abortListeners) {
      try { cb({ reason, results }); } catch (_) { /* ignore */ }
    }
    return { aborted: true, reason, cleanupResults: results };
  }

  isAborted() {
    return this.aborted;
  }

  reset() {
    this.aborted = false;
    this.cleanupFns = [];
    this.abortListeners = [];
  }
}

// ----- 7. UserApprovalGate: request user intervention -----
class UserApprovalGate {
  constructor(options = {}) {
    this.options = { timeoutMs: options.timeoutMs || 30000, ...options };
    this.pending = new Map(); // requestId -> { resolve, reject, timeout }
    this.history = [];
  }

  async request(description, context = {}) {
    const requestId = 'req_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        this.pending.delete(requestId);
        this.history.push({ requestId, description, decision: 'timeout', timestamp: Date.now() });
        reject(new Error('approval_timeout'));
      }, this.options.timeoutMs);
      this.pending.set(requestId, { resolve, reject, timeout, description, context });
    });
  }

  approve(requestId, notes = '') {
    const entry = this.pending.get(requestId);
    if (!entry) return false;
    clearTimeout(entry.timeout);
    this.pending.delete(requestId);
    this.history.push({ requestId, description: entry.description, decision: 'approved', notes, timestamp: Date.now() });
    entry.resolve({ approved: true, notes });
    return true;
  }

  reject(requestId, reason = '') {
    const entry = this.pending.get(requestId);
    if (!entry) return false;
    clearTimeout(entry.timeout);
    this.pending.delete(requestId);
    this.history.push({ requestId, description: entry.description, decision: 'rejected', reason, timestamp: Date.now() });
    entry.reject(new Error('approval_rejected: ' + reason));
    return true;
  }

  listPending() {
    return Array.from(this.pending.entries()).map(([id, e]) => ({
      requestId: id,
      description: e.description,
      context: e.context
    }));
  }

  getHistory() {
    return this.history;
  }
}

// ----- 8. FailureClassifier: categorize errors -----
class FailureClassifier {
  constructor(options = {}) {
    this.options = { ...options };
    this.rules = [
      { category: 'timeout', patterns: [/timeout/i, /timed out/i, /etimedout/i] },
      { category: 'permission', patterns: [/permission/i, /denied/i, /forbidden/i, /eacces/i, /eperm/i] },
      { category: 'network', patterns: [/network/i, /econnrefused/i, /enotfound/i, /econnreset/i] },
      { category: 'not_found', patterns: [/not found/i, /enoent/i, /missing/i] },
      { category: 'crash', patterns: [/crash/i, /segfault/i, /panic/i, /abort/i] },
      { category: 'memory', patterns: [/memory/i, /oom/i, /out of memory/i] },
      { category: 'validation', patterns: [/validation/i, /invalid/i, /malformed/i] },
      { category: 'rate_limit', patterns: [/rate/i, /limit/i, /429/i, /too many/i] },
      { category: 'conflict', patterns: [/conflict/i, /already exists/i, /eexist/i] },
      { category: 'dependency', patterns: [/dependency/i, /requires/i, /missing dep/i] }
    ];
  }

  classify(error) {
    const msg = (error?.message || String(error) || '').toLowerCase();
    for (const rule of this.rules) {
      for (const pattern of rule.patterns) {
        if (pattern.test(msg)) {
          return { category: rule.category, pattern: pattern.source, message: msg };
        }
      }
    }
    return { category: 'unknown', pattern: null, message: msg };
  }

  isTransient(category) {
    return ['timeout', 'network', 'rate_limit', 'memory'].includes(category);
  }

  isFatal(category) {
    return ['crash', 'permission', 'validation'].includes(category);
  }
}

// ----- 9. RecoveryPolicy: rules per failure category -----
class RecoveryPolicy {
  constructor(options = {}) {
    this.policies = new Map();
    this.setDefaults();
    if (options.policies) {
      for (const [k, v] of Object.entries(options.policies)) {
        this.policies.set(k, v);
      }
    }
  }

  setDefaults() {
    this.policies.set('timeout', { action: 'retry', maxAttempts: 3, backoff: 'exponential' });
    this.policies.set('network', { action: 'retry', maxAttempts: 5, backoff: 'exponential' });
    this.policies.set('rate_limit', { action: 'retry', maxAttempts: 3, backoff: 'exponential', baseDelayMs: 1000 });
    this.policies.set('memory', { action: 'retry', maxAttempts: 2, backoff: 'linear' });
    this.policies.set('permission', { action: 'abort', reason: 'permission_denied' });
    this.policies.set('validation', { action: 'abort', reason: 'invalid_input' });
    this.policies.set('crash', { action: 'rollback', reason: 'process_crashed' });
    this.policies.set('not_found', { action: 'replan', reason: 'resource_missing' });
    this.policies.set('conflict', { action: 'replan', reason: 'state_conflict' });
    this.policies.set('dependency', { action: 'replan', reason: 'missing_dependency' });
    this.policies.set('unknown', { action: 'retry', maxAttempts: 1, backoff: 'fixed' });
  }

  getPolicy(category) {
    return this.policies.get(category) || this.policies.get('unknown');
  }

  setPolicy(category, policy) {
    this.policies.set(category, policy);
  }

  decide(category, context = {}) {
    const policy = this.getPolicy(category);
    return {
      category,
      action: policy.action,
      reason: policy.reason || null,
      maxAttempts: policy.maxAttempts || 1,
      backoff: policy.backoff || 'fixed',
      baseDelayMs: policy.baseDelayMs || 100,
      context
    };
  }
}

// ----- 10. RecoveryHistory: learn from past failures -----
class RecoveryHistory {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 1000, ...options };
    this.entries = [];
    this.signatureIndex = new Map(); // signature -> count
  }

  record(failure, recovery) {
    const signature = globalNativeBridge.hashErrorSignature(failure?.message || String(failure));
    const entry = {
      timestamp: Date.now(),
      signature,
      category: recovery?.category || 'unknown',
      action: recovery?.action || 'unknown',
      success: recovery?.success !== false,
      attempts: recovery?.attempts || 1,
      durationMs: recovery?.durationMs || 0,
      failure: failure?.message || String(failure)
    };
    this.entries.push(entry);
    this.signatureIndex.set(signature, (this.signatureIndex.get(signature) || 0) + 1);
    // Trim if over max
    if (this.entries.length > this.options.maxEntries) {
      const removed = this.entries.shift();
      const count = this.signatureIndex.get(removed.signature) || 1;
      if (count <= 1) {
        this.signatureIndex.delete(removed.signature);
      } else {
        this.signatureIndex.set(removed.signature, count - 1);
      }
    }
    return entry;
  }

  getFrequency(signature) {
    return this.signatureIndex.get(signature) || 0;
  }

  getMostCommon(limit = 10) {
    return Array.from(this.signatureIndex.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([signature, count]) => ({ signature, count }));
  }

  getSuccessRate(category) {
    const matching = this.entries.filter(e => e.category === category);
    if (matching.length === 0) return null;
    const successes = matching.filter(e => e.success).length;
    return successes / matching.length;
  }

  getRecent(limit = 20) {
    return this.entries.slice(-limit);
  }

  clear() {
    this.entries = [];
    this.signatureIndex.clear();
  }
}

// ----- Global instances -----
const globalRetryStrategy = new RetryStrategy();
const globalAlternativePipeline = new AlternativePipeline();
const globalRollbackManager = new RollbackManager();
const globalReObserver = new ReObserver();
const globalReplanner = new Replanner();
const globalSafeAbort = new SafeAbort();
const globalUserApprovalGate = new UserApprovalGate();
const globalFailureClassifier = new FailureClassifier();
const globalRecoveryPolicy = new RecoveryPolicy();
const globalRecoveryHistory = new RecoveryHistory();

// ----- Native hooks for Phase 9 -----
const _RetryStrategy_nativeBackoff = (attempt, base) => globalNativeBridge.computeBackoff(attempt, base);
const _FailureClassifier_nativeClassify = (msg) => globalNativeBridge.classifyFailure(msg);
const _RecoveryHistory_nativeHash = (msg) => globalNativeBridge.hashErrorSignature(msg);

// ============================================================================
// PHASE 10 — EVENT SYSTEM: 10 utilities for unified event communication
// ============================================================================
//
// Event System provides:
//   - EventBus: central pub/sub for all events
//   - EventTypes: typed event catalog
//   - EventEmitter: per-source event emission
//   - EventSubscriber: typed subscription with filters
//   - EventFilter: filter events by type/source/predicate
//   - EventRouter: route events to handlers
//   - EventRecorder: record events for replay
//   - EventReplayer: replay recorded events
//   - EventAggregator: aggregate events into summaries
//   - EventTracer: trace event flow for debugging
//

// ----- Event type catalog -----
const EVENT_TYPES = {
  // Pipeline lifecycle
  PipelineStarted: 'PipelineStarted',
  PipelineCompleted: 'PipelineCompleted',
  PipelineFailed: 'PipelineFailed',
  PipelineCancelled: 'PipelineCancelled',
  // Window events
  WindowOpened: 'WindowOpened',
  WindowClosed: 'WindowClosed',
  WindowFocused: 'WindowFocused',
  WindowResized: 'WindowResized',
  // Browser events
  BrowserLoaded: 'BrowserLoaded',
  BrowserNavigated: 'BrowserNavigated',
  BrowserTabChanged: 'BrowserTabChanged',
  // Download events
  DownloadStarted: 'DownloadStarted',
  DownloadProgress: 'DownloadProgress',
  DownloadFinished: 'DownloadFinished',
  DownloadFailed: 'DownloadFailed',
  // File events
  FileChanged: 'FileChanged',
  FileCreated: 'FileCreated',
  FileDeleted: 'FileDeleted',
  FileRenamed: 'FileRenamed',
  // OCR/Vision events
  OCRCompleted: 'OCRCompleted',
  OCRFailed: 'OCRFailed',
  VisionDetected: 'VisionDetected',
  VisionMatched: 'VisionMatched',
  // User events
  UserInterrupted: 'UserInterrupted',
  UserCommand: 'UserCommand',
  UserAction: 'UserAction',
  // Approval events
  ApprovalRequested: 'ApprovalRequested',
  ApprovalGranted: 'ApprovalGranted',
  ApprovalRejected: 'ApprovalRejected',
  ApprovalExpired: 'ApprovalExpired',
  // Context events
  ContextUpdated: 'ContextUpdated',
  ContextCleared: 'ContextCleared',
  // Recovery events
  RecoveryStarted: 'RecoveryStarted',
  RecoveryCompleted: 'RecoveryCompleted',
  RecoveryFailed: 'RecoveryFailed',
  // System events
  SystemError: 'SystemError',
  SystemWarning: 'SystemWarning',
  SystemInfo: 'SystemInfo'
};

// ----- 1. EventBus: central pub/sub -----
class EventBus {
  constructor(options = {}) {
    this.options = { maxQueueSize: options.maxQueueSize || 10000, ...options };
    this.subscribers = new Map(); // eventType -> [callback, ...]
    this.wildcardSubscribers = []; // catch-all subscribers
    this.queue = []; // pending events
    this.history = []; // recent events
    this.paused = false;
  }

  subscribe(eventType, callback) {
    if (typeof callback !== 'function') return () => {};
    if (eventType === '*' || eventType === undefined) {
      this.wildcardSubscribers.push(callback);
      return () => {
        const idx = this.wildcardSubscribers.indexOf(callback);
        if (idx !== -1) this.wildcardSubscribers.splice(idx, 1);
      };
    }
    if (!this.subscribers.has(eventType)) {
      this.subscribers.set(eventType, []);
    }
    this.subscribers.get(eventType).push(callback);
    return () => {
      const arr = this.subscribers.get(eventType);
      if (arr) {
        const idx = arr.indexOf(callback);
        if (idx !== -1) arr.splice(idx, 1);
      }
    };
  }

  publish(event) {
    const enriched = {
      id: event.id || globalNativeBridge.generateEventId('evt'),
      timestamp: event.timestamp || globalNativeBridge.eventTimestamp(),
      type: event.type,
      source: event.source || 'unknown',
      payload: event.payload || {},
      priority: event.priority !== undefined ? event.priority : globalNativeBridge.computeEventPriority(event.type, 0)
    };
    if (this.paused) {
      this.queue.push(enriched);
      if (this.queue.length > this.options.maxQueueSize) {
        this.queue.shift();
      }
      return enriched;
    }
    this._dispatch(enriched);
    this.history.push(enriched);
    if (this.history.length > this.options.maxQueueSize) {
      this.history.shift();
    }
    return enriched;
  }

  _dispatch(event) {
    const subs = this.subscribers.get(event.type) || [];
    for (const cb of subs) {
      try { cb(event); } catch (_) { /* ignore subscriber errors */ }
    }
    for (const cb of this.wildcardSubscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
    const queued = this.queue.slice();
    this.queue = [];
    for (const evt of queued) {
      this._dispatch(evt);
      this.history.push(evt);
    }
  }

  getHistory(limit = 100) {
    return this.history.slice(-limit);
  }

  clearHistory() {
    this.history = [];
  }
}

// ----- 2. EventTypes: typed event catalog -----
class EventTypes {
  constructor(options = {}) {
    this.options = options;
    this.catalog = new Map();
    this._initCatalog();
  }

  _initCatalog() {
    for (const [name, type] of Object.entries(EVENT_TYPES)) {
      this.catalog.set(type, {
        name,
        category: this._categorize(name),
        description: this._describe(name)
      });
    }
  }

  _categorize(name) {
    if (name.startsWith('Pipeline')) return 'pipeline';
    if (name.startsWith('Window')) return 'window';
    if (name.startsWith('Browser')) return 'browser';
    if (name.startsWith('Download')) return 'download';
    if (name.startsWith('File')) return 'file';
    if (name.startsWith('OCR') || name.startsWith('Vision')) return 'perception';
    if (name.startsWith('User')) return 'user';
    if (name.startsWith('Approval')) return 'approval';
    if (name.startsWith('Context')) return 'context';
    if (name.startsWith('Recovery')) return 'recovery';
    if (name.startsWith('System')) return 'system';
    return 'other';
  }

  _describe(name) {
    const descriptions = {
      PipelineStarted: 'A pipeline execution has started',
      PipelineCompleted: 'A pipeline execution has completed successfully',
      PipelineFailed: 'A pipeline execution has failed',
      WindowOpened: 'A new window has been opened',
      BrowserLoaded: 'A browser page has finished loading',
      DownloadFinished: 'A download has completed',
      FileChanged: 'A file has been modified',
      OCRCompleted: 'OCR recognition has completed',
      VisionDetected: 'Vision detection has found elements',
      UserInterrupted: 'User has interrupted execution',
      ApprovalGranted: 'User has approved a pending action',
      ContextUpdated: 'Context state has been updated'
    };
    return descriptions[name] || name;
  }

  get(type) {
    return this.catalog.get(type) || null;
  }

  list(category) {
    const results = [];
    for (const [type, info] of this.catalog.entries()) {
      if (!category || info.category === category) {
        results.push({ type, ...info });
      }
    }
    return results;
  }

  isValid(type) {
    return this.catalog.has(type);
  }
}

// ----- 3. EventEmitter: per-source event emission -----
class EventEmitter {
  constructor(source, bus) {
    this.source = source;
    this.bus = bus || globalEventBus;
    this.localListeners = new Map();
  }

  emit(type, payload = {}) {
    const event = {
      type,
      source: this.source,
      payload,
      timestamp: globalNativeBridge.eventTimestamp()
    };
    if (this.bus) this.bus.publish(event);
    const local = this.localListeners.get(type) || [];
    for (const cb of local) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
    return event;
  }

  on(type, callback) {
    if (!this.localListeners.has(type)) {
      this.localListeners.set(type, []);
    }
    this.localListeners.get(type).push(callback);
    return () => {
      const arr = this.localListeners.get(type);
      if (arr) {
        const idx = arr.indexOf(callback);
        if (idx !== -1) arr.splice(idx, 1);
      }
    };
  }
}

// ----- 4. EventSubscriber: typed subscription with filters -----
class EventSubscriber {
  constructor(options = {}) {
    this.options = options;
    this.filters = [];
    this.callback = null;
    this.bus = options.bus || globalEventBus;
    this.unsubscribe = null;
  }

  onType(type) {
    this.filters.push(evt => evt.type === type);
    return this;
  }

  onTypes(types) {
    if (!Array.isArray(types)) types = [types];
    this.filters.push(evt => types.includes(evt.type));
    return this;
  }

  onCategory(category) {
    this.filters.push(evt => {
      const info = globalEventTypes.get(evt.type);
      return info && info.category === category;
    });
    return this;
  }

  onSource(source) {
    this.filters.push(evt => evt.source === source);
    return this;
  }

  onPredicate(predicate) {
    if (typeof predicate === 'function') {
      this.filters.push(predicate);
    }
    return this;
  }

  onMinPriority(minPriority) {
    this.filters.push(evt => (evt.priority || 0) >= minPriority);
    return this;
  }

  subscribe(callback) {
    this.callback = callback;
    const wrapped = (event) => {
      for (const filter of this.filters) {
        if (!filter(event)) return;
      }
      try { callback(event); } catch (_) { /* ignore */ }
    };
    this.unsubscribe = this.bus.subscribe('*', wrapped);
    return this;
  }

  unsubscribe_() {
    if (this.unsubscribe) {
      this.unsubscribe();
      this.unsubscribe = null;
    }
    return this;
  }
}

// ----- 5. EventFilter: filter events by criteria -----
class EventFilter {
  constructor(options = {}) {
    this.options = options;
    this.criteria = {
      types: options.types || null,
      sources: options.sources || null,
      categories: options.categories || null,
      minPriority: options.minPriority || 0,
      since: options.since || null,
      until: options.until || null,
      predicate: options.predicate || null
    };
  }

  matches(event) {
    if (this.criteria.types && !this.criteria.types.includes(event.type)) return false;
    if (this.criteria.sources && !this.criteria.sources.includes(event.source)) return false;
    if (this.criteria.categories) {
      const info = globalEventTypes.get(event.type);
      if (!info || !this.criteria.categories.includes(info.category)) return false;
    }
    if ((event.priority || 0) < this.criteria.minPriority) return false;
    if (this.criteria.since && event.timestamp < this.criteria.since) return false;
    if (this.criteria.until && event.timestamp > this.criteria.until) return false;
    if (this.criteria.predicate && !this.criteria.predicate(event)) return false;
    return true;
  }

  filter(events) {
    return events.filter(evt => this.matches(evt));
  }
}

// ----- 6. EventRouter: route events to handlers -----
class EventRouter {
  constructor(options = {}) {
    this.options = options;
    this.routes = new Map(); // pattern -> handler
    this.fallback = null;
  }

  route(pattern, handler) {
    this.routes.set(pattern, handler);
    return this;
  }

  setFallback(handler) {
    this.fallback = handler;
  }

  async route_(event) {
    // Try exact match first
    if (this.routes.has(event.type)) {
      try {
        await this.routes.get(event.type)(event);
        return { routed: true, pattern: event.type };
      } catch (err) {
        return { routed: false, error: err.message };
      }
    }
    // Try wildcard patterns
    for (const [pattern, handler] of this.routes.entries()) {
      if (pattern.includes('*')) {
        const regex = new RegExp('^' + pattern.replace(/\*/g, '.*') + '$');
        if (regex.test(event.type)) {
          try {
            await handler(event);
            return { routed: true, pattern };
          } catch (err) {
            return { routed: false, error: err.message };
          }
        }
      }
    }
    // Fallback
    if (this.fallback) {
      try {
        await this.fallback(event);
        return { routed: true, pattern: 'fallback' };
      } catch (err) {
        return { routed: false, error: err.message };
      }
    }
    return { routed: false, reason: 'no_route' };
  }
}

// ----- 7. EventRecorder: record events for replay -----
class EventRecorder {
  constructor(options = {}) {
    this.options = { maxEvents: options.maxEvents || 10000, ...options };
    this.recording = false;
    this.events = [];
    this.startTime = null;
  }

  start() {
    this.recording = true;
    this.startTime = globalNativeBridge.eventTimestamp();
    this.events = [];
  }

  stop() {
    this.recording = false;
  }

  record(event) {
    if (!this.recording) return false;
    this.events.push({
      ...event,
      recordedAt: globalNativeBridge.eventTimestamp(),
      offsetMs: globalNativeBridge.eventTimestamp() - this.startTime
    });
    if (this.events.length > this.options.maxEvents) {
      this.events.shift();
    }
    return true;
  }

  getEvents() {
    return this.events.slice();
  }

  clear() {
    this.events = [];
  }
}

// ----- 8. EventReplayer: replay recorded events -----
class EventReplayer {
  constructor(options = {}) {
    this.options = { speed: options.speed || 1.0, realTime: options.realTime !== false, ...options };
    this.replaying = false;
  }

  async replay(events, bus) {
    if (this.replaying) return { replayed: false, reason: 'already_replaying' };
    this.replaying = true;
    const target = bus || globalEventBus;
    let count = 0;
    try {
      for (const event of events) {
        if (!this.replaying) break;
        if (this.options.realTime && event.offsetMs !== undefined && count > 0) {
          const prev = events[count - 1];
          const gap = (event.offsetMs - (prev.offsetMs || 0)) / this.options.speed;
          if (gap > 0) await new Promise(r => setTimeout(r, gap));
        }
        target.publish({ ...event, replayed: true });
        count++;
      }
      return { replayed: true, count };
    } finally {
      this.replaying = false;
    }
  }

  stop() {
    this.replaying = false;
  }
}

// ----- 9. EventAggregator: aggregate events into summaries -----
class EventAggregator {
  constructor(options = {}) {
    this.options = { windowMs: options.windowMs || 60000, ...options };
    this.buckets = new Map(); // windowStart -> { count, byType, bySource }
  }

  add(event) {
    const windowStart = Math.floor(event.timestamp / this.options.windowMs) * this.options.windowMs;
    if (!this.buckets.has(windowStart)) {
      this.buckets.set(windowStart, {
        windowStart,
        windowEnd: windowStart + this.options.windowMs,
        count: 0,
        byType: {},
        bySource: {},
        byCategory: {}
      });
    }
    const bucket = this.buckets.get(windowStart);
    bucket.count++;
    bucket.byType[event.type] = (bucket.byType[event.type] || 0) + 1;
    bucket.bySource[event.source] = (bucket.bySource[event.source] || 0) + 1;
    const info = globalEventTypes.get(event.type);
    if (info) {
      bucket.byCategory[info.category] = (bucket.byCategory[info.category] || 0) + 1;
    }
    return bucket;
  }

  getSummary(windowStart) {
    return this.buckets.get(windowStart) || null;
  }

  getRecent(limit = 10) {
    return Array.from(this.buckets.values()).sort((a, b) => b.windowStart - a.windowStart).slice(0, limit);
  }

  getTotal() {
    let total = 0;
    for (const bucket of this.buckets.values()) total += bucket.count;
    return total;
  }

  clear() {
    this.buckets.clear();
  }
}

// ----- 10. EventTracer: trace event flow for debugging -----
class EventTracer {
  constructor(options = {}) {
    this.options = { maxTraces: options.maxTraces || 1000, ...options };
    this.traces = [];
    this.activeFlows = new Map(); // flowId -> [events]
  }

  startFlow(flowId, initialEvent) {
    this.activeFlows.set(flowId, [{
      ...initialEvent,
      flowId,
      flowStep: 0,
      tracedAt: globalNativeBridge.eventTimestamp()
    }]);
    return flowId;
  }

  trace(flowId, event) {
    if (!this.activeFlows.has(flowId)) {
      this.startFlow(flowId, event);
      return;
    }
    const flow = this.activeFlows.get(flowId);
    flow.push({
      ...event,
      flowId,
      flowStep: flow.length,
      tracedAt: globalNativeBridge.eventTimestamp()
    });
    this.traces.push(flow[flow.length - 1]);
    if (this.traces.length > this.options.maxTraces) {
      this.traces.shift();
    }
  }

  endFlow(flowId) {
    const flow = this.activeFlows.get(flowId);
    if (flow) {
      this.activeFlows.delete(flowId);
      return { flowId, steps: flow.length, duration: flow.length > 0 ? flow[flow.length - 1].tracedAt - flow[0].tracedAt : 0 };
    }
    return null;
  }

  getFlow(flowId) {
    return this.activeFlows.get(flowId) || null;
  }

  getRecentTraces(limit = 50) {
    return this.traces.slice(-limit);
  }

  getActiveFlows() {
    return Array.from(this.activeFlows.keys());
  }

  clear() {
    this.traces = [];
    this.activeFlows.clear();
  }
}

// ----- Global instances -----
const globalEventBus = new EventBus();
const globalEventTypes = new EventTypes();
const globalEventRecorder = new EventRecorder();
const globalEventReplayer = new EventReplayer();
const globalEventAggregator = new EventAggregator();
const globalEventTracer = new EventTracer();
const globalEventFilter = new EventFilter();
const globalEventRouter = new EventRouter();

// ----- Native hooks for Phase 10 -----
const _EventBus_nativeTimestamp = () => globalNativeBridge.eventTimestamp();
const _EventRecorder_nativeId = (prefix) => globalNativeBridge.generateEventId(prefix);
const _EventAggregator_nativePriority = (type, age) => globalNativeBridge.computeEventPriority(type, age);

// ============================================================================
// PHASE 11 — MEMORY SYSTEM: 10 utilities for learning over time
// ============================================================================
//
// Memory System provides:
//   - ShortTermMemory: in-flight task context
//   - LongTermMemory: persistent knowledge across sessions
//   - TaskHistory: record of past task executions
//   - WorkflowMemory: successful and failed workflow patterns
//   - UserPreferences: learned user behavior
//   - ApplicationProfile: per-app usage patterns
//   - ActionFrequency: frequently used actions
//   - ObservationCache: cached screen/perception results
//   - MemoryCleanup: TTL-based eviction
//   - MemoryIndex: fast lookup by key
//

// ----- 1. ShortTermMemory: in-flight task context -----
class ShortTermMemory {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 100, ttlMs: options.ttlMs || 600000, ...options };
    this.entries = new Map(); // key -> { value, createdAt, lastAccess, accessCount }
  }

  set(key, value, ttlMs) {
    const now = globalNativeBridge.eventTimestamp();
    const ttl = ttlMs !== undefined ? ttlMs : this.options.ttlMs;
    this.entries.set(key, {
      value,
      createdAt: now,
      lastAccess: now,
      accessCount: 0,
      expiresAt: now + ttl
    });
    if (this.entries.size > this.options.maxEntries) {
      // Evict oldest
      let oldestKey = null;
      let oldestTime = Infinity;
      for (const [k, v] of this.entries.entries()) {
        if (v.lastAccess < oldestTime) {
          oldestTime = v.lastAccess;
          oldestKey = k;
        }
      }
      if (oldestKey) this.entries.delete(oldestKey);
    }
    return true;
  }

  get(key) {
    const entry = this.entries.get(key);
    if (!entry) return null;
    const now = globalNativeBridge.eventTimestamp();
    if (entry.expiresAt && now > entry.expiresAt) {
      this.entries.delete(key);
      return null;
    }
    entry.lastAccess = now;
    entry.accessCount++;
    return entry.value;
  }

  has(key) {
    return this.entries.has(key);
  }

  delete(key) {
    return this.entries.delete(key);
  }

  clear() {
    this.entries.clear();
  }

  size() {
    return this.entries.size;
  }

  keys() {
    return Array.from(this.entries.keys());
  }
}

// ----- 2. LongTermMemory: persistent knowledge -----
class LongTermMemory {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 10000, ...options };
    this.entries = new Map(); // key -> { value, createdAt, importance, tags, accessCount }
    this.tagIndex = new Map(); // tag -> Set<key>
  }

  store(key, value, options = {}) {
    const now = globalNativeBridge.eventTimestamp();
    const importance = options.importance !== undefined ? options.importance : 50;
    const tags = options.tags || [];
    this.entries.set(key, {
      value,
      createdAt: now,
      importance,
      tags,
      accessCount: 0,
      lastAccess: now
    });
    for (const tag of tags) {
      if (!this.tagIndex.has(tag)) this.tagIndex.set(tag, new Set());
      this.tagIndex.get(tag).add(key);
    }
    if (this.entries.size > this.options.maxEntries) {
      this._evictLeastImportant();
    }
    return true;
  }

  recall(key) {
    const entry = this.entries.get(key);
    if (!entry) return null;
    entry.lastAccess = globalNativeBridge.eventTimestamp();
    entry.accessCount++;
    return entry.value;
  }

  search(query, options = {}) {
    const limit = options.limit || 10;
    const now = globalNativeBridge.eventTimestamp();
    const results = [];
    for (const [key, entry] of this.entries.entries()) {
      const age = now - entry.createdAt;
      const score = globalNativeBridge.computeMemoryRelevance(query, key, age);
      if (score > 0) {
        results.push({ key, value: entry.value, score, importance: entry.importance });
      }
    }
    results.sort((a, b) => b.score - a.score);
    return results.slice(0, limit);
  }

  byTag(tag) {
    const keys = this.tagIndex.get(tag);
    if (!keys) return [];
    const results = [];
    for (const key of keys) {
      const entry = this.entries.get(key);
      if (entry) results.push({ key, value: entry.value, importance: entry.importance });
    }
    return results;
  }

  forget(key) {
    const entry = this.entries.get(key);
    if (entry && entry.tags) {
      for (const tag of entry.tags) {
        const set = this.tagIndex.get(tag);
        if (set) {
          set.delete(key);
          if (set.size === 0) this.tagIndex.delete(tag);
        }
      }
    }
    return this.entries.delete(key);
  }

  _evictLeastImportant() {
    let victim = null;
    let minScore = Infinity;
    const now = globalNativeBridge.eventTimestamp();
    for (const [key, entry] of this.entries.entries()) {
      const age = now - entry.createdAt;
      const score = entry.importance - Math.floor(age / 86400000);
      if (score < minScore) {
        minScore = score;
        victim = key;
      }
    }
    if (victim) this.forget(victim);
  }

  size() {
    return this.entries.size;
  }

  clear() {
    this.entries.clear();
    this.tagIndex.clear();
  }
}

// ----- 3. TaskHistory: record of past task executions -----
class TaskHistory {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 1000, ...options };
    this.tasks = []; // [{ id, command, status, startedAt, completedAt, duration, result }]
  }

  record(task) {
    const now = globalNativeBridge.eventTimestamp();
    const entry = {
      id: task.id || globalNativeBridge.generateEventId('task'),
      command: task.command || '',
      intent: task.intent || '',
      status: task.status || 'pending',
      startedAt: task.startedAt || now,
      completedAt: task.completedAt || null,
      duration: task.duration || null,
      result: task.result || null,
      error: task.error || null
    };
    if (entry.completedAt && entry.startedAt) {
      entry.duration = entry.completedAt - entry.startedAt;
    }
    this.tasks.push(entry);
    if (this.tasks.length > this.options.maxEntries) {
      this.tasks.shift();
    }
    return entry;
  }

  complete(taskId, result, error) {
    const task = this.tasks.find(t => t.id === taskId);
    if (!task) return null;
    const now = globalNativeBridge.eventTimestamp();
    task.completedAt = now;
    task.duration = now - task.startedAt;
    task.status = error ? 'failed' : 'completed';
    task.result = result;
    task.error = error;
    return task;
  }

  get(taskId) {
    return this.tasks.find(t => t.id === taskId) || null;
  }

  recent(limit = 20) {
    return this.tasks.slice(-limit).reverse();
  }

  byStatus(status) {
    return this.tasks.filter(t => t.status === status);
  }

  successful() {
    return this.byStatus('completed');
  }

  failed() {
    return this.byStatus('failed');
  }

  successRate() {
    if (this.tasks.length === 0) return 0;
    const completed = this.successful().length;
    return completed / this.tasks.length;
  }

  averageDuration() {
    const completed = this.successful();
    if (completed.length === 0) return 0;
    const total = completed.reduce((sum, t) => sum + (t.duration || 0), 0);
    return total / completed.length;
  }

  clear() {
    this.tasks = [];
  }
}

// ----- 4. WorkflowMemory: successful and failed workflow patterns -----
class WorkflowMemory {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 500, ...options };
    this.workflows = new Map(); // id -> { steps, successCount, failCount, lastUsed }
  }

  recordWorkflow(id, steps, success) {
    const now = globalNativeBridge.eventTimestamp();
    if (!this.workflows.has(id)) {
      this.workflows.set(id, {
        id,
        steps,
        successCount: 0,
        failCount: 0,
        lastUsed: now,
        createdAt: now
      });
    }
    const wf = this.workflows.get(id);
    wf.lastUsed = now;
    if (success) wf.successCount++;
    else wf.failCount++;
    return wf;
  }

  get(id) {
    return this.workflows.get(id) || null;
  }

  successful() {
    const results = [];
    for (const wf of this.workflows.values()) {
      if (wf.successCount > wf.failCount) results.push(wf);
    }
    return results.sort((a, b) => b.successCount - a.successCount);
  }

  failed() {
    const results = [];
    for (const wf of this.workflows.values()) {
      if (wf.failCount > wf.successCount) results.push(wf);
    }
    return results.sort((a, b) => b.failCount - a.failCount);
  }

  successRate(id) {
    const wf = this.workflows.get(id);
    if (!wf) return 0;
    const total = wf.successCount + wf.failCount;
    return total > 0 ? wf.successCount / total : 0;
  }

  match(command) {
    const tokens = String(command || '').toLowerCase().split(/\s+/).filter(Boolean);
    const results = [];
    for (const wf of this.workflows.values()) {
      const stepText = wf.steps.join(' ').toLowerCase();
      let overlap = 0;
      for (const t of tokens) {
        if (stepText.includes(t)) overlap++;
      }
      const score = tokens.length > 0 ? overlap / tokens.length : 0;
      if (score > 0.3) {
        results.push({ workflow: wf, score });
      }
    }
    return results.sort((a, b) => b.score - a.score);
  }

  clear() {
    this.workflows.clear();
  }
}

// ----- 5. UserPreferences: learned user behavior -----
class UserPreferences {
  constructor(options = {}) {
    this.options = options;
    this.preferences = new Map(); // key -> { value, confidence, source }
  }

  set(key, value, confidence = 1.0, source = 'explicit') {
    this.preferences.set(key, {
      value,
      confidence: Math.max(0, Math.min(1, confidence)),
      source,
      updatedAt: globalNativeBridge.eventTimestamp()
    });
    return true;
  }

  get(key, defaultValue = null) {
    const pref = this.preferences.get(key);
    if (!pref) return defaultValue;
    return pref.value;
  }

  has(key) {
    return this.preferences.has(key);
  }

  learn(key, value, confidence = 0.5) {
    const existing = this.preferences.get(key);
    if (existing) {
      // Weighted average of confidence
      const totalConf = existing.confidence + confidence;
      existing.value = existing.confidence > confidence ? existing.value : value;
      existing.confidence = Math.min(1, totalConf / 2);
      existing.source = 'learned';
      existing.updatedAt = globalNativeBridge.eventTimestamp();
    } else {
      this.set(key, value, confidence, 'learned');
    }
    return true;
  }

  forget(key) {
    return this.preferences.delete(key);
  }

  all() {
    const result = {};
    for (const [key, pref] of this.preferences.entries()) {
      result[key] = { value: pref.value, confidence: pref.confidence, source: pref.source };
    }
    return result;
  }

  clear() {
    this.preferences.clear();
  }
}

// ----- 6. ApplicationProfile: per-app usage patterns -----
class ApplicationProfile {
  constructor(options = {}) {
    this.options = options;
    this.profiles = new Map(); // appName -> { launchCount, lastLaunch, commonActions, avgDuration }
  }

  recordLaunch(appName, durationMs) {
    const now = globalNativeBridge.eventTimestamp();
    if (!this.profiles.has(appName)) {
      this.profiles.set(appName, {
        appName,
        launchCount: 0,
        lastLaunch: now,
        totalDuration: 0,
        avgDuration: 0,
        commonActions: new Map()
      });
    }
    const profile = this.profiles.get(appName);
    profile.launchCount++;
    profile.lastLaunch = now;
    if (durationMs) {
      profile.totalDuration += durationMs;
      profile.avgDuration = profile.totalDuration / profile.launchCount;
    }
    return profile;
  }

  recordAction(appName, action) {
    const profile = this.profiles.get(appName);
    if (!profile) return null;
    const count = profile.commonActions.get(action) || 0;
    profile.commonActions.set(action, count + 1);
    return profile;
  }

  get(appName) {
    return this.profiles.get(appName) || null;
  }

  commonActions(appName, limit = 5) {
    const profile = this.profiles.get(appName);
    if (!profile) return [];
    return Array.from(profile.commonActions.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, limit)
      .map(([action, count]) => ({ action, count }));
  }

  recentlyUsed(limit = 10) {
    return Array.from(this.profiles.values())
      .sort((a, b) => b.lastLaunch - a.lastLaunch)
      .slice(0, limit);
  }

  clear() {
    this.profiles.clear();
  }
}

// ----- 7. ActionFrequency: frequently used actions -----
class ActionFrequency {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 1000, ...options };
    this.actions = new Map(); // actionKey -> { count, lastUsed, totalDuration }
  }

  record(actionKey, durationMs) {
    const now = globalNativeBridge.eventTimestamp();
    if (!this.actions.has(actionKey)) {
      this.actions.set(actionKey, {
        action: actionKey,
        count: 0,
        lastUsed: now,
        firstUsed: now,
        totalDuration: 0,
        avgDuration: 0
      });
    }
    const entry = this.actions.get(actionKey);
    entry.count++;
    entry.lastUsed = now;
    if (durationMs) {
      entry.totalDuration += durationMs;
      entry.avgDuration = entry.totalDuration / entry.count;
    }
    return entry;
  }

  top(limit = 10) {
    return Array.from(this.actions.values())
      .sort((a, b) => b.count - a.count)
      .slice(0, limit);
  }

  recent(limit = 10) {
    return Array.from(this.actions.values())
      .sort((a, b) => b.lastUsed - a.lastUsed)
      .slice(0, limit);
  }

  get(actionKey) {
    return this.actions.get(actionKey) || null;
  }

  frequency(actionKey) {
    const entry = this.actions.get(actionKey);
    return entry ? entry.count : 0;
  }

  clear() {
    this.actions.clear();
  }
}

// ----- 8. ObservationCache: cached screen/perception results -----
class ObservationCache {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 200, ttlMs: options.ttlMs || 30000, ...options };
    this.cache = new Map(); // key -> { value, createdAt, expiresAt, hitCount }
  }

  set(key, value, ttlMs) {
    const now = globalNativeBridge.eventTimestamp();
    const ttl = ttlMs !== undefined ? ttlMs : this.options.ttlMs;
    this.cache.set(key, {
      value,
      createdAt: now,
      expiresAt: now + ttl,
      hitCount: 0
    });
    if (this.cache.size > this.options.maxEntries) {
      // Evict oldest
      let oldestKey = null;
      let oldestTime = Infinity;
      for (const [k, v] of this.cache.entries()) {
        if (v.createdAt < oldestTime) {
          oldestTime = v.createdAt;
          oldestKey = k;
        }
      }
      if (oldestKey) this.cache.delete(oldestKey);
    }
    return true;
  }

  get(key) {
    const entry = this.cache.get(key);
    if (!entry) return null;
    const now = globalNativeBridge.eventTimestamp();
    if (now > entry.expiresAt) {
      this.cache.delete(key);
      return null;
    }
    entry.hitCount++;
    return entry.value;
  }

  has(key) {
    const entry = this.cache.get(key);
    if (!entry) return false;
    if (globalNativeBridge.eventTimestamp() > entry.expiresAt) {
      this.cache.delete(key);
      return false;
    }
    return true;
  }

  invalidate(key) {
    return this.cache.delete(key);
  }

  invalidateAll() {
    this.cache.clear();
  }

  stats() {
    let totalHits = 0;
    let validEntries = 0;
    const now = globalNativeBridge.eventTimestamp();
    for (const entry of this.cache.values()) {
      if (now <= entry.expiresAt) {
        validEntries++;
        totalHits += entry.hitCount;
      }
    }
    return { size: validEntries, totalHits, hitRate: validEntries > 0 ? totalHits / validEntries : 0 };
  }
}

// ----- 9. MemoryCleanup: TTL-based eviction -----
class MemoryCleanup {
  constructor(options = {}) {
    this.options = options;
    this.lastRun = null;
    this.totalEvicted = 0;
  }

  cleanupShortTerm(memory) {
    const now = globalNativeBridge.eventTimestamp();
    let evicted = 0;
    for (const [key, entry] of memory.entries.entries()) {
      if (entry.expiresAt && now > entry.expiresAt) {
        memory.entries.delete(key);
        evicted++;
      }
    }
    this.totalEvicted += evicted;
    return evicted;
  }

  cleanupObservations(cache) {
    const now = globalNativeBridge.eventTimestamp();
    let evicted = 0;
    for (const [key, entry] of cache.cache.entries()) {
      if (now > entry.expiresAt) {
        cache.cache.delete(key);
        evicted++;
      }
    }
    this.totalEvicted += evicted;
    return evicted;
  }

  cleanupLongTerm(memory, options = {}) {
    const maxAge = options.maxAge || 30 * 86400000; // 30 days
    const minImportance = options.minImportance || 10;
    const now = globalNativeBridge.eventTimestamp();
    let evicted = 0;
    for (const [key, entry] of memory.entries.entries()) {
      const age = now - entry.createdAt;
      const priority = globalNativeBridge.computeCleanupPriority(age, entry.accessCount, entry.importance);
      if (age > maxAge && entry.importance < minImportance && priority > 50) {
        memory.forget(key);
        evicted++;
      }
    }
    this.totalEvicted += evicted;
    return evicted;
  }

  cleanupAll(memories) {
    const results = {
      shortTerm: 0,
      observations: 0,
      longTerm: 0
    };
    if (memories.shortTerm) results.shortTerm = this.cleanupShortTerm(memories.shortTerm);
    if (memories.observations) results.observations = this.cleanupObservations(memories.observations);
    if (memories.longTerm) results.longTerm = this.cleanupLongTerm(memories.longTerm);
    this.lastRun = globalNativeBridge.eventTimestamp();
    return results;
  }

  getStats() {
    return {
      lastRun: this.lastRun,
      totalEvicted: this.totalEvicted
    };
  }
}

// ----- 10. MemoryIndex: fast lookup by key -----
class MemoryIndex {
  constructor(options = {}) {
    this.options = options;
    this.index = new Map(); // hash -> Set<key>
    this.reverseIndex = new Map(); // key -> hash
  }

  add(key) {
    const hash = globalNativeBridge.hashMemoryKey(key);
    if (!this.index.has(hash)) this.index.set(hash, new Set());
    this.index.get(hash).add(key);
    this.reverseIndex.set(key, hash);
    return hash;
  }

  remove(key) {
    const hash = this.reverseIndex.get(key);
    if (!hash) return false;
    const set = this.index.get(hash);
    if (set) {
      set.delete(key);
      if (set.size === 0) this.index.delete(hash);
    }
    this.reverseIndex.delete(key);
    return true;
  }

  lookup(key) {
    const hash = globalNativeBridge.hashMemoryKey(key);
    const set = this.index.get(hash);
    return set ? Array.from(set) : [];
  }

  has(key) {
    return this.reverseIndex.has(key);
  }

  size() {
    return this.reverseIndex.size;
  }

  clear() {
    this.index.clear();
    this.reverseIndex.clear();
  }
}

// ----- Global instances -----
const globalShortTermMemory = new ShortTermMemory();
const globalLongTermMemory = new LongTermMemory();
const globalTaskHistory = new TaskHistory();
const globalWorkflowMemory = new WorkflowMemory();
const globalUserPreferences = new UserPreferences();
const globalApplicationProfile = new ApplicationProfile();
const globalActionFrequency = new ActionFrequency();
const globalObservationCache = new ObservationCache();
const globalMemoryCleanup = new MemoryCleanup();
const globalMemoryIndex = new MemoryIndex();

// ----- Native hooks for Phase 11 -----
const _LongTermMemory_nativeRelevance = (query, key, age) => globalNativeBridge.computeMemoryRelevance(query, key, age);
const _MemoryIndex_nativeHash = (key) => globalNativeBridge.hashMemoryKey(key);
const _MemoryCleanup_nativePriority = (age, access, importance) => globalNativeBridge.computeCleanupPriority(age, access, importance);

// ============================================================================
// PHASE 13 — SKILL ORCHESTRATOR: 10 utilities for intelligent skill composition
// ============================================================================
//
// Skill Orchestrator provides:
//   - SkillDiscovery: find skills by query, tags, or capability
//   - SkillRanking: rank skills by match score, health, and cost
//   - SkillFallback: chain of fallback skills when primary fails
//   - SkillChaining: compose multiple skills into a pipeline
//   - SkillDependencyResolver: topological sort of skill dependencies
//   - SkillCache: cache skill results for reuse
//   - SkillHealthMonitor: track success/failure rates per skill
//   - ProviderSelector: choose best provider for a skill
//   - SkillRetryPolicy: retry strategies per skill
//   - SkillMetrics: aggregate metrics across all skills
//

// ----- 1. SkillDiscovery: find skills by query/tags/capability -----
class SkillDiscovery {
  constructor(options = {}) {
    this.options = options;
    this.registry = new Map(); // skillId -> { name, tags, capabilities, provider, version }
  }

  register(skill) {
    if (!skill || !skill.id) return false;
    this.registry.set(skill.id, {
      id: skill.id,
      name: skill.name || skill.id,
      tags: skill.tags || [],
      capabilities: skill.capabilities || [],
      provider: skill.provider || 'default',
      version: skill.version || '1.0.0',
      registeredAt: globalNativeBridge.eventTimestamp()
    });
    return true;
  }

  unregister(skillId) {
    return this.registry.delete(skillId);
  }

  find(query, options = {}) {
    const limit = options.limit || 10;
    const results = [];
    for (const skill of this.registry.values()) {
      const score = globalNativeBridge.computeSkillMatch(query, skill.name, skill.tags.join(','));
      if (score > 0) {
        results.push({ skill, score });
      }
    }
    results.sort((a, b) => b.score - a.score);
    return results.slice(0, limit);
  }

  byTag(tag) {
    const results = [];
    for (const skill of this.registry.values()) {
      if (skill.tags.includes(tag)) results.push(skill);
    }
    return results;
  }

  byCapability(capability) {
    const results = [];
    for (const skill of this.registry.values()) {
      if (skill.capabilities.includes(capability)) results.push(skill);
    }
    return results;
  }

  byProvider(provider) {
    const results = [];
    for (const skill of this.registry.values()) {
      if (skill.provider === provider) results.push(skill);
    }
    return results;
  }

  get(skillId) {
    return this.registry.get(skillId) || null;
  }

  list() {
    return Array.from(this.registry.values());
  }

  size() {
    return this.registry.size;
  }

  clear() {
    this.registry.clear();
  }
}

// ----- 2. SkillRanking: rank skills by match/health/cost -----
class SkillRanking {
  constructor(options = {}) {
    this.options = { weights: options.weights || { match: 0.5, health: 0.3, cost: 0.2 }, ...options };
  }

  rank(skills, query) {
    const results = [];
    for (const skill of skills) {
      const matchScore = globalNativeBridge.computeSkillMatch(query, skill.name, (skill.tags || []).join(','));
      const healthScore = skill.health !== undefined ? skill.health : 50;
      const costScore = skill.cost !== undefined ? Math.max(0, 100 - skill.cost) : 50;
      const total = Math.round(
        matchScore * this.options.weights.match +
        healthScore * this.options.weights.health +
        costScore * this.options.weights.cost
      );
      results.push({ skill, score: total, breakdown: { match: matchScore, health: healthScore, cost: costScore } });
    }
    results.sort((a, b) => b.score - a.score);
    return results;
  }

  top(skills, query, limit = 1) {
    return this.rank(skills, query).slice(0, limit);
  }
}

// ----- 3. SkillFallback: chain of fallback skills -----
class SkillFallback {
  constructor(options = {}) {
    this.options = options;
    this.chains = new Map(); // primaryId -> [fallbackIds]
  }

  define(primaryId, fallbackIds) {
    this.chains.set(primaryId, Array.isArray(fallbackIds) ? fallbackIds : [fallbackIds]);
    return true;
  }

  get(primaryId) {
    return this.chains.get(primaryId) || [];
  }

  async execute(primaryId, executor) {
    const chain = [primaryId, ...this.get(primaryId)];
    const errors = [];
    for (const skillId of chain) {
      try {
        const result = await executor(skillId);
        return { skillId, result, fallbackUsed: skillId !== primaryId, errors };
      } catch (err) {
        errors.push({ skillId, error: err.message || String(err) });
      }
    }
    return { skillId: null, result: null, fallbackUsed: true, errors };
  }

  clear() {
    this.chains.clear();
  }
}

// ----- 4. SkillChaining: compose skills into a pipeline -----
class SkillChaining {
  constructor(options = {}) {
    this.options = options;
    this.chains = new Map(); // chainId -> [skillIds]
  }

  define(chainId, skillIds) {
    this.chains.set(chainId, Array.isArray(skillIds) ? skillIds : [skillIds]);
    return true;
  }

  get(chainId) {
    return this.chains.get(chainId) || [];
  }

  async execute(chainId, executor, options = {}) {
    const chain = this.get(chainId);
    const results = [];
    const stopOnError = options.stopOnError !== false;
    for (const skillId of chain) {
      try {
        const result = await executor(skillId);
        results.push({ skillId, status: 'success', result });
      } catch (err) {
        results.push({ skillId, status: 'failed', error: err.message || String(err) });
        if (stopOnError) break;
      }
    }
    return { chainId, results, completed: results.every(r => r.status === 'success') };
  }

  list() {
    return Array.from(this.chains.keys());
  }

  clear() {
    this.chains.clear();
  }
}

// ----- 5. SkillDependencyResolver: topological sort -----
class SkillDependencyResolver {
  constructor(options = {}) {
    this.options = options;
    this.dependencies = new Map(); // skillId -> [dependencyIds]
  }

  add(skillId, dependencies) {
    this.dependencies.set(skillId, Array.isArray(dependencies) ? dependencies : [dependencies]);
    return true;
  }

  remove(skillId) {
    return this.dependencies.delete(skillId);
  }

  resolve(skillIds) {
    const ids = Array.isArray(skillIds) ? skillIds : [skillIds];
    const visited = new Set();
    const visiting = new Set();
    const order = [];

    const visit = (id) => {
      if (visited.has(id)) return;
      if (visiting.has(id)) {
        // Cycle detected, skip
        return;
      }
      visiting.add(id);
      const deps = this.dependencies.get(id) || [];
      for (const dep of deps) {
        if (ids.includes(dep)) visit(dep);
      }
      visiting.delete(id);
      visited.add(id);
      order.push(id);
    };

    for (const id of ids) visit(id);
    return order;
  }

  detectCycles() {
    const cycles = [];
    const visited = new Set();
    const stack = new Set();

    const dfs = (id, path) => {
      if (stack.has(id)) {
        const cycleStart = path.indexOf(id);
        cycles.push(path.slice(cycleStart).concat(id));
        return;
      }
      if (visited.has(id)) return;
      visited.add(id);
      stack.add(id);
      const deps = this.dependencies.get(id) || [];
      for (const dep of deps) {
        dfs(dep, path.concat(id));
      }
      stack.delete(id);
    };

    for (const id of this.dependencies.keys()) {
      dfs(id, []);
    }
    return cycles;
  }

  clear() {
    this.dependencies.clear();
  }
}

// ----- 6. SkillCache: cache skill results -----
class SkillCache {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 500, ttlMs: options.ttlMs || 300000, ...options };
    this.cache = new Map(); // key -> { value, createdAt, expiresAt, hitCount }
  }

  set(key, value, ttlMs) {
    const now = globalNativeBridge.eventTimestamp();
    const ttl = ttlMs !== undefined ? ttlMs : this.options.ttlMs;
    this.cache.set(key, {
      value,
      createdAt: now,
      expiresAt: now + ttl,
      hitCount: 0
    });
    if (this.cache.size > this.options.maxEntries) {
      let oldestKey = null;
      let oldestTime = Infinity;
      for (const [k, v] of this.cache.entries()) {
        if (v.createdAt < oldestTime) {
          oldestTime = v.createdAt;
          oldestKey = k;
        }
      }
      if (oldestKey) this.cache.delete(oldestKey);
    }
    return true;
  }

  get(key) {
    const entry = this.cache.get(key);
    if (!entry) return null;
    const now = globalNativeBridge.eventTimestamp();
    if (now > entry.expiresAt) {
      this.cache.delete(key);
      return null;
    }
    entry.hitCount++;
    return entry.value;
  }

  has(key) {
    const entry = this.cache.get(key);
    if (!entry) return false;
    if (globalNativeBridge.eventTimestamp() > entry.expiresAt) {
      this.cache.delete(key);
      return false;
    }
    return true;
  }

  invalidate(key) {
    return this.cache.delete(key);
  }

  invalidateByPrefix(prefix) {
    let count = 0;
    for (const key of this.cache.keys()) {
      if (key.startsWith(prefix)) {
        this.cache.delete(key);
        count++;
      }
    }
    return count;
  }

  stats() {
    let totalHits = 0;
    let validEntries = 0;
    const now = globalNativeBridge.eventTimestamp();
    for (const entry of this.cache.values()) {
      if (now <= entry.expiresAt) {
        validEntries++;
        totalHits += entry.hitCount;
      }
    }
    return { size: validEntries, totalHits, hitRate: validEntries > 0 ? totalHits / validEntries : 0 };
  }

  clear() {
    this.cache.clear();
  }
}

// ----- 7. SkillHealthMonitor: track success/failure rates -----
class SkillHealthMonitor {
  constructor(options = {}) {
    this.options = options;
    this.metrics = new Map(); // skillId -> { successCount, failCount, totalDuration, lastUsed, lastError }
  }

  recordSuccess(skillId, durationMs) {
    if (!this.metrics.has(skillId)) {
      this.metrics.set(skillId, {
        skillId,
        successCount: 0,
        failCount: 0,
        totalDuration: 0,
        avgDuration: 0,
        lastUsed: null,
        lastError: null
      });
    }
    const m = this.metrics.get(skillId);
    m.successCount++;
    m.totalDuration += durationMs || 0;
    m.avgDuration = m.totalDuration / (m.successCount + m.failCount);
    m.lastUsed = globalNativeBridge.eventTimestamp();
    return m;
  }

  recordFailure(skillId, error, durationMs) {
    if (!this.metrics.has(skillId)) {
      this.metrics.set(skillId, {
        skillId,
        successCount: 0,
        failCount: 0,
        totalDuration: 0,
        avgDuration: 0,
        lastUsed: null,
        lastError: null
      });
    }
    const m = this.metrics.get(skillId);
    m.failCount++;
    m.totalDuration += durationMs || 0;
    m.avgDuration = m.totalDuration / (m.successCount + m.failCount);
    m.lastUsed = globalNativeBridge.eventTimestamp();
    m.lastError = error ? String(error) : null;
    return m;
  }

  get(skillId) {
    return this.metrics.get(skillId) || null;
  }

  health(skillId) {
    const m = this.metrics.get(skillId);
    if (!m) return 50; // unknown
    return globalNativeBridge.computeSkillHealth(m.successCount, m.failCount, m.avgDuration);
  }

  healthy(threshold = 60) {
    const results = [];
    for (const [skillId, m] of this.metrics.entries()) {
      const score = this.health(skillId);
      if (score >= threshold) results.push({ skillId, health: score, metrics: m });
    }
    return results.sort((a, b) => b.health - a.health);
  }

  unhealthy(threshold = 40) {
    const results = [];
    for (const [skillId, m] of this.metrics.entries()) {
      const score = this.health(skillId);
      if (score < threshold) results.push({ skillId, health: score, metrics: m });
    }
    return results.sort((a, b) => a.health - b.health);
  }

  all() {
    return Array.from(this.metrics.values());
  }

  clear() {
    this.metrics.clear();
  }
}

// ----- 8. ProviderSelector: choose best provider for a skill -----
class ProviderSelector {
  constructor(options = {}) {
    this.options = options;
    this.providers = new Map(); // providerId -> { name, capabilities, health, cost, latency }
  }

  register(provider) {
    if (!provider || !provider.id) return false;
    this.providers.set(provider.id, {
      id: provider.id,
      name: provider.name || provider.id,
      capabilities: provider.capabilities || [],
      health: provider.health !== undefined ? provider.health : 80,
      cost: provider.cost !== undefined ? provider.cost : 50,
      latency: provider.latency !== undefined ? provider.latency : 100,
      registeredAt: globalNativeBridge.eventTimestamp()
    });
    return true;
  }

  unregister(providerId) {
    return this.providers.delete(providerId);
  }

  select(capability, options = {}) {
    const candidates = [];
    for (const provider of this.providers.values()) {
      if (provider.capabilities.includes(capability)) {
        const score = Math.round(
          provider.health * 0.5 +
          (100 - provider.cost) * 0.3 +
          (100 - Math.min(100, provider.latency / 10)) * 0.2
        );
        candidates.push({ provider, score });
      }
    }
    candidates.sort((a, b) => b.score - a.score);
    if (options.limit) return candidates.slice(0, options.limit);
    return candidates.length > 0 ? candidates[0] : null;
  }

  get(providerId) {
    return this.providers.get(providerId) || null;
  }

  list() {
    return Array.from(this.providers.values());
  }

  clear() {
    this.providers.clear();
  }
}

// ----- 9. SkillRetryPolicy: retry strategies per skill -----
class SkillRetryPolicy {
  constructor(options = {}) {
    this.options = options;
    this.policies = new Map(); // skillId -> { maxAttempts, backoff, retryableErrors }
  }

  define(skillId, policy) {
    this.policies.set(skillId, {
      maxAttempts: policy.maxAttempts || 3,
      backoff: policy.backoff || 'exponential',
      baseDelayMs: policy.baseDelayMs || 1000,
      maxDelayMs: policy.maxDelayMs || 30000,
      retryableErrors: policy.retryableErrors || ['timeout', 'network', 'rate_limit']
    });
    return true;
  }

  get(skillId) {
    return this.policies.get(skillId) || {
      maxAttempts: 3,
      backoff: 'exponential',
      baseDelayMs: 1000,
      maxDelayMs: 30000,
      retryableErrors: ['timeout', 'network', 'rate_limit']
    };
  }

  shouldRetry(skillId, attempt, error) {
    const policy = this.get(skillId);
    if (attempt >= policy.maxAttempts) return false;
    const errorStr = String(error || '').toLowerCase();
    return policy.retryableErrors.some(e => errorStr.includes(e));
  }

  getDelay(skillId, attempt) {
    const policy = this.get(skillId);
    let delay;
    if (policy.backoff === 'exponential') {
      delay = policy.baseDelayMs * Math.pow(2, attempt);
    } else if (policy.backoff === 'linear') {
      delay = policy.baseDelayMs * (attempt + 1);
    } else {
      delay = policy.baseDelayMs;
    }
    return Math.min(delay, policy.maxDelayMs);
  }

  async execute(skillId, executor) {
    const policy = this.get(skillId);
    let lastError = null;
    for (let attempt = 0; attempt < policy.maxAttempts; attempt++) {
      try {
        const result = await executor(attempt);
        return { success: true, result, attempts: attempt + 1 };
      } catch (err) {
        lastError = err;
        if (!this.shouldRetry(skillId, attempt, err)) break;
        if (attempt < policy.maxAttempts - 1) {
          const delay = this.getDelay(skillId, attempt);
          await new Promise(r => setTimeout(r, delay));
        }
      }
    }
    return { success: false, error: lastError, attempts: policy.maxAttempts };
  }

  clear() {
    this.policies.clear();
  }
}

// ----- 10. SkillMetrics: aggregate metrics across all skills -----
class SkillMetrics {
  constructor(options = {}) {
    this.options = options;
    this.metrics = new Map(); // skillId -> { calls, successes, failures, totalDuration, lastCalled }
  }

  record(skillId, success, durationMs) {
    if (!this.metrics.has(skillId)) {
      this.metrics.set(skillId, {
        skillId,
        calls: 0,
        successes: 0,
        failures: 0,
        totalDuration: 0,
        avgDuration: 0,
        lastCalled: null
      });
    }
    const m = this.metrics.get(skillId);
    m.calls++;
    if (success) m.successes++;
    else m.failures++;
    m.totalDuration += durationMs || 0;
    m.avgDuration = m.totalDuration / m.calls;
    m.lastCalled = globalNativeBridge.eventTimestamp();
    return m;
  }

  get(skillId) {
    return this.metrics.get(skillId) || null;
  }

  top(limit = 10) {
    return Array.from(this.metrics.values())
      .sort((a, b) => b.calls - a.calls)
      .slice(0, limit);
  }

  successRate(skillId) {
    const m = this.metrics.get(skillId);
    if (!m || m.calls === 0) return 0;
    return m.successes / m.calls;
  }

  averageDuration(skillId) {
    const m = this.metrics.get(skillId);
    return m ? m.avgDuration : 0;
  }

  all() {
    return Array.from(this.metrics.values());
  }

  summary() {
    let totalCalls = 0;
    let totalSuccesses = 0;
    let totalFailures = 0;
    let totalDuration = 0;
    for (const m of this.metrics.values()) {
      totalCalls += m.calls;
      totalSuccesses += m.successes;
      totalFailures += m.failures;
      totalDuration += m.totalDuration;
    }
    return {
      totalSkills: this.metrics.size,
      totalCalls,
      totalSuccesses,
      totalFailures,
      successRate: totalCalls > 0 ? totalSuccesses / totalCalls : 0,
      avgDuration: totalCalls > 0 ? totalDuration / totalCalls : 0
    };
  }

  clear() {
    this.metrics.clear();
  }
}

