const _SkillDiscovery_nativeMatch = (query, name, tags) => globalNativeBridge.computeSkillMatch(query, name, tags);
const _SkillHealthMonitor_nativeHealth = (s, f, d) => globalNativeBridge.computeSkillHealth(s, f, d);
const _SkillChaining_nativeCost = (skills) => globalNativeBridge.computeSkillChainCost(skills);
