// ============================================================================
// PHASE 14 — STATE MANAGER: 10 utilities for single source of truth
// ============================================================================
//
// State Manager provides a unified state store across:
//   - DesktopState: desktop environment state
//   - BrowserState: browser session state
//   - WindowState: window/UI state
//   - FileState: filesystem state
//   - TaskState: task execution state
//   - ExecutionState: pipeline execution state
//   - PipelineState: pipeline registry state
//   - AgentState: agent brain state
//   - ResourceState: system resource state
//   - VariableStore: shared variable store
//
// All states are tracked with:
//   - Hash-based change detection
//   - Freshness scoring
//   - Eviction priority
//   - Subscriber notifications
//

// ----- 1. DesktopState: desktop environment state -----
class DesktopState {
  constructor(options = {}) {
    this.options = options;
    this.state = {
      wallpaper: null,
      theme: 'unknown',
      resolution: { width: 0, height: 0 },
      scale: 1.0,
      monitors: [],
      lastUpdated: null
    };
    this.subscribers = [];
    this.history = [];
  }

  update(partial) {
    const prev = JSON.stringify(this.state);
    this.state = { ...this.state, ...partial, lastUpdated: globalNativeBridge.eventTimestamp() };
    const next = JSON.stringify(this.state);
    const hash = globalNativeBridge.computeStateHash(next);
    this.history.push({ hash, timestamp: this.state.lastUpdated, change: prev !== next });
    if (this.history.length > 50) this.history.shift();
    this._notify({ type: 'desktop', state: this.state, hash });
    return hash;
  }

  get() {
    return { ...this.state };
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(this.state));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 2. BrowserState: browser session state -----
class BrowserState {
  constructor(options = {}) {
    this.options = options;
    this.state = {
      activeBrowser: null,
      tabs: [],
      activeTab: null,
      url: null,
      title: null,
      lastUpdated: null
    };
    this.subscribers = [];
  }

  update(partial) {
    this.state = { ...this.state, ...partial, lastUpdated: globalNativeBridge.eventTimestamp() };
    const hash = globalNativeBridge.computeStateHash(JSON.stringify(this.state));
    this._notify({ type: 'browser', state: this.state, hash });
    return hash;
  }

  addTab(tab) {
    this.state.tabs.push(tab);
    return this.update({ tabs: this.state.tabs });
  }

  closeTab(tabId) {
    this.state.tabs = this.state.tabs.filter(t => t.id !== tabId);
    return this.update({ tabs: this.state.tabs });
  }

  setActive(tabId) {
    const tab = this.state.tabs.find(t => t.id === tabId);
    if (tab) {
      this.state.activeTab = tabId;
      this.state.url = tab.url;
      this.state.title = tab.title;
      return this.update({ activeTab: tabId, url: tab.url, title: tab.title });
    }
    return null;
  }

  get() {
    return { ...this.state };
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(this.state));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 3. WindowState: window/UI state -----
class WindowState {
  constructor(options = {}) {
    this.options = options;
    this.state = {
      focusedWindow: null,
      openWindows: [],
      minimized: [],
      lastUpdated: null
    };
    this.subscribers = [];
  }

  update(partial) {
    this.state = { ...this.state, ...partial, lastUpdated: globalNativeBridge.eventTimestamp() };
    const hash = globalNativeBridge.computeStateHash(JSON.stringify(this.state));
    this._notify({ type: 'window', state: this.state, hash });
    return hash;
  }

  open(window) {
    this.state.openWindows.push(window);
    return this.update({ openWindows: this.state.openWindows });
  }

  close(windowId) {
    this.state.openWindows = this.state.openWindows.filter(w => w.id !== windowId);
    this.state.minimized = this.state.minimized.filter(id => id !== windowId);
    if (this.state.focusedWindow === windowId) this.state.focusedWindow = null;
    return this.update({
      openWindows: this.state.openWindows,
      minimized: this.state.minimized,
      focusedWindow: this.state.focusedWindow
    });
  }

  focus(windowId) {
    this.state.focusedWindow = windowId;
    return this.update({ focusedWindow: windowId });
  }

  minimize(windowId) {
    if (!this.state.minimized.includes(windowId)) this.state.minimized.push(windowId);
    return this.update({ minimized: this.state.minimized });
  }

  restore(windowId) {
    this.state.minimized = this.state.minimized.filter(id => id !== windowId);
    return this.update({ minimized: this.state.minimized });
  }

  get() {
    return { ...this.state };
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(this.state));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 4. FileState: filesystem state -----
class FileState {
  constructor(options = {}) {
    this.options = options;
    this.state = {
      watchedPaths: new Map(), // path -> { hash, mtime, size }
      recentFiles: [],
      lastUpdated: null
    };
    this.subscribers = [];
  }

  watch(path, info) {
    this.state.watchedPaths.set(path, {
      hash: info.hash || globalNativeBridge.computeStateHash(path),
      mtime: info.mtime || globalNativeBridge.eventTimestamp(),
      size: info.size || 0
    });
    return this.update({ watchedPaths: this.state.watchedPaths });
  }

  unwatch(path) {
    this.state.watchedPaths.delete(path);
    return this.update({ watchedPaths: this.state.watchedPaths });
  }

  recordAccess(path) {
    if (!this.state.recentFiles.includes(path)) {
      this.state.recentFiles.unshift(path);
      if (this.state.recentFiles.length > 20) this.state.recentFiles.pop();
    }
    return this.update({ recentFiles: this.state.recentFiles });
  }

  detectChange(path, newHash) {
    const watched = this.state.watchedPaths.get(path);
    if (!watched) return null;
    if (watched.hash !== newHash) {
      const oldHash = watched.hash;
      watched.hash = newHash;
      watched.mtime = globalNativeBridge.eventTimestamp();
      this._notify({ type: 'file', path, oldHash, newHash });
      return { path, oldHash, newHash };
    }
    return null;
  }

  update(partial) {
    this.state = { ...this.state, ...partial, lastUpdated: globalNativeBridge.eventTimestamp() };
    const hash = globalNativeBridge.computeStateHash(JSON.stringify({
      ...this.state,
      watchedPaths: Array.from(this.state.watchedPaths.entries())
    }));
    return hash;
  }

  get() {
    return {
      watchedPaths: Array.from(this.state.watchedPaths.entries()),
      recentFiles: [...this.state.recentFiles],
      lastUpdated: this.state.lastUpdated
    };
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(this.get()));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 5. TaskState: task execution state -----
class TaskState {
  constructor(options = {}) {
    this.options = options;
    this.tasks = new Map(); // taskId -> { status, progress, startedAt, completedAt, result }
    this.subscribers = [];
  }

  create(taskId, info = {}) {
    this.tasks.set(taskId, {
      taskId,
      status: 'pending',
      progress: 0,
      startedAt: globalNativeBridge.eventTimestamp(),
      completedAt: null,
      result: null,
      error: null,
      ...info
    });
    this._notify({ type: 'task_created', taskId, state: this.tasks.get(taskId) });
    return this.tasks.get(taskId);
  }

  update(taskId, partial) {
    const task = this.tasks.get(taskId);
    if (!task) return null;
    Object.assign(task, partial);
    this._notify({ type: 'task_updated', taskId, state: task });
    return task;
  }

  start(taskId) {
    return this.update(taskId, { status: 'running', startedAt: globalNativeBridge.eventTimestamp() });
  }

  progress(taskId, percent) {
    return this.update(taskId, { progress: Math.max(0, Math.min(100, percent)) });
  }

  complete(taskId, result) {
    return this.update(taskId, {
      status: 'completed',
      progress: 100,
      completedAt: globalNativeBridge.eventTimestamp(),
      result
    });
  }

  fail(taskId, error) {
    return this.update(taskId, {
      status: 'failed',
      completedAt: globalNativeBridge.eventTimestamp(),
      error: error ? String(error) : null
    });
  }

  cancel(taskId) {
    return this.update(taskId, {
      status: 'cancelled',
      completedAt: globalNativeBridge.eventTimestamp()
    });
  }

  get(taskId) {
    return this.tasks.get(taskId) || null;
  }

  list(filter = {}) {
    let results = Array.from(this.tasks.values());
    if (filter.status) results = results.filter(t => t.status === filter.status);
    return results;
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(Array.from(this.tasks.entries())));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 6. ExecutionState: pipeline execution state -----
class ExecutionState {
  constructor(options = {}) {
    this.options = options;
    this.executions = new Map(); // executionId -> { pipelineId, status, nodes, startedAt }
    this.subscribers = [];
  }

  start(executionId, pipelineId) {
    this.executions.set(executionId, {
      executionId,
      pipelineId,
      status: 'running',
      nodes: new Map(),
      startedAt: globalNativeBridge.eventTimestamp(),
      completedAt: null
    });
    this._notify({ type: 'execution_started', executionId, pipelineId });
    return this.executions.get(executionId);
  }

  updateNode(executionId, nodeId, status, result) {
    const exec = this.executions.get(executionId);
    if (!exec) return null;
    exec.nodes.set(nodeId, { nodeId, status, result, timestamp: globalNativeBridge.eventTimestamp() });
    this._notify({ type: 'node_updated', executionId, nodeId, status });
    return exec.nodes.get(nodeId);
  }

  complete(executionId, result) {
    const exec = this.executions.get(executionId);
    if (!exec) return null;
    exec.status = 'completed';
    exec.completedAt = globalNativeBridge.eventTimestamp();
    exec.result = result;
    this._notify({ type: 'execution_completed', executionId, result });
    return exec;
  }

  fail(executionId, error) {
    const exec = this.executions.get(executionId);
    if (!exec) return null;
    exec.status = 'failed';
    exec.completedAt = globalNativeBridge.eventTimestamp();
    exec.error = error ? String(error) : null;
    this._notify({ type: 'execution_failed', executionId, error: exec.error });
    return exec;
  }

  get(executionId) {
    const exec = this.executions.get(executionId);
    if (!exec) return null;
    return {
      ...exec,
      nodes: Array.from(exec.nodes.entries())
    };
  }

  list() {
    return Array.from(this.executions.values()).map(e => ({
      ...e,
      nodes: Array.from(e.nodes.entries())
    }));
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(this.list()));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

