// ----- 10. StateVariableStore: shared variable store -----
class StateVariableStore {
  constructor(options = {}) {
    this.options = { maxEntries: options.maxEntries || 1000, ...options };
    this.variables = new Map(); // key -> { value, type, scope, createdAt, accessCount, sizeBytes }
    this.subscribers = [];
  }

  set(key, value, options = {}) {
    const now = globalNativeBridge.eventTimestamp();
    const sizeBytes = JSON.stringify(value).length;
    this.variables.set(key, {
      value,
      type: options.type || typeof value,
      scope: options.scope || 'global',
      createdAt: now,
      updatedAt: now,
      accessCount: 0,
      sizeBytes
    });
    if (this.variables.size > this.options.maxEntries) {
      // Evict by lowest freshness
      let evictKey = null;
      let lowestPriority = -1;
      for (const [k, v] of this.variables.entries()) {
        const priority = globalNativeBridge.computeStateEvictionPriority(
          now - v.updatedAt, v.accessCount, v.sizeBytes
        );
        if (priority > lowestPriority) {
          lowestPriority = priority;
          evictKey = k;
        }
      }
      if (evictKey) this.variables.delete(evictKey);
    }
    this._notify({ type: 'variable_set', key, value });
    return true;
  }

  get(key) {
    const entry = this.variables.get(key);
    if (!entry) return null;
    entry.accessCount++;
    return entry.value;
  }

  has(key) {
    return this.variables.has(key);
  }

  delete(key) {
    const removed = this.variables.delete(key);
    if (removed) this._notify({ type: 'variable_deleted', key });
    return removed;
  }

  keys() {
    return Array.from(this.variables.keys());
  }

  byScope(scope) {
    const results = [];
    for (const [k, v] of this.variables.entries()) {
      if (v.scope === scope) results.push({ key: k, ...v });
    }
    return results;
  }

  freshness(key, maxAgeMs = 60000) {
    const entry = this.variables.get(key);
    if (!entry) return 0;
    const age = globalNativeBridge.eventTimestamp() - entry.updatedAt;
    return globalNativeBridge.computeStateFreshness(age, maxAgeMs);
  }

  hash() {
    return globalNativeBridge.computeStateHash(JSON.stringify(Array.from(this.variables.entries())));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- Global instances -----
const globalDesktopState = new DesktopState();
const globalBrowserState = new BrowserState();
const globalWindowState = new WindowState();
const globalFileState = new FileState();
const globalTaskState = new TaskState();
const globalExecutionState = new ExecutionState();
const globalPipelineState = new PipelineState();
const globalAgentState = new AgentState();
const globalResourceState = new ResourceState();
const globalStateVariableStore = new StateVariableStore();

// ============================================================================
// PHASE 15 — WORKFLOW ENGINE: 10 utilities for complex automations
// ============================================================================
//
// Workflow Engine handles:
//   - Workflow builder (compose nodes into a workflow)
//   - Branching (conditional execution paths)
//   - Loops (iterate over collections or until condition)
//   - Conditions (evaluate predicates)
//   - Parallel branches (fan-out concurrent execution)
//   - Scheduled workflows (cron-like scheduling)
//   - Trigger-based workflows (event-driven execution)
//   - Workflow templates (reusable workflow definitions)
//   - Nested workflows (workflows within workflows)
//   - Workflow persistence (save/load to disk)

// ----- 1. WorkflowBuilder: compose nodes into a workflow -----
class WorkflowBuilder {
  constructor(options = {}) {
    this.options = options;
    this.workflows = new Map(); // workflowId -> { nodes, edges, metadata }
    this.subscribers = [];
  }

  create(workflowId, metadata = {}) {
    this.workflows.set(workflowId, {
      workflowId,
      nodes: new Map(),
      edges: [],
      metadata: { createdAt: globalNativeBridge.eventTimestamp(), ...metadata },
      status: 'draft'
    });
    this._notify({ type: 'workflow_created', workflowId });
    return this.workflows.get(workflowId);
  }

  addNode(workflowId, nodeId, node) {
    const wf = this.workflows.get(workflowId);
    if (!wf) return null;
    wf.nodes.set(nodeId, { nodeId, ...node });
    this._notify({ type: 'node_added', workflowId, nodeId });
    return wf.nodes.get(nodeId);
  }

  addEdge(workflowId, fromNodeId, toNodeId, condition = null) {
    const wf = this.workflows.get(workflowId);
    if (!wf) return null;
    wf.edges.push({ from: fromNodeId, to: toNodeId, condition });
    this._notify({ type: 'edge_added', workflowId, from: fromNodeId, to: toNodeId });
    return wf.edges[wf.edges.length - 1];
  }

  get(workflowId) {
    const wf = this.workflows.get(workflowId);
    if (!wf) return null;
    return {
      ...wf,
      nodes: Array.from(wf.nodes.entries()),
      edges: [...wf.edges]
    };
  }

  list() {
    return Array.from(this.workflows.values()).map(w => ({
      ...w,
      nodes: Array.from(w.nodes.entries()),
      edges: [...w.edges]
    }));
  }

  delete(workflowId) {
    const removed = this.workflows.delete(workflowId);
    if (removed) this._notify({ type: 'workflow_deleted', workflowId });
    return removed;
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 2. WorkflowBrancher: conditional execution paths -----
class WorkflowBrancher {
  constructor(options = {}) {
    this.options = options;
    this.branches = new Map(); // branchId -> { condition, thenPath, elsePath }
    this.subscribers = [];
  }

  define(branchId, condition, thenPath, elsePath) {
    this.branches.set(branchId, {
      branchId,
      condition,
      thenPath,
      elsePath,
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'branch_defined', branchId });
    return this.branches.get(branchId);
  }

  evaluate(branchId, context) {
    const branch = this.branches.get(branchId);
    if (!branch) return null;
    let result = false;
    try {
      if (typeof branch.condition === 'function') {
        result = !!branch.condition(context);
      } else if (branch.condition && branch.condition.key) {
        result = context[branch.condition.key] === branch.condition.value;
      }
    } catch (_) { result = false; }
    return {
      branchId,
      result,
      path: result ? branch.thenPath : branch.elsePath
    };
  }

  get(branchId) {
    return this.branches.get(branchId) || null;
  }

  list() {
    return Array.from(this.branches.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 3. WorkflowLoop: iterate over collections or until condition -----
class WorkflowLoop {
  constructor(options = {}) {
    this.options = { maxIterations: options.maxIterations || 1000, ...options };
    this.loops = new Map(); // loopId -> { collection, condition, currentIndex }
    this.subscribers = [];
  }

  define(loopId, config) {
    this.loops.set(loopId, {
      loopId,
      collection: config.collection || [],
      condition: config.condition || null,
      maxIterations: config.maxIterations || this.options.maxIterations,
      currentIndex: 0,
      iterations: 0,
      status: 'pending',
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'loop_defined', loopId });
    return this.loops.get(loopId);
  }

  iterate(loopId) {
    const loop = this.loops.get(loopId);
    if (!loop) return null;
    if (loop.iterations >= loop.maxIterations) {
      loop.status = 'max_reached';
      return { done: true, reason: 'max_iterations' };
    }
    if (loop.currentIndex >= loop.collection.length) {
      loop.status = 'completed';
      return { done: true, reason: 'collection_exhausted' };
    }
    if (loop.condition) {
      try {
        if (!loop.condition(loop.collection[loop.currentIndex], loop.iterations)) {
          loop.status = 'condition_false';
          return { done: true, reason: 'condition_false' };
        }
      } catch (_) { /* ignore */ }
    }
    const item = loop.collection[loop.currentIndex];
    loop.currentIndex++;
    loop.iterations++;
    loop.status = 'running';
    return { done: false, item, index: loop.currentIndex - 1, iteration: loop.iterations };
  }

  reset(loopId) {
    const loop = this.loops.get(loopId);
    if (!loop) return null;
    loop.currentIndex = 0;
    loop.iterations = 0;
    loop.status = 'pending';
    return loop;
  }

  get(loopId) {
    return this.loops.get(loopId) || null;
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 4. WorkflowCondition: evaluate predicates -----
class WorkflowCondition {
  constructor(options = {}) {
    this.options = options;
    this.conditions = new Map(); // conditionId -> { predicate, description }
    this.subscribers = [];
  }

  define(conditionId, predicate, description = '') {
    this.conditions.set(conditionId, {
      conditionId,
      predicate,
      description,
      createdAt: globalNativeBridge.eventTimestamp()
    });
    return this.conditions.get(conditionId);
  }

  evaluate(conditionId, context) {
    const cond = this.conditions.get(conditionId);
    if (!cond) return null;
    try {
      return { conditionId, result: !!cond.predicate(context), context };
    } catch (e) {
      return { conditionId, result: false, error: e.message };
    }
  }

  evaluateAll(conditionIds, context) {
    return conditionIds.map(id => this.evaluate(id, context));
  }

  evaluateAny(conditionIds, context) {
    for (const id of conditionIds) {
      const r = this.evaluate(id, context);
      if (r && r.result) return r;
    }
    return null;
  }

  get(conditionId) {
    return this.conditions.get(conditionId) || null;
  }

  list() {
    return Array.from(this.conditions.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 5. WorkflowParallel: fan-out concurrent execution -----
class WorkflowParallel {
  constructor(options = {}) {
    this.options = { maxConcurrency: options.maxConcurrency || 8, ...options };
    this.branches = new Map(); // branchId -> { tasks, results, status }
    this.subscribers = [];
  }

  define(branchId, tasks) {
    this.branches.set(branchId, {
      branchId,
      tasks: tasks.map((t, i) => ({ id: i, task: t, status: 'pending', result: null })),
      results: [],
      status: 'pending',
      startedAt: null,
      completedAt: null,
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'parallel_defined', branchId });
    return this.branches.get(branchId);
  }

  async execute(branchId, executor) {
    const branch = this.branches.get(branchId);
    if (!branch) return null;
    branch.status = 'running';
    branch.startedAt = globalNativeBridge.eventTimestamp();
    const results = await Promise.all(
      branch.tasks.map(async (t) => {
        try {
          t.status = 'running';
          t.result = await executor(t.task, t.id);
          t.status = 'completed';
          return { id: t.id, success: true, result: t.result };
        } catch (e) {
          t.status = 'failed';
          t.result = e.message;
          return { id: t.id, success: false, error: e.message };
        }
      })
    );
    branch.results = results;
    branch.status = results.every(r => r.success) ? 'completed' : 'partial';
    branch.completedAt = globalNativeBridge.eventTimestamp();
    this._notify({ type: 'parallel_completed', branchId, results });
    return { branchId, results, status: branch.status };
  }

  get(branchId) {
    return this.branches.get(branchId) || null;
  }

  list() {
    return Array.from(this.branches.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 6. WorkflowScheduler: cron-like scheduling -----
class WorkflowScheduler {
  constructor(options = {}) {
    this.options = options;
    this.schedules = new Map(); // scheduleId -> { workflowId, cron, nextRun, status }
    this.subscribers = [];
  }

  define(scheduleId, workflowId, cron, options = {}) {
    this.schedules.set(scheduleId, {
      scheduleId,
      workflowId,
      cron,
      intervalMs: options.intervalMs || null,
      nextRun: options.intervalMs ? globalNativeBridge.eventTimestamp() + options.intervalMs : null,
      lastRun: null,
      runCount: 0,
      status: 'active',
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'schedule_defined', scheduleId });
    return this.schedules.get(scheduleId);
  }

  tick(now = globalNativeBridge.eventTimestamp()) {
    const due = [];
    for (const [id, sched] of this.schedules.entries()) {
      if (sched.status !== 'active') continue;
      if (sched.nextRun && sched.nextRun <= now) {
        due.push(id);
        sched.lastRun = now;
        sched.runCount++;
        if (sched.intervalMs) {
          sched.nextRun = now + sched.intervalMs;
        } else {
          sched.status = 'completed';
        }
      }
    }
    if (due.length) this._notify({ type: 'schedules_due', scheduleIds: due });
    return due;
  }

  pause(scheduleId) {
    const sched = this.schedules.get(scheduleId);
    if (!sched) return null;
    sched.status = 'paused';
    return sched;
  }

  resume(scheduleId) {
    const sched = this.schedules.get(scheduleId);
    if (!sched) return null;
    sched.status = 'active';
    return sched;
  }

  get(scheduleId) {
    return this.schedules.get(scheduleId) || null;
  }

  list() {
    return Array.from(this.schedules.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 7. WorkflowTrigger: event-driven execution -----
class WorkflowTrigger {
  constructor(options = {}) {
    this.options = options;
    this.triggers = new Map(); // triggerId -> { event, workflowId, filter }
    this.subscribers = [];
  }

  define(triggerId, event, workflowId, filter = null) {
    this.triggers.set(triggerId, {
      triggerId,
      event,
      workflowId,
      filter,
      fireCount: 0,
      lastFired: null,
      status: 'active',
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'trigger_defined', triggerId });
    return this.triggers.get(triggerId);
  }

  fire(eventName, payload) {
    const fired = [];
    for (const [id, trig] of this.triggers.entries()) {
      if (trig.status !== 'active') continue;
      if (trig.event !== eventName) continue;
      if (trig.filter) {
        try {
          if (!trig.filter(payload)) continue;
        } catch (_) { continue; }
      }
      trig.fireCount++;
      trig.lastFired = globalNativeBridge.eventTimestamp();
      fired.push({ triggerId: id, workflowId: trig.workflowId, payload });
    }
    if (fired.length) this._notify({ type: 'triggers_fired', event: eventName, fired });
    return fired;
  }

  disable(triggerId) {
    const trig = this.triggers.get(triggerId);
    if (!trig) return null;
    trig.status = 'disabled';
    return trig;
  }

  enable(triggerId) {
    const trig = this.triggers.get(triggerId);
    if (!trig) return null;
    trig.status = 'active';
    return trig;
  }

  get(triggerId) {
    return this.triggers.get(triggerId) || null;
  }

  list() {
    return Array.from(this.triggers.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 8. WorkflowTemplate: reusable workflow definitions -----
class WorkflowTemplate {
  constructor(options = {}) {
    this.options = options;
    this.templates = new Map(); // templateId -> { name, definition, params }
    this.subscribers = [];
  }

  define(templateId, name, definition, params = []) {
    this.templates.set(templateId, {
      templateId,
      name,
      definition,
      params,
      useCount: 0,
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'template_defined', templateId });
    return this.templates.get(templateId);
  }

  instantiate(templateId, values = {}) {
    const tpl = this.templates.get(templateId);
    if (!tpl) return null;
    tpl.useCount++;
    const params = {};
    for (const p of tpl.params) {
      params[p.name] = p.default !== undefined ? p.default : null;
    }
    Object.assign(params, values);
    return {
      templateId,
      name: tpl.name,
      params,
      definition: tpl.definition,
      instantiatedAt: globalNativeBridge.eventTimestamp()
    };
  }

  get(templateId) {
    return this.templates.get(templateId) || null;
  }

  list() {
    return Array.from(this.templates.values());
  }

  search(query) {
    const q = (query || '').toLowerCase();
    return this.list().filter(t =>
      t.name.toLowerCase().includes(q) ||
      t.templateId.toLowerCase().includes(q)
    );
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 9. WorkflowNested: workflows within workflows -----
class WorkflowNested {
  constructor(options = {}) {
    this.options = { maxDepth: options.maxDepth || 5, ...options };
    this.nested = new Map(); // parentId -> { children: [childId, ...] }
    this.subscribers = [];
  }

  nest(parentId, childId, depth = 0) {
    if (depth >= this.options.maxDepth) return null;
    if (!this.nested.has(parentId)) {
      this.nested.set(parentId, { parentId, children: [], depth: 0 });
    }
    const parent = this.nested.get(parentId);
    if (!parent.children.includes(childId)) {
      parent.children.push(childId);
    }
    this._notify({ type: 'workflow_nested', parentId, childId });
    return parent;
  }

  getChildren(parentId) {
    const parent = this.nested.get(parentId);
    return parent ? [...parent.children] : [];
  }

  getDepth(workflowId) {
    let depth = 0;
    let current = workflowId;
    const visited = new Set();
    while (this.nested.has(current) && !visited.has(current)) {
      visited.add(current);
      depth++;
      const children = this.nested.get(current).children;
      if (children.length === 0) break;
      current = children[0];
    }
    return depth;
  }

  flatten(rootId) {
    const result = [];
    const visited = new Set();
    const stack = [rootId];
    while (stack.length) {
      const id = stack.pop();
      if (visited.has(id)) continue;
      visited.add(id);
      result.push(id);
      const children = this.getChildren(id);
      stack.push(...children);
    }
    return result;
  }

  get(parentId) {
    return this.nested.get(parentId) || null;
  }

  list() {
    return Array.from(this.nested.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 10. WorkflowPersistence: save/load workflows to disk -----
class WorkflowPersistence {
  constructor(options = {}) {
    this.options = { storageDir: options.storageDir || './workflows', ...options };
    this.records = new Map(); // workflowId -> { savedAt, path, hash }
    this.subscribers = [];
  }

  save(workflowId, workflowData) {
    const now = globalNativeBridge.eventTimestamp();
    const json = JSON.stringify(workflowData);
    const hash = globalNativeBridge.computeStateHash(json);
    const path = this.options.storageDir + '/' + workflowId + '.json';
    this.records.set(workflowId, {
      workflowId,
      path,
      hash,
      sizeBytes: json.length,
      savedAt: now
    });
    this._notify({ type: 'workflow_saved', workflowId, path });
    return this.records.get(workflowId);
  }

  load(workflowId) {
    const rec = this.records.get(workflowId);
    if (!rec) return null;
    return {
      workflowId,
      path: rec.path,
      hash: rec.hash,
      loadedAt: globalNativeBridge.eventTimestamp(),
      metadata: rec
    };
  }

  delete(workflowId) {
    const removed = this.records.delete(workflowId);
    if (removed) this._notify({ type: 'workflow_deleted_persisted', workflowId });
    return removed;
  }

  list() {
    return Array.from(this.records.values());
  }

  exists(workflowId) {
    return this.records.has(workflowId);
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

