const globalWorkflowBuilder = new WorkflowBuilder();
const globalWorkflowBrancher = new WorkflowBrancher();
const globalWorkflowLoop = new WorkflowLoop();
const globalWorkflowCondition = new WorkflowCondition();
const globalWorkflowParallel = new WorkflowParallel();
const globalWorkflowScheduler = new WorkflowScheduler();
const globalWorkflowTrigger = new WorkflowTrigger();
const globalWorkflowTemplate = new WorkflowTemplate();
const globalWorkflowNested = new WorkflowNested();
const globalWorkflowPersistence = new WorkflowPersistence();

// ----- Native hooks for Phase 15 -----
const _WorkflowBuilder_nativeComplexity = (nodes, depth) => globalNativeBridge.computeWorkflowComplexity(nodes, depth);
const _WorkflowParallel_nativeParallelism = (branches, width) => globalNativeBridge.computeWorkflowParallelism(branches, width);
const _WorkflowScheduler_nativePriority = (priority, due) => globalNativeBridge.computeWorkflowPriority(priority, due);
const _WorkflowTrigger_nativeRetryBudget = (used, max) => globalNativeBridge.computeWorkflowRetryBudget(used, max);

// ============================================================================
// PHASE 16 — PROVIDER ABSTRACTION: 10 utilities for swappable implementations
// ============================================================================
//
// Provider Abstraction handles:
//   - Provider registry (catalog of available implementations)
//   - Provider selection (pick best provider for a capability)
//   - Provider fallback (chain of alternative providers)
//   - Provider load balancing (distribute requests across providers)
//   - Provider circuit breaker (isolate failing providers)
//   - Provider health monitor (track success/failure rates)
//   - Provider capability matcher (match providers to capabilities)
//   - Provider config manager (per-provider configuration)
//   - Provider metrics collector (aggregate provider stats)
//   - Provider lifecycle manager (init/shutdown providers)

// ----- 1. ProviderRegistry: catalog of available implementations -----
class ProviderRegistry {
  constructor(options = {}) {
    this.options = options;
    this.providers = new Map(); // providerId -> { id, type, capabilities, config, status }
    this.subscribers = [];
  }

  register(providerId, provider) {
    this.providers.set(providerId, {
      providerId,
      type: provider.type || 'unknown',
      capabilities: provider.capabilities || [],
      config: provider.config || {},
      status: 'registered',
      registeredAt: globalNativeBridge.eventTimestamp(),
      ...provider
    });
    this._notify({ type: 'provider_registered', providerId });
    return this.providers.get(providerId);
  }

  unregister(providerId) {
    const removed = this.providers.delete(providerId);
    if (removed) this._notify({ type: 'provider_unregistered', providerId });
    return removed;
  }

  get(providerId) {
    return this.providers.get(providerId) || null;
  }

  list(type = null) {
    const all = Array.from(this.providers.values());
    return type ? all.filter(p => p.type === type) : all;
  }

  findByCapability(capability) {
    return Array.from(this.providers.values()).filter(p =>
      p.capabilities && p.capabilities.includes(capability)
    );
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 2. ProviderSelectorV2: pick best provider for a capability -----
class ProviderSelectorV2 {
  constructor(options = {}) {
    this.options = options;
    this.selections = new Map(); // selectionId -> { capability, providerId, score }
    this.subscribers = [];
  }

  select(capability, candidates) {
    if (!Array.isArray(candidates) || candidates.length === 0) return null;
    let best = null;
    let bestScore = -1;
    for (const c of candidates) {
      const score = globalNativeBridge.computeProviderScore(
        c.health || 50,
        c.cost || 50,
        c.latencyMs || 1000
      );
      if (score > bestScore) {
        bestScore = score;
        best = { ...c, score };
      }
    }
    const selectionId = 'sel_' + globalNativeBridge.eventTimestamp() + '_' + Math.random().toString(36).slice(2, 8);
    this.selections.set(selectionId, {
      selectionId,
      capability,
      providerId: best.providerId,
      score: bestScore,
      selectedAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'provider_selected', capability, providerId: best.providerId, score: bestScore });
    return { selectionId, capability, providerId: best.providerId, score: bestScore, provider: best };
  }

  get(selectionId) {
    return this.selections.get(selectionId) || null;
  }

  list() {
    return Array.from(this.selections.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 3. ProviderFallback: chain of alternative providers -----
class ProviderFallback {
  constructor(options = {}) {
    this.options = options;
    this.chains = new Map(); // chainId -> { providers: [providerId, ...], currentIndex }
    this.subscribers = [];
  }

  define(chainId, providerIds) {
    this.chains.set(chainId, {
      chainId,
      providers: providerIds,
      currentIndex: 0,
      attempts: 0,
      createdAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'fallback_defined', chainId });
    return this.chains.get(chainId);
  }

  async execute(chainId, executor) {
    const chain = this.chains.get(chainId);
    if (!chain) return null;
    chain.attempts = 0;
    const errors = [];
    for (let i = 0; i < chain.providers.length; i++) {
      chain.currentIndex = i;
      chain.attempts++;
      try {
        const result = await executor(chain.providers[i], i);
        this._notify({ type: 'fallback_success', chainId, providerId: chain.providers[i], attempt: i + 1 });
        return { chainId, providerId: chain.providers[i], attempt: i + 1, result };
      } catch (e) {
        errors.push({ providerId: chain.providers[i], error: e.message });
      }
    }
    this._notify({ type: 'fallback_exhausted', chainId, errors });
    return { chainId, success: false, errors };
  }

  get(chainId) {
    return this.chains.get(chainId) || null;
  }

  list() {
    return Array.from(this.chains.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 4. ProviderLoadBalancer: distribute requests across providers -----
class ProviderLoadBalancer {
  constructor(options = {}) {
    this.options = { strategy: options.strategy || 'weighted', ...options };
    this.providers = new Map(); // providerId -> { capacity, currentLoad, weight }
    this.subscribers = [];
  }

  addProvider(providerId, capacity) {
    this.providers.set(providerId, {
      providerId,
      capacity,
      currentLoad: 0,
      weight: 100,
      addedAt: globalNativeBridge.eventTimestamp()
    });
    return this.providers.get(providerId);
  }

  removeProvider(providerId) {
    return this.providers.delete(providerId);
  }

  acquire(providerId) {
    const p = this.providers.get(providerId);
    if (!p) return null;
    if (p.currentLoad >= p.capacity) return null;
    p.currentLoad++;
    p.weight = globalNativeBridge.computeLoadWeight(p.capacity, p.currentLoad);
    this._notify({ type: 'provider_acquired', providerId });
    return p;
  }

  release(providerId) {
    const p = this.providers.get(providerId);
    if (!p) return null;
    if (p.currentLoad > 0) p.currentLoad--;
    p.weight = globalNativeBridge.computeLoadWeight(p.capacity, p.currentLoad);
    this._notify({ type: 'provider_released', providerId });
    return p;
  }

  pickBest() {
    let best = null;
    let bestWeight = -1;
    for (const p of this.providers.values()) {
      if (p.currentLoad >= p.capacity) continue;
      if (p.weight > bestWeight) {
        bestWeight = p.weight;
        best = p;
      }
    }
    return best;
  }

  get(providerId) {
    return this.providers.get(providerId) || null;
  }

  list() {
    return Array.from(this.providers.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 5. ProviderCircuitBreaker: isolate failing providers -----
class ProviderCircuitBreaker {
  constructor(options = {}) {
    this.options = { threshold: options.threshold || 5, resetMs: options.resetMs || 60000, ...options };
    this.breakers = new Map(); // providerId -> { state, failures, lastFailure, openedAt }
    this.subscribers = [];
  }

  recordSuccess(providerId) {
    const b = this.breakers.get(providerId);
    if (!b) return null;
    b.failures = 0;
    b.state = 0; // closed
    return b;
  }

  recordFailure(providerId) {
    let b = this.breakers.get(providerId);
    if (!b) {
      b = { providerId, state: 0, failures: 0, lastFailure: null, openedAt: null };
      this.breakers.set(providerId, b);
    }
    b.failures++;
    b.lastFailure = globalNativeBridge.eventTimestamp();
    b.state = globalNativeBridge.computeCircuitState(b.failures, this.options.threshold);
    if (b.state === 2) {
      b.openedAt = b.lastFailure;
      this._notify({ type: 'circuit_opened', providerId });
    }
    return b;
  }

  canCall(providerId) {
    const b = this.breakers.get(providerId);
    if (!b) return true;
    if (b.state === 0) return true; // closed
    if (b.state === 2) {
      // open — check if reset time has elapsed
      if (b.openedAt && (globalNativeBridge.eventTimestamp() - b.openedAt) >= this.options.resetMs) {
        b.state = 1; // half-open
        this._notify({ type: 'circuit_half_open', providerId });
        return true;
      }
      return false;
    }
    return true; // half-open allows test calls
  }

  reset(providerId) {
    const b = this.breakers.get(providerId);
    if (!b) return null;
    b.state = 0;
    b.failures = 0;
    b.openedAt = null;
    return b;
  }

  get(providerId) {
    return this.breakers.get(providerId) || null;
  }

  list() {
    return Array.from(this.breakers.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 6. ProviderHealthMonitor: track success/failure rates -----
class ProviderHealthMonitor {
  constructor(options = {}) {
    this.options = options;
    this.healthData = new Map(); // providerId -> { success, failure, totalMs, lastCheck }
    this.subscribers = [];
  }

  recordSuccess(providerId, durationMs = 0) {
    let h = this.healthData.get(providerId);
    if (!h) {
      h = { providerId, success: 0, failure: 0, totalMs: 0, lastCheck: null, successRate: 100, avgMs: 0 };
      this.healthData.set(providerId, h);
    }
    h.success++;
    h.totalMs += durationMs;
    h.lastCheck = globalNativeBridge.eventTimestamp();
    this._updateRates(h);
    return h;
  }

  recordFailure(providerId, durationMs = 0) {
    let h = this.healthData.get(providerId);
    if (!h) {
      h = { providerId, success: 0, failure: 0, totalMs: 0, lastCheck: null, successRate: 100, avgMs: 0 };
      this.healthData.set(providerId, h);
    }
    h.failure++;
    h.totalMs += durationMs;
    h.lastCheck = globalNativeBridge.eventTimestamp();
    this._updateRates(h);
    return h;
  }

  _updateRates(h) {
    const total = h.success + h.failure;
    h.successRate = total > 0 ? Math.floor((h.success * 100) / total) : 100;
    h.avgMs = total > 0 ? Math.floor(h.totalMs / total) : 0;
  }

  health(providerId) {
    const h = this.healthData.get(providerId);
    if (!h) return null;
    return {
      providerId,
      successRate: h.successRate,
      avgMs: h.avgMs,
      total: h.success + h.failure,
      lastCheck: h.lastCheck
    };
  }

  get(providerId) {
    return this.healthData.get(providerId) || null;
  }

  list() {
    return Array.from(this.healthData.values()).map(h => ({
      providerId: h.providerId,
      successRate: h.successRate,
      avgMs: h.avgMs,
      total: h.success + h.failure,
      lastCheck: h.lastCheck
    }));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 7. ProviderCapabilityMatcher: match providers to capabilities -----
class ProviderCapabilityMatcher {
  constructor(options = {}) {
    this.options = options;
    this.matches = new Map(); // matchId -> { capability, providers, scores }
    this.subscribers = [];
  }

  match(capability, providers) {
    if (!Array.isArray(providers) || providers.length === 0) return null;
    const scored = providers.map(p => {
      const hasCap = p.capabilities && p.capabilities.includes(capability);
      const score = hasCap ? (p.score || 50) : 0;
      return { providerId: p.providerId, hasCap, score };
    }).sort((a, b) => b.score - a.score);
    const matchId = 'match_' + globalNativeBridge.eventTimestamp() + '_' + Math.random().toString(36).slice(2, 8);
    this.matches.set(matchId, {
      matchId,
      capability,
      providers: scored,
      matchedAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'capability_matched', capability, matchId });
    return { matchId, capability, providers: scored };
  }

  get(matchId) {
    return this.matches.get(matchId) || null;
  }

  list() {
    return Array.from(this.matches.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 8. ProviderConfigManager: per-provider configuration -----
class ProviderConfigManager {
  constructor(options = {}) {
    this.options = options;
    this.configs = new Map(); // providerId -> { config, version, updatedAt }
    this.subscribers = [];
  }

  set(providerId, config) {
    const existing = this.configs.get(providerId);
    const version = existing ? existing.version + 1 : 1;
    this.configs.set(providerId, {
      providerId,
      config,
      version,
      updatedAt: globalNativeBridge.eventTimestamp()
    });
    this._notify({ type: 'config_updated', providerId, version });
    return this.configs.get(providerId);
  }

  get(providerId) {
    const c = this.configs.get(providerId);
    return c ? { ...c, config: { ...c.config } } : null;
  }

  merge(providerId, partial) {
    const c = this.configs.get(providerId);
    if (!c) return this.set(providerId, partial);
    return this.set(providerId, { ...c.config, ...partial });
  }

  delete(providerId) {
    const removed = this.configs.delete(providerId);
    if (removed) this._notify({ type: 'config_deleted', providerId });
    return removed;
  }

  list() {
    return Array.from(this.configs.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 9. ProviderMetricsCollector: aggregate provider stats -----
class ProviderMetricsCollector {
  constructor(options = {}) {
    this.options = options;
    this.metrics = new Map(); // providerId -> { calls, errors, totalMs, p95Ms, lastReset }
    this.subscribers = [];
  }

  recordCall(providerId, durationMs, success) {
    let m = this.metrics.get(providerId);
    if (!m) {
      m = { providerId, calls: 0, errors: 0, totalMs: 0, samples: [], p95Ms: 0, lastReset: globalNativeBridge.eventTimestamp() };
      this.metrics.set(providerId, m);
    }
    m.calls++;
    if (!success) m.errors++;
    m.totalMs += durationMs;
    m.samples.push(durationMs);
    if (m.samples.length > 100) m.samples.shift();
    // Compute p95
    if (m.samples.length > 0) {
      const sorted = [...m.samples].sort((a, b) => a - b);
      const idx = Math.floor(sorted.length * 0.95);
      m.p95Ms = sorted[Math.min(idx, sorted.length - 1)];
    }
    return m;
  }

  reset(providerId) {
    const m = this.metrics.get(providerId);
    if (!m) return null;
    m.calls = 0;
    m.errors = 0;
    m.totalMs = 0;
    m.samples = [];
    m.p95Ms = 0;
    m.lastReset = globalNativeBridge.eventTimestamp();
    return m;
  }

  summary(providerId) {
    const m = this.metrics.get(providerId);
    if (!m) return null;
    return {
      providerId,
      calls: m.calls,
      errors: m.errors,
      errorRate: m.calls > 0 ? Math.floor((m.errors * 100) / m.calls) : 0,
      avgMs: m.calls > 0 ? Math.floor(m.totalMs / m.calls) : 0,
      p95Ms: m.p95Ms
    };
  }

  get(providerId) {
    return this.metrics.get(providerId) || null;
  }

  list() {
    return Array.from(this.metrics.keys()).map(id => this.summary(id));
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- 10. ProviderLifecycleManager: init/shutdown providers -----
class ProviderLifecycleManager {
  constructor(options = {}) {
    this.options = options;
    this.lifecycle = new Map(); // providerId -> { state, initAt, shutdownAt, hooks }
    this.subscribers = [];
  }

  init(providerId, initFn) {
    const entry = {
      providerId,
      state: 'initializing',
      initAt: globalNativeBridge.eventTimestamp(),
      shutdownAt: null,
      hooks: { init: initFn || null }
    };
    this.lifecycle.set(providerId, entry);
    try {
      if (typeof initFn === 'function') initFn();
      entry.state = 'active';
    } catch (e) {
      entry.state = 'failed';
      entry.error = e.message;
    }
    this._notify({ type: 'provider_initialized', providerId, state: entry.state });
    return entry;
  }

  shutdown(providerId, shutdownFn) {
    const entry = this.lifecycle.get(providerId);
    if (!entry) return null;
    entry.state = 'shutting_down';
    try {
      if (typeof shutdownFn === 'function') shutdownFn();
      entry.state = 'shutdown';
      entry.shutdownAt = globalNativeBridge.eventTimestamp();
    } catch (e) {
      entry.state = 'shutdown_failed';
      entry.error = e.message;
    }
    this._notify({ type: 'provider_shutdown', providerId, state: entry.state });
    return entry;
  }

  restart(providerId, initFn, shutdownFn) {
    this.shutdown(providerId, shutdownFn);
    return this.init(providerId, initFn);
  }

  get(providerId) {
    return this.lifecycle.get(providerId) || null;
  }

  list() {
    return Array.from(this.lifecycle.values());
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    return this;
  }

  _notify(event) {
    for (const cb of this.subscribers) {
      try { cb(event); } catch (_) { /* ignore */ }
    }
  }
}

// ----- Global instances -----
const globalProviderRegistry = new ProviderRegistry();
const globalProviderSelectorV2 = new ProviderSelectorV2();
const globalProviderFallback = new ProviderFallback();
const globalProviderLoadBalancer = new ProviderLoadBalancer();
const globalProviderCircuitBreaker = new ProviderCircuitBreaker();
const globalProviderHealthMonitor = new ProviderHealthMonitor();
const globalProviderCapabilityMatcher = new ProviderCapabilityMatcher();
const globalProviderConfigManager = new ProviderConfigManager();
const globalProviderMetricsCollector = new ProviderMetricsCollector();
const globalProviderLifecycleManager = new ProviderLifecycleManager();

// ----- Native hooks for Phase 16 -----
const _ProviderSelector_nativeScore = (health, cost, latency) => globalNativeBridge.computeProviderScore(health, cost, latency);
const _ProviderFallback_nativeDepth = (chain, reliability) => globalNativeBridge.computeFallbackDepth(chain, reliability);
const _ProviderLoadBalancer_nativeWeight = (capacity, load) => globalNativeBridge.computeLoadWeight(capacity, load);
const _ProviderCircuitBreaker_nativeState = (failures, threshold) => globalNativeBridge.computeCircuitState(failures, threshold);

// ============================================================================
// PHASE 17 — AGENT RUNTIME: 10 utilities that tie the runtime together
// ============================================================================
// AgentRuntime orchestrates: Intent -> Context -> Plan -> Graph -> Registry ->
// Runtime -> Skills -> Observe -> Verify -> Recover -> Memory -> Complete

class IntentEngine {
  constructor(options = {}) {
    this.options = options;
    this.patterns = [
      { regex: /open\s+(chrome|edge|firefox|browser)/i, name: 'browser_open', risk: 1 },
      { regex: /search\s+(.+)/i, name: 'browser_search', risk: 1 },
      { regex: /close\s+(chrome|edge|firefox|browser)/i, name: 'browser_close', risk: 1 },
      { regex: /delete\s+(file\s+)?(.+)/i, name: 'file_delete', risk: 3 },
      { regex: /move\s+(.+)\s+to\s+(.+)/i, name: 'file_move', risk: 2 },
      { regex: /list\s+(files|directory)/i, name: 'file_list', risk: 0 },
      { regex: /check\s+(status|system|memory|disk)/i, name: 'system_status', risk: 0 },
      { regex: /login\s+(to\s+)?(.+)/i, name: 'auth_login', risk: 3 },
      { regex: /download\s+(.+)/i, name: 'download_file', risk: 2 },
      { regex: /run\s+(.+)/i, name: 'system_run', risk: 4 },
    ];
  }

  classify(request) {
    const text = (typeof request === 'string') ? request : ((request && request.text) || '');
    for (const p of this.patterns) {
      const m = text.match(p.regex);
      if (m) {
        return {
          name: p.name,
          risk: p.risk,
          confidence: 0.9,
          match: m[0],
          groups: m.slice(1),
          timestamp: Date.now(),
        };
      }
    }
    return {
      name: 'unknown',
      risk: 0,
      confidence: 0.0,
      match: text,
      groups: [],
      timestamp: Date.now(),
    };
  }
}

class ContextEngine {
  constructor(options = {}) {
    this.options = options;
    this.snapshot = {};
  }

  gather(request) {
    const ctx = {
      timestamp: Date.now(),
      request: request || {},
      intent: request && request.intent ? request.intent : null,
      environment: {
        platform: process.platform,
        nodeVersion: process.version,
        pid: process.pid,
      },
      memory: {
        shortTerm: (globalShortTermMemory && typeof globalShortTermMemory.snapshot === 'function') ? globalShortTermMemory.snapshot() : {},
        longTerm: (globalLongTermMemory && typeof globalLongTermMemory.snapshot === 'function') ? globalLongTermMemory.snapshot() : {},
      },
      resources: (globalResourceState && typeof globalResourceState.snapshot === 'function') ? globalResourceState.snapshot() : {},
    };
    this.snapshot = ctx;
    return ctx;
  }
}

class RuntimePlanner {
  constructor(options = {}) {
    this.options = options;
  }

  createPlan(intent, context) {
    const steps = [];
    const intentName = (intent && intent.name) || 'unknown';
    const risk = (intent && intent.risk) || 0;

    steps.push({ type: 'observe', tool: 'context.gather', risk: 0 });

    if (intentName === 'browser_open') {
      steps.push({ type: 'act', tool: 'system.open_app', risk: 1, args: { app: 'chrome' } });
    } else if (intentName === 'browser_search') {
      steps.push({ type: 'act', tool: 'browser.search', risk: 1, args: { query: intent.groups[0] } });
    } else if (intentName === 'browser_close') {
      steps.push({ type: 'act', tool: 'browser.close', risk: 1 });
    } else if (intentName === 'file_delete') {
      steps.push({ type: 'act', tool: 'file.quarantine', risk: 3, args: { path: intent.groups[1] } });
    } else if (intentName === 'file_move') {
      steps.push({ type: 'act', tool: 'file.move', risk: 2, args: { src: intent.groups[0], dst: intent.groups[1] } });
    } else if (intentName === 'file_list') {
      steps.push({ type: 'act', tool: 'file.list', risk: 0 });
    } else if (intentName === 'system_status') {
      steps.push({ type: 'act', tool: 'system.status', risk: 0 });
    } else if (intentName === 'auth_login') {
      steps.push({ type: 'act', tool: 'auth.password_login', risk: 3, args: { site: intent.groups[1] } });
    } else if (intentName === 'download_file') {
      steps.push({ type: 'act', tool: 'download.file', risk: 2, args: { url: intent.groups[0] } });
    } else if (intentName === 'system_run') {
      steps.push({ type: 'act', tool: 'system.run_command', risk: 4, args: { command: intent.groups[0] } });
    } else {
      steps.push({ type: 'act', tool: 'agent.echo', risk: 0, args: { text: 'unknown intent' } });
    }

    steps.push({ type: 'verify', tool: 'verify.result', risk: 0 });
    steps.push({ type: 'finish', risk: 0 });

    return {
      intent: intentName,
      risk,
      steps,
      context: context || null,
      createdAt: Date.now(),
    };
  }
}

class RuntimeExecutionGraphBuilder {
  constructor(options = {}) {
    this.options = options;
  }

  build(steps) {
    const nodes = [];
    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      const node = {
        id: 'n' + (i + 1),
        type: step.type,
        tool: step.tool || null,
        risk: step.risk || 0,
        args: step.args || {},
        status: 'pending',
      };
      // Auto-insert approval node before high-risk actions
      if (step.type === 'act' && (step.risk || 0) >= 3) {
        nodes.push({
          id: 'approval_' + node.id,
          type: 'approval',
          tool: 'approval.request',
          risk: 0,
          args: { action: step.tool, target: step.args },
          status: 'pending',
        });
      }
      nodes.push(node);
    }
    return {
      nodes,
      edges: this._buildEdges(nodes),
      createdAt: Date.now(),
    };
  }

  _buildEdges(nodes) {
    const edges = [];
    for (let i = 0; i < nodes.length - 1; i++) {
      edges.push({ from: nodes[i].id, to: nodes[i + 1].id });
    }
    return edges;
  }
}

class PipelineRegistryBridge {
  constructor(options = {}) {
    this.options = options;
    this.pipelines = new Map();
  }

  register(name, definition) {
    this.pipelines.set(name, { name, definition, registeredAt: Date.now() });
    return this.pipelines.get(name);
  }

  unregister(name) {
    return this.pipelines.delete(name);
  }

  get(name) {
    return this.pipelines.get(name);
  }

  list() {
    return Array.from(this.pipelines.values());
  }

  findByCapability(capability) {
    return this.list().filter(p => {
      const steps = (p.definition && p.definition.steps) || [];
      return steps.some(s => s.includes(capability));
    });
  }
}

class RuntimeExecutionEngine {
  constructor(options = {}) {
    this.options = options;
    this.executions = [];
  }

  execute(graph) {
    const nodes = (graph && graph.nodes) || [];
    const results = [];
    for (const node of nodes) {
      const result = {
        id: node.id,
        type: node.type,
        tool: node.tool,
        status: 'completed',
        executedAt: Date.now(),
      };
      results.push(result);
    }
    const execution = {
      graph,
      results,
      status: 'completed',
      startedAt: Date.now(),
      completedAt: Date.now(),
    };
    this.executions.push(execution);
    return execution;
  }

  history() {
    return this.executions;
  }
}

class SkillOrchestratorBridge {
  constructor(options = {}) {
    this.options = options;
  }

  orchestrate(request) {
    const intent = (request && request.intent) || 'unknown';
    const requestedSkills = (request && request.skills) || [];
    const skills = [];

    if (requestedSkills.length > 0) {
      for (const s of requestedSkills) {
        skills.push({ id: s, status: 'queued', intent });
      }
    } else {
      // Auto-select skills based on intent
      const intentToSkill = {
        browser_open: ['open_chrome', 'verify_window'],
        browser_search: ['browser_search', 'extract_results'],
        file_delete: ['file_quarantine', 'verify_quarantine'],
        system_status: ['system_status', 'format_report'],
      };
      const candidates = intentToSkill[intent] || ['meta_echo'];
      for (const s of candidates) {
        skills.push({ id: s, status: 'queued', intent });
      }
    }

    return {
      intent,
      skills,
      orchestratedAt: Date.now(),
    };
  }
}

class ObservationEngineBridge {
  constructor(options = {}) {
    this.options = options;
    this.observations = [];
  }

  observe(request) {
    const obs = {
      stage: (request && request.stage) || 'unknown',
      timestamp: Date.now(),
      data: (request && request.data) || null,
      source: 'runtime',
    };
    this.observations.push(obs);
    return obs;
  }

  recent(n = 10) {
    return this.observations.slice(-n);
  }
}

class VerificationEngineBridge {
  constructor(options = {}) {
    this.options = options;
  }

  verify(request) {
    const stage = (request && request.stage) || 'unknown';
    const observation = (request && request.observation) || {};
    const observedStatus = observation.status || (observation.data && observation.data.status);
    const passed = observedStatus === 'ok' || observedStatus === 'completed';
    return {
      stage,
      passed,
      observation,
      verifiedAt: Date.now(),
    };
  }
}

class RecoveryEngineBridge {
  constructor(options = {}) {
    this.options = options;
    this.policies = {
      timeout: { action: 'retry', attempts: 3 },
      network: { action: 'retry', attempts: 5 },
      permission: { action: 'abort' },
      validation: { action: 'abort' },
      crash: { action: 'rollback' },
      not_found: { action: 'replan' },
      unknown: { action: 'retry', attempts: 1 },
    };
  }

  classify(error) {
    const msg = (error && error.message) || String(error || '');
    if (/timeout/i.test(msg)) return 'timeout';
    if (/network|ECONN|fetch/i.test(msg)) return 'network';
    if (/permission|denied|forbidden/i.test(msg)) return 'permission';
    if (/validation|invalid/i.test(msg)) return 'validation';
    if (/crash|segfault/i.test(msg)) return 'crash';
    if (/not found|missing/i.test(msg)) return 'not_found';
    return 'unknown';
  }

  recover(request) {
    const error = request && request.error;
    const category = this.classify(error);
    const policy = this.policies[category] || this.policies.unknown;
    return {
      stage: (request && request.stage) || 'unknown',
      category,
      action: policy.action,
      attempts: policy.attempts || 1,
      error: error || null,
      recoveredAt: Date.now(),
    };
  }
}

class MemoryUpdateBridge {
  constructor(options = {}) {
    this.options = options;
    this.updates = [];
  }

  update(request) {
    const stage = (request && request.stage) || 'unknown';
    const result = (request && request.result) || {};
    const key = (request && request.key) || ('runtime.' + stage + '.' + Date.now());
    const update = {
      key,
      stage,
      value: result,
      storedAt: Date.now(),
    };
    this.updates.push(update);
    if (globalLongTermMemory) {
      globalLongTermMemory.store(key, result, { importance: 50, tags: ['runtime', stage] });
    }
    return { ...update, stored: true };
  }

  recent(n = 10) {
    return this.updates.slice(-n);
  }
}

class AgentRuntime {
  constructor(options = {}) {
    this.options = options;
    this.intentEngine = new IntentEngine();
    this.contextEngine = new ContextEngine();
    this.planner = new RuntimePlanner();
    this.executionGraph = new RuntimeExecutionGraphBuilder();
    this.pipelineRegistry = new PipelineRegistryBridge();
    this.executionRuntime = new RuntimeExecutionEngine();
    this.skillOrchestrator = new SkillOrchestratorBridge();
    this.observationEngine = new ObservationEngineBridge();
    this.verificationEngine = new VerificationEngineBridge();
    this.recoveryEngine = new RecoveryEngineBridge();
    this.memoryUpdate = new MemoryUpdateBridge();
    this.history = [];
  }

  processRequest(request) {
    const stages = [];
    let error = null;

    try {
      // 1. Intent
      const intent = this.intentEngine.classify(request);
      stages.push('intent');

      // 2. Context
      const context = this.contextEngine.gather({ ...request, intent });
      stages.push('context');

      // 3. Plan
      const plan = this.planner.createPlan(intent, context);
      stages.push('plan');

      // 4. Execution Graph
      const graph = this.executionGraph.build(plan.steps);
      stages.push('graph');

      // 5. Pipeline Registry
      this.pipelineRegistry.register('runtime_' + Date.now(), { steps: plan.steps });
      stages.push('registry');

      // 6. Execution Runtime
      const execution = this.executionRuntime.execute(graph);
      stages.push('runtime');

      // 7. Skill Orchestrator
      const orchestration = this.skillOrchestrator.orchestrate({ intent: intent.name });
      stages.push('skills');

      // 8. Observation
      const observation = this.observationEngine.observe({ stage: 'runtime', data: execution });
      stages.push('observe');

      // 9. Verification
      const verification = this.verificationEngine.verify({ stage: 'runtime', observation });
      stages.push('verify');

      // 10. Recovery (only if verification failed)
      if (!verification.passed) {
        const recovery = this.recoveryEngine.recover({ stage: 'runtime', error: 'verification_failed' });
        stages.push('recover');
      } else {
        stages.push('recover');
      }

      // 11. Memory Update
      const memory = this.memoryUpdate.update({ stage: 'runtime', result: execution, key: 'last_runtime' });
      stages.push('memory');

      // 12. Complete
      stages.push('complete');

      const result = {
        request,
        intent,
        context,
        plan,
        graph,
        execution,
        orchestration,
        observation,
        verification,
        memory,
        stages,
        status: 'completed',
        completedAt: Date.now(),
      };
      this.history.push(result);
      return result;
    } catch (e) {
      error = e;
      const recovery = this.recoveryEngine.recover({ stage: 'runtime', error: e });
      stages.push('recover');
      const result = {
        request,
        error: e.message,
        recovery,
        stages,
        status: 'failed',
        completedAt: Date.now(),
      };
      this.history.push(result);
      return result;
    }
  }
}

